function clampCoreStats(st) {
  const target = st || (typeof state !== 'undefined' ? state : null);
  if (!target) return;
  if (typeof lifeCycleEngine !== 'undefined' && lifeCycleEngine && typeof lifeCycleEngine.clampStats === 'function') {
    lifeCycleEngine.clampStats(target);
    return target;
  }
  const boundedKeys = Object.keys(CORE_BOUNDED_STATS);
  for (let i = 0; i < boundedKeys.length; i++) {
    const k = boundedKeys[i];
    if (typeof target[k] === 'number' && !Number.isNaN(target[k])) {
      const cfg = CORE_BOUNDED_STATS[k];
      const maxCap = (k === 'iq' && target && target.clanIqCapBonus) ? (cfg.max + target.clanIqCapBonus) : cfg.max;
      target[k] = Math.max(cfg.min, Math.min(maxCap, Math.round(target[k])));
    }
  }
  if ((target.age || 0) < 18) {
    target.govLevel = 0;
    target.rankIndex = 0;
    target.lifetimeMaxRank = 0;
  } else if (typeof target.govLevel === 'number' || typeof target.rankIndex === 'number') {
    const lvl = Math.max(1, Math.min(5, Math.round(target.govLevel || target.rankIndex || 1)));
    target.govLevel = lvl;
    target.rankIndex = lvl;
    target.lifetimeMaxRank = Math.max(target.lifetimeMaxRank || 1, lvl);
  }
}

// 关键节点埋点与全链路数据上报引擎 (Funnel & Telemetry Engine)
