const EMOJI_REGEX = /[\u{1F300}-\u{1F9FF}\u{1FA00}-\u{1FAFF}\u{2600}-\u{26FF}\u{FE00}-\u{FE0F}]/gu;

function cleanEmojiForAncientUI(str) {
  if (!str) return str;
  if (typeof str !== 'string') str = String(str);
  for (const [em, rep] of Object.entries(EMOJI_ANCIENT_MAP)) {
    if (str.includes(em)) {
      str = str.split(em).join(rep);
    }
  }
  return str.replace(EMOJI_REGEX, '').trim();
}

function wrapCanvasContextFont(rawCtx) {
  if (!rawCtx) return rawCtx;

  // 1. 确保 Canvas 原生 ellipse 在缺乏支持的小程序/小游戏环境中平稳降级
  try {
    if (typeof rawCtx.ellipse !== 'function') {
      rawCtx.ellipse = function(x, y, radiusX, radiusY, rotation, startAngle, endAngle, counterclockwise) {
        this.save();
        this.translate(x, y);
        if (rotation) this.rotate(rotation);
        this.scale(Math.max(0.001, Math.abs(radiusX)), Math.max(0.001, Math.abs(radiusY)));
        this.arc(0, 0, 1, startAngle || 0, endAngle !== undefined ? endAngle : Math.PI * 2, counterclockwise);
        this.restore();
      };
    }
  } catch (_) {}

  // 2. 全局古典宣纸文本防豆腐块净化拦截器 (Render Sanitizer Shield)
  try {
    if (typeof rawCtx.fillText === 'function' && !rawCtx._emojiSanitized) {
      const _origFillText = rawCtx.fillText;
      rawCtx.fillText = function(text, x, y, maxWidth) {
        if (typeof text === 'string') {
          text = cleanEmojiForAncientUI(text);
        }
        if (maxWidth !== undefined) {
          return _origFillText.call(this, text, x, y, maxWidth);
        } else {
          return _origFillText.call(this, text, x, y);
        }
      };
      const _origMeasureText = rawCtx.measureText;
      rawCtx.measureText = function(text) {
        if (typeof text === 'string') {
          text = cleanEmojiForAncientUI(text);
        }
        return _origMeasureText.call(this, text);
      };
      rawCtx._emojiSanitized = true;
    }
  } catch (_) {}

  return rawCtx;
}

