// ==========================================
let screenShakeX = 0;
let screenShakeY = 0;
let screenShakeTime = 0;
let screenShakeMag = 6;

function triggerScreenShake(magnitude, durationMs) {
  screenShakeTime = durationMs || 220;
  screenShakeMag = magnitude || 6;
}

// 常驻 40 颗丁达尔浮动金粉微粒 (更密集而空灵的历史微尘)
const ambientMotes = [];
for (let i = 0; i < 40; i++) {
  ambientMotes.push({
    x: fxRandom() * screenWidth,
    y: fxRandom() * screenHeight,
    radius: 0.8 + fxRandom() * 1.8,
    speedY: -0.15 - fxRandom() * 0.3,
    speedX: (fxRandom() - 0.5) * 0.18,
    baseAlpha: 0.15 + fxRandom() * 0.45,
    phase: fxRandom() * Math.PI * 2
  });
}

// 墨泥朱砂粒子池
let inkParticles = [];
function spawnDustParticles(x, y, color, count) {
  for (let i = 0; i < count; i++) {
    const angle = fxRandom() * Math.PI * 2;
    const spd = 1.5 + fxRandom() * 4.5;
    inkParticles.push(obtainPooledParticle((obj) => {
      obj.x = x;
      obj.y = y;
      obj.vx = Math.cos(angle) * spd;
      obj.vy = Math.sin(angle) * spd;
      obj.radius = 1.2 + fxRandom() * 2.5;
      obj.alpha = 0.95;
      obj.decay = 0.02 + fxRandom() * 0.03;
      obj.color = color || '#ef4444';
    }));
  }
}

// 浮空文字队列
let floatingTexts = [];
function addFloatingText(text, x, y, color) {
  let targetX = x;
  let targetY = y;
  const isDefaultCoord = targetX === undefined || targetY === undefined ||
    (typeof screenWidth === 'number' && Math.abs(targetX - screenWidth / 2) < 4 && Math.abs(targetY - (getDashboardY() + 40)) < 15);
  if (isDefaultCoord) {
    if (typeof lastTouchX === 'number' && lastTouchX > 0 && typeof lastTouchY === 'number' && lastTouchY > 0) {
      targetX = Math.max(30, Math.min((screenWidth || 375) - 30, lastTouchX));
      targetY = Math.max(70, Math.min((screenHeight || 667) - 60, lastTouchY - 22));
    } else {
      targetX = (screenWidth || 375) / 2;
      targetY = (screenHeight || 667) * 0.45;
    }
  }
  floatingTexts.push(obtainPooledParticle((obj) => {
    obj.text = text;
    obj.x = targetX;
    obj.y = targetY;
    obj.vy = -1.2;
    obj.alpha = 1.0;
    obj.color = color || '#f59e0b';
  }));
}

// 🖋️ V25 动态水墨晕染涟漪引擎 (Ink Wash Ripple Fluid Engine)
let touchRipples = [];
function addTouchRipple(x, y, color = null) {
  const sIdx = Math.abs((state.year || 1980) % 4);
  const seasonInkColors = ['#fb7185', '#f59e0b', '#d97706', '#60a5fa'];
  const inkColor = color || seasonInkColors[sIdx];
  touchRipples.push({
    x: x,
    y: y,
    radius: 3,
    maxRadius: 42,
    alpha: 0.85,
    color: inkColor,
    droplets: [
      { dx: (seededRandom() - 0.5) * 12, dy: (seededRandom() - 0.5) * 12, r: 1.4 + seededRandom() * 1.6 },
      { dx: (seededRandom() - 0.5) * 18, dy: (seededRandom() - 0.5) * 18, r: 1.0 + seededRandom() * 1.3 },
      { dx: (seededRandom() - 0.5) * 24, dy: (seededRandom() - 0.5) * 24, r: 0.8 + seededRandom() * 1.0 }
    ]
  });
  if (touchRipples.length > 18) touchRipples.shift();
}

// 岁序时光流转翻转动画 (Year Flip & Time-Stream Transition)
let yearFlipAnim = {
  active: false,
  fromYear: null,
  toYear: null,
  fromAge: null,
  toAge: null,
  progress: 1.0
};

function triggerYearFlipAnim(fromYear, toYear, fromAge, toAge) {
  if (fromYear === toYear && fromAge === toAge) return;
  yearFlipAnim.active = true;
  yearFlipAnim.fromYear = fromYear;
  yearFlipAnim.toYear = toYear;
  yearFlipAnim.fromAge = fromAge;
  yearFlipAnim.toAge = toAge;
  yearFlipAnim.progress = 0.0;
  triggerTimeStreamFX();
  requestRender();
}

let timeStreamFX = {
  active: false,
  alpha: 0.0
};

function triggerTimeStreamFX() {
  timeStreamFX.active = true;
  timeStreamFX.alpha = 0.14;
}

