// ==========================================
// ==========================================
// 四、 字体排版与中式国风视觉装帧规范系统 (Design System)
// ==========================================
const FONT_CHRONICLE = '"Songti SC", "Source Han Serif SC", "Noto Serif CJK SC", "STSong", "SimSun", "FangSong", "KaiTi", "Georgia", serif';
const FONT_UI = FONT_CHRONICLE;
const FONT_MONO = '"SF Mono", "Menlo", "Consolas", "Roboto Mono", "Courier New", monospace';

// ----------------------------------------------------
// 1. 字体层级规范令牌 (Typography Scale Tokens)
// ----------------------------------------------------
const TYPOGRAPHY = {
  // L1 Display / Hero: 终局宏大盖棺定论、游戏大标题、历史剧变
  hero: { size: 20, weight: 'bold', family: FONT_CHRONICLE, lineHeight: 28, desc: '主视觉大标题' },
  // L2 Title Large: 模态弹窗主标题、年度大考大标题、章节关口
  titleL: { size: 16.5, weight: 'bold', family: FONT_CHRONICLE, lineHeight: 24, desc: '弹窗主标题' },
  // L3 Title Medium: 选项标题、名仕姓名、身份初度命盘
  titleM: { size: 14.5, weight: 'bold', family: FONT_CHRONICLE, lineHeight: 21, desc: '模块与交互主标题' },
  // L4 Title Small / Subhead: 选项内细分标题、子卡片顶栏、官职头衔
  titleS: { size: 13.5, weight: 'bold', family: FONT_CHRONICLE, lineHeight: 19, desc: '次级醒目标题' },
  // L5 Body Regular: 剧情叙事文本、事件背景、生平小传主文
  body: { size: 13, weight: 'normal', family: FONT_CHRONICLE, lineHeight: 19, desc: '剧情叙事主正文' },
  // L6 Body Secondary: 选项后果预测、次级说明、辅助解释
  bodySecondary: { size: 12, weight: 'normal', family: FONT_CHRONICLE, lineHeight: 17, desc: '次要解释文本' },
  // L7 Caption / Metadata: 提示小字、时间消耗、门楣家风底注
  caption: { size: 11, weight: 'normal', family: FONT_CHRONICLE, lineHeight: 15, desc: '元数据与注释' },
  // L8 Micro Badge: 状态标签、节气印泥小胶囊、微型标签
  badge: { size: 10.5, weight: 'bold', family: FONT_CHRONICLE, lineHeight: 14, desc: '徽章与状态胶囊' },
  // 数值/统计等宽字族 (Tabular / Monospace)
  statL: { size: 17, weight: 'bold', family: FONT_MONO, lineHeight: 22, desc: '核心大字得分' },
  statM: { size: 13, weight: 'bold', family: FONT_MONO, lineHeight: 18, desc: '属性与资本' },
  statS: { size: 10, weight: 'bold', family: FONT_MONO, lineHeight: 14, desc: '胜率拆解公式条' }
};

/**
 * 统一获取符合规范的字体 CSS 字符串
 * @param {string|object} token TYPOGRAPHY key (e.g. 'titleL') 或自定义配置/字体字符串
 * @param {string} [overrideFamily] 可选强制替换字族
 * @returns {string} 可直接赋予 ctx.font 的标准化字号字符串
 */
function getTypographyFont(token, overrideFamily) {
  if (typeof token === 'string' && TYPOGRAPHY[token]) {
    const t = TYPOGRAPHY[token];
    const fam = overrideFamily || t.family;
    const wt = t.weight ? (t.weight + ' ') : '';
    return `${wt}${t.size}px ${fam}`;
  }
  if (typeof token === 'string') return token;
  if (typeof token === 'object' && token.size) {
    const fam = overrideFamily || token.family || FONT_CHRONICLE;
    const wt = token.weight ? (token.weight + ' ') : '';
    return `${wt}${token.size}px ${fam}`;
  }
  return '13px ' + FONT_CHRONICLE;
}

