/**
 * 绘制图符与文本紧密对齐组合 (Icon & Label Inline Pair)
 * 自动规范图符与文本的间距与垂直对齐，杜绝平台基准线漂移
 */
function drawIconTextPair(context, x, y, icon, text, fontToken, textColor, maxWidth) {
  if (!context || !text) return 0;
  const fontStr = getTypographyFont(fontToken || 'body');
  const effFont = elevateFontSize(fontStr, 10);
  context.save();
  context.font = effFont;
  context.textBaseline = 'top';

  let curX = x;
  if (icon) {
    context.fillStyle = '#ffffff';
    context.fillText(icon, curX, y);
    const iconW = context.measureText(icon).width;
    curX += iconW + ICON_SPEC.sizes.inlineSpacing;
  }

  context.fillStyle = textColor || COLOR_TOKENS.text.primary;
  const availW = maxWidth ? Math.max(20, maxWidth - (curX - x)) : undefined;
  const outText = availW ? fitText(String(text), availW, effFont) : String(text);
  context.fillText(outText, curX, y);
  const totalW = (curX - x) + context.measureText(outText).width;
  context.restore();
  return totalW;
}

function formatCurrency(amount, customYear) {
  const num = Number(amount) || 0;
  const currentYear = (typeof customYear === 'number') ? customYear : (typeof state !== 'undefined' && state && typeof state.year === 'number' ? state.year : 100);
  const isS1 = currentYear <= 500;
  const prefix = isS1 ? '' : '¥';
  const suffix = isS1 ? '钱' : '';
  if (Math.abs(num) >= 100000000) {
    return prefix + (num / 100000000).toFixed(2) + '亿' + suffix;
  } else if (Math.abs(num) >= 10000) {
    return prefix + (num / 10000).toFixed(1) + '万' + suffix;
  } else {
    return prefix + Math.round(num) + (isS1 ? '五铢钱' : '');
  }
}

function formatHudCapital(amount, customYear) {
  const num = Number(amount) || 0;
  const yr = (typeof customYear === 'number') ? customYear : (typeof state !== 'undefined' && state && typeof state.year === 'number' ? state.year : 100);
  const isHanWei = yr <= 500;
  const prefix = isHanWei ? '' : '¥';
  if (Math.abs(num) >= 100000000) {
    return prefix + (num / 100000000).toFixed(1) + '亿';
  } else if (Math.abs(num) >= 10000) {
    return prefix + (num / 10000).toFixed(1) + '万';
  } else {
    return prefix + Math.round(num).toLocaleString();
  }
}

function drawCornerOrnaments(context, x, y, w, h, len, color) {
  if (w <= 0 || h <= 0) return;
  context.save();
  const cColor = color || '#f59e0b';
  context.strokeStyle = cColor;
  context.lineWidth = 1.4;
  const l = Math.max(6, len || 8);

  // 外层如意直角折线
  context.beginPath();
  // 左上
  context.moveTo(x + 2, y + l + 2);
  context.lineTo(x + 2, y + 2);
  context.lineTo(x + l + 2, y + 2);
  // 右上
  context.moveTo(x + w - l - 2, y + 2);
  context.lineTo(x + w - 2, y + 2);
  context.lineTo(x + w - 2, y + l + 2);
  // 左下
  context.moveTo(x + 2, y + h - l - 2);
  context.lineTo(x + 2, y + h - 2);
  context.lineTo(x + l + 2, y + h - 2);
  // 右下
  context.moveTo(x + w - l - 2, y + h - 2);
  context.lineTo(x + w - 2, y + h - 2);
  context.lineTo(x + w - 2, y + h - l - 2);
  context.stroke();

  // 内角回字点睛微点 (如意回纹古珠)
  if (l >= 6) {
    context.fillStyle = cColor;
    const dotR = 1.2;
    context.beginPath(); context.arc(x + 5.5, y + 5.5, dotR, 0, Math.PI * 2); context.fill();
    context.beginPath(); context.arc(x + w - 5.5, y + 5.5, dotR, 0, Math.PI * 2); context.fill();
    context.beginPath(); context.arc(x + 5.5, y + h - 5.5, dotR, 0, Math.PI * 2); context.fill();
    context.beginPath(); context.arc(x + w - 5.5, y + h - 5.5, dotR, 0, Math.PI * 2); context.fill();
  }
  context.restore();
}

const SEAL_OFFSCREEN_CACHE = new Map();

function drawSealDirect(context, cx, cy, text, sub, radius) {
  const r = radius || 38;
  context.save();
  context.translate(cx, cy);
  context.rotate(-0.12);

  // 外同心双圈
  context.strokeStyle = '#dc2626';
  context.lineWidth = 2.5;
  context.beginPath();
  context.arc(0, 0, r, 0, Math.PI * 2);
  context.stroke();

  context.lineWidth = 1.0;
  context.beginPath();
  context.arc(0, 0, r - 3.5, 0, Math.PI * 2);
  context.stroke();

  // 五角星徽
  context.fillStyle = '#dc2626';
  context.beginPath();
  for (let i = 0; i < 5; i++) {
    const a = (i * 4 * Math.PI) / 5 - Math.PI / 2;
    const rad = 7.5;
    const px = Math.cos(a) * rad;
    const py = Math.sin(a) * rad;
    if (i === 0) context.moveTo(px, py);
    else context.lineTo(px, py);
  }
  context.closePath();
  context.fill();

  // 印文章文
  context.textAlign = 'center';
  context.textBaseline = 'middle';
  context.font = 'bold 14px ' + FONT_CHRONICLE;
  context.fillText(text || '准予批复', 0, 13);

  if (sub) {
    context.font = 'bold 14px ' + FONT_UI;
    context.fillText(sub, 0, 23);
  }

  context.restore();
}

function drawSeal(context, cx, cy, text, sub, radius) {
  const r = radius || 38;
  const sealText = text || '准予批复';
  const sealSub = sub || '';
  const key = `${sealText}_${sealSub}_${r}`;

  let cached = SEAL_OFFSCREEN_CACHE.get(key);
  if (!cached) {
    try {
      const pad = 6;
      const dim = Math.ceil((r + pad) * 2);
      let offCanvas = null;
      if (typeof wx !== 'undefined' && typeof wx.createOffscreenCanvas === 'function') {
        offCanvas = wx.createOffscreenCanvas({ type: '2d', width: dim, height: dim });
      } else if (typeof document !== 'undefined') {
        offCanvas = document.createElement('canvas');
        offCanvas.width = dim;
        offCanvas.height = dim;
      }
      if (offCanvas) {
        const offCtx = offCanvas.getContext('2d');
        if (offCtx) {
          drawSealDirect(offCtx, dim / 2, dim / 2, sealText, sealSub, r);
          cached = { canvas: offCanvas, dim, halfDim: dim / 2 };
          if (SEAL_OFFSCREEN_CACHE.size > 20) {
            const firstKey = SEAL_OFFSCREEN_CACHE.keys().next().value;
            SEAL_OFFSCREEN_CACHE.delete(firstKey);
          }
          SEAL_OFFSCREEN_CACHE.set(key, cached);
        }
      }
    } catch (e) { logDebugError("caughtException_" + 14, e); }
  }

  if (cached && cached.canvas) {
    context.drawImage(cached.canvas, cx - cached.halfDim, cy - cached.halfDim);
  } else {
    drawSealDirect(context, cx, cy, sealText, sealSub, r);
  }
}

/**
 * 🎨 纯矢量自绘国风徽记系统 (Traditional Vector Seal & Glyph System)
 * 彻底告别对操作系统特定字体 Emoji (👶, 🕰️, 📽️, 📜, 🏆 等) 的依赖，保障跨机型国风质感与高精度渲染
 */
function drawTraditionalSealBadge(context, type, cx, cy, radius, color) {
  if (!context) return;
  const r = radius || 14;
  const clr = color || '#f59e0b';
  context.save();
  context.translate(cx, cy);

  switch (type) {
    case 'baby':
    case 'infant':
    case 'lock': {
      // 🌟 如意长命锁徽标 (取代 👶)
      context.strokeStyle = clr;
      context.fillStyle = clr;
      context.lineWidth = 1.6;

      // 锁梁 (上圆弧弯环)
      context.beginPath();
      context.arc(0, -r * 0.45, r * 0.48, Math.PI, 0, false);
      context.stroke();

      // 如意云头主体锁面 (扁鼓/弧角梯形)
      context.beginPath();
      context.moveTo(-r * 0.8, -r * 0.3);
      context.quadraticCurveTo(-r * 0.9, r * 0.5, 0, r * 0.65);
      context.quadraticCurveTo(r * 0.9, r * 0.5, r * 0.8, -r * 0.3);
      context.quadraticCurveTo(0, -r * 0.1, -r * 0.8, -r * 0.3);
      context.closePath();
      context.stroke();

      // 锁心如意圆孔
      context.beginPath();
      context.arc(0, r * 0.15, r * 0.18, 0, Math.PI * 2);
      context.fill();
      break;
    }

    case 'era':
    case 'clock':
    case 'sundial': {
      // 🕰️ 青铜日晷刻度盘徽标 (取代 🕰️)
      context.strokeStyle = clr;
      context.fillStyle = clr;
      context.lineWidth = 1.5;

      // 外晷盘
      context.beginPath();
      context.arc(0, 0, r * 0.85, 0, Math.PI * 2);
      context.stroke();

      // 内同心圆
      context.lineWidth = 0.9;
      context.beginPath();
      context.arc(0, 0, r * 0.55, 0, Math.PI * 2);
      context.stroke();

      // 四方时辰刻线
      for (let i = 0; i < 4; i++) {
        const ang = (i * Math.PI) / 2;
        context.beginPath();
        context.moveTo(Math.cos(ang) * (r * 0.55), Math.sin(ang) * (r * 0.55));
        context.lineTo(Math.cos(ang) * (r * 0.85), Math.sin(ang) * (r * 0.85));
        context.stroke();
      }

      // 晷针 (斜向金光指针)
      context.lineWidth = 1.8;
      context.beginPath();
      context.moveTo(0, 0);
      context.lineTo(r * 0.45, -r * 0.45);
      context.stroke();

      // 晷心基准点
      context.beginPath();
      context.arc(0, 0, r * 0.18, 0, Math.PI * 2);
      context.fill();
      break;
    }

    case 'film':
    case 'scroll':
    case 'chronicle': {
      // 📽️ 锦缎展卷 / 丹青画卷轴徽标 (取代 📽️ / 📜)
      context.strokeStyle = clr;
      context.fillStyle = clr;
      context.lineWidth = 1.5;

      // 展开的锦帛画幅
      context.beginPath();
      context.rect(-r * 0.7, -r * 0.5, r * 1.4, r * 1.0);
      context.stroke();

      // 卷轴两端轴头
      context.lineWidth = 2.0;
      context.beginPath();
      context.moveTo(-r * 0.7, -r * 0.75);
      context.lineTo(-r * 0.7, r * 0.75);
      context.moveTo(r * 0.7, -r * 0.75);
      context.lineTo(r * 0.7, r * 0.75);
      context.stroke();

      // 卷内书文字痕
      context.lineWidth = 1.0;
      context.beginPath();
      context.moveTo(-r * 0.4, -r * 0.18);
      context.lineTo(r * 0.4, -r * 0.18);
      context.moveTo(-r * 0.4, r * 0.18);
      context.lineTo(r * 0.2, r * 0.18);
      context.stroke();
      break;
    }

    case 'medal':
    case 'tripod':
    case 'trophy': {
      // 🏆 商周青铜宝鼎徽标 (取代 🏆)
      context.strokeStyle = clr;
      context.fillStyle = clr;
      context.lineWidth = 1.5;

      // 鼎腹 (大圆腹碗形)
      context.beginPath();
      context.arc(0, -r * 0.05, r * 0.65, 0, Math.PI, false);
      context.lineTo(-r * 0.65, -r * 0.05);
      context.closePath();
      context.stroke();

      // 鼎沿两侧立耳
      context.beginPath();
      context.rect(-r * 0.6, -r * 0.4, r * 0.22, r * 0.35);
      context.rect(r * 0.38, -r * 0.4, r * 0.22, r * 0.35);
      context.stroke();

      // 鼎足 (三足鼎立)
      context.lineWidth = 1.8;
      context.beginPath();
      context.moveTo(-r * 0.45, r * 0.5);
      context.lineTo(-r * 0.5, r * 0.85);
      context.moveTo(0, r * 0.6);
      context.lineTo(0, r * 0.85);
      context.moveTo(r * 0.45, r * 0.5);
      context.lineTo(r * 0.5, r * 0.85);
      context.stroke();
      break;
    }

    case 'repair':
    case 'taichi':
    default: {
      // ☯️ 太极玄印徽标 (用于异常修复 / 乾坤流转)
      context.strokeStyle = clr;
      context.fillStyle = clr;
      context.lineWidth = 1.5;

      context.beginPath();
      context.arc(0, 0, r * 0.85, 0, Math.PI * 2);
      context.stroke();

      // S 弯太极曲线
      context.beginPath();
      context.arc(0, -r * 0.425, r * 0.425, -Math.PI / 2, Math.PI / 2, false);
      context.arc(0, r * 0.425, r * 0.425, -Math.PI / 2, Math.PI / 2, true);
      context.arc(0, 0, r * 0.85, Math.PI / 2, -Math.PI / 2, true);
      context.closePath();
      context.fill();

      // 阴阳双鱼眼
      context.fillStyle = '#140f13';
      context.beginPath();
      context.arc(0, -r * 0.425, r * 0.16, 0, Math.PI * 2);
      context.fill();

      context.fillStyle = clr;
      context.beginPath();
      context.arc(0, r * 0.425, r * 0.16, 0, Math.PI * 2);
      context.fill();
      break;
    }
  }

  context.restore();
}

function roundRect(context, x, y, width, height, radius, fill, stroke, strokeColor, strokeWidth) {
  if (width <= 0 || height <= 0 || !context) return;
  const r = Math.min(radius || 6, width / 2, height / 2);
  context.beginPath();
  if (typeof context.arcTo === 'function') {
    context.moveTo(x + r, y);
    context.lineTo(x + width - r, y);
    context.arcTo(x + width, y, x + width, y + r, r);
    context.lineTo(x + width, y + height - r);
    context.arcTo(x + width, y + height, x + width - r, y + height, r);
    context.lineTo(x + r, y + height);
    context.arcTo(x, y + height, x, y + height - r, r);
    context.lineTo(x, y + r);
    context.arcTo(x, y, x + r, y, r);
    context.closePath();
  } else {
    context.rect(x, y, width, height);
    context.closePath();
  }

  if (fill) context.fill();
  if (stroke) {
    if (strokeColor) context.strokeStyle = strokeColor;
    if (strokeWidth !== undefined) context.lineWidth = strokeWidth;
    context.stroke();
  }
}

/**
 * 模态弹窗聚光暗角遮罩 (Modal Spotlight Backdrop Mask)
 * 中心微透、边缘深邃径向渐变，压暗底层复杂信息流，聚焦弹窗核心
 */
function drawModalBackdrop(c) {
  if (!c) return;
  c.save();
  const cx = screenWidth / 2;
  const cy = screenHeight / 2;
  const maxR = Math.max(screenWidth, screenHeight) * 0.75;
  try {
    const radGrad = c.createRadialGradient(cx, cy, Math.min(screenWidth, screenHeight) * 0.15, cx, cy, maxR);
    radGrad.addColorStop(0, 'rgba(18, 14, 16, 0.70)');
    radGrad.addColorStop(0.65, 'rgba(12, 9, 11, 0.85)');
    radGrad.addColorStop(1, 'rgba(6, 4, 6, 0.95)');
    c.fillStyle = radGrad;
  } catch (_) {
    c.fillStyle = 'rgba(10, 8, 10, 0.82)';
  }
  c.fillRect(0, 0, screenWidth, screenHeight);
  c.restore();
}

/**
 * 沉浸式东方美学分层卡片绘制器 (Layered Oriental Elevation Engine)
 * 赋予面板：立体物理柔和外投影 (Elevation 1/2)、宋瓷墨玉渐变底板、琉璃倒角顶高光、内外双重金石装裱
 * 支持：玉带标题底纹 (headerBandColor)、左侧高亮色标 (leftAccentColor)、内凹深槽 (isInset) 与交互凸起 (isInteractive)
 */
function drawElevatedCard(context, x, y, width, height, opts = {}) {
  if (width <= 0 || height <= 0 || !context) return;
  const {
    radius = 6,
    elevation = 1,
    bg = null,
    borderColor = '#856447',
    borderWidth = 1,
    hasCornerOrnaments = true,
    cornerLength = 6,
    hasInnerHighlight = false,
    isInset = false,
    isInteractive = false,
    headerBandColor = null,
    headerBand = false,
    leftAccentColor = null
  } = opts;

  context.save();

  // 1. 东方画屏金石承托底影 (彻底消除移动端 Canvas 原生 shadowBlur 导致的浑浊脏黑晕与高DPR杂色)
  if (elevation > 0 && !isInset) {
    context.save();
    // 采用宋代装帧 1.2px 徽墨沉刻衬底，提供纯净微立体层次，绝无移动端高分辨率下的发虚脏边与双重抗锯齿黑边
    context.fillStyle = 'rgba(0, 0, 0, 0.35)';
    roundRect(context, x, y + 1.2, width, height, radius, true, false);
    context.restore();
  }

  // 严格重置阴影状态，杜绝任何平台级原生 Canvas 上下文状态泄漏污染
  context.shadowColor = 'transparent';
  context.shadowBlur = 0;
  context.shadowOffsetX = 0;
  context.shadowOffsetY = 0;

  // 2. 徽墨古砚/宋瓷温润微渐变底板 (平挺沉稳，墨分五色)
  if (bg) {
    context.fillStyle = bg;
  } else if (isInset) {
    context.fillStyle = '#0d0a0d'; // 内凹只读槽位深邃墨底
  } else if (isInteractive) {
    try {
      const grad = context.createLinearGradient(x, y, x, y + height);
      grad.addColorStop(0, '#261e22'); // 交互卡片/选项凸起暖茶墨色
      grad.addColorStop(1, '#1b1518');
      context.fillStyle = grad;
    } catch (_) {
      context.fillStyle = '#20181c';
    }
  } else {
    try {
      const grad = context.createLinearGradient(x, y, x, y + height);
      grad.addColorStop(0, '#1f181c'); // 主面板宋瓷徽墨暖玉渐变
      grad.addColorStop(0.4, '#181316');
      grad.addColorStop(1, '#130f11');
      context.fillStyle = grad;
    } catch (_) {
      context.fillStyle = '#161114';
    }
  }

  // 3. 主卡片外框绘制 (平挺典雅单线或泥金细边)
  const finalBorder = isInset ? (opts.borderColor || '#3a2e26') : (borderColor || '#856447');
  roundRect(context, x, y, width, height, radius, true, !!finalBorder, finalBorder, borderWidth);

  // 4. 顶部玉带底纹与鎏金界线 (Header Jade Band & Hairline Divider，仅在明确指定时绘制，杜绝穿模横线)
  const shouldDrawBand = !isInset && (headerBand || !!opts.headerBandColor) && headerBand !== false && width > 24;
  if (shouldDrawBand) {
    context.save();
    context.beginPath();
    context.rect(x + 1, y + 1, width - 2, 26);
    context.clip();
    const bandGrad = context.createLinearGradient(x, y, x + width, y);
    bandGrad.addColorStop(0, 'rgba(245, 158, 11, 0.02)');
    bandGrad.addColorStop(0.5, headerBandColor || 'rgba(245, 158, 11, 0.12)');
    bandGrad.addColorStop(1, 'rgba(245, 158, 11, 0.02)');
    context.fillStyle = bandGrad;
    context.fillRect(x + 1, y + 1, width - 2, 26);
    context.restore();

    context.save();
    const lineGrad = context.createLinearGradient(x + 10, y + 27, x + width - 10, y + 27);
    lineGrad.addColorStop(0, 'rgba(217, 119, 6, 0)');
    lineGrad.addColorStop(0.2, 'rgba(245, 158, 11, 0.30)');
    lineGrad.addColorStop(0.8, 'rgba(245, 158, 11, 0.30)');
    lineGrad.addColorStop(1, 'rgba(217, 119, 6, 0)');
    context.strokeStyle = lineGrad;
    context.lineWidth = 0.8;
    context.beginPath();
    context.moveTo(x + 10, y + 27);
    context.lineTo(x + width - 10, y + 27);
    context.stroke();
    context.restore();
  }

  // 5. 左侧色标锚点 (Left Accent Color Anchor)
  if (leftAccentColor) {
    context.save();
    context.fillStyle = leftAccentColor;
    const barW = 3;
    const barPad = Math.max(2, Math.min(5, radius / 2));
    const barH = Math.max(6, height - barPad * 2);
    roundRect(context, x + 2.5, y + barPad, barW, barH, 1.5, true, false);
    context.restore();
  }

  // 6. 四角金石如意回纹装裱
  if (hasCornerOrnaments && !isInset) {
    drawCornerOrnaments(context, x, y, width, height, cornerLength, finalBorder || '#856447');
  }

  context.shadowColor = 'transparent';
  context.shadowBlur = 0;
  context.shadowOffsetX = 0;
  context.shadowOffsetY = 0;
  context.restore();
}

function drawWrappedText(ctx, text, x, y, maxWidth, lineHeight) {
  if (!text) return 0;
  const effectiveFont = elevateFontSize(ctx.font, 10);
  ctx.font = effectiveFont;
  const scale = typeof getScreenScaleFactor === 'function' ? getScreenScaleFactor() : 1.0;
  const baseLineH = lineHeight || Math.round(18 * scale);
  const effectiveLineHeight = Math.max(baseLineH, isElderAccessibilityMode ? 24 : Math.round(18 * scale));
  const lines = wrapTextLines(text, maxWidth, effectiveFont);
  const totalH = lines.length * effectiveLineHeight;
  // 视口快速剔除：若整个文本块在屏幕垂直可见域之外，直接返回计算高度供排版，跳过昂贵的底层 fillText
  if (y + totalH < -20 || y > screenHeight + 20) {
    return totalH;
  }
  for (let idx = 0; idx < lines.length; idx++) {
    const lineY = y + idx * effectiveLineHeight;
    if (lineY >= -20 && lineY <= screenHeight + 20) {
      ctx.fillText(lines[idx], x, lineY);
    }
  }
  return totalH;
}

const wrapText = drawWrappedText;

const WRAP_TEXT_CACHE = new Map();

function wrapTextLines(text, maxWidth, font) {
  if (!text) return [];
  const effectiveFont = elevateFontSize(font, 10);
  const cacheKey = effectiveFont + '||' + maxWidth + '||' + text;
  const cached = WRAP_TEXT_CACHE.get(cacheKey);
  if (cached) return cached;

  ctx.save();
  ctx.font = effectiveFont;
  const paragraphs = String(text).split('\n');
  const lines = [];

  for (let p = 0; p < paragraphs.length; p++) {
    const para = paragraphs[p];
    if (para.length === 0) {
      if (paragraphs.length > 1 && p < paragraphs.length - 1) {
        lines.push('');
      }
      continue;
    }

    // 整段快速命中检测：若直接能容纳，单次 measureText 即刻完成，省去逐字测量与数组分配
    if (ctx.measureText(para).width <= maxWidth) {
      lines.push(para);
      continue;
    }

    let cur = '';
    for (let i = 0; i < para.length; i++) {
      const ch = para[i];
      const test = cur + ch;
      if (measureTextMemo(ctx, test, effectiveFont) > maxWidth && cur.length > 0) {
        lines.push(cur);
        cur = ch;
      } else {
        cur = test;
      }
    }
    if (cur.length > 0) lines.push(cur);
  }
  ctx.restore();

  if (WRAP_TEXT_CACHE.size > 800) {
    const firstKey = WRAP_TEXT_CACHE.keys().next().value;
    WRAP_TEXT_CACHE.delete(firstKey);
  }
  WRAP_TEXT_CACHE.set(cacheKey, lines);
  return lines;
}

const FIT_TEXT_CACHE = new Map();

function fitText(text, maxWidth, font) {
  if (!text) return '';
  const effectiveFont = elevateFontSize(font, 10);
  const cacheKey = effectiveFont + '||' + maxWidth + '||' + text;
  const cached = FIT_TEXT_CACHE.get(cacheKey);
  if (cached !== undefined) {
    FIT_TEXT_CACHE.delete(cacheKey);
    FIT_TEXT_CACHE.set(cacheKey, cached);
    return cached;
  }

  ctx.save();
  ctx.font = effectiveFont;
  if (measureTextMemo(ctx, text, effectiveFont) <= maxWidth) {
    ctx.restore();
    if (FIT_TEXT_CACHE.size > 1200) {
      const firstKey = FIT_TEXT_CACHE.keys().next().value;
      FIT_TEXT_CACHE.delete(firstKey);
    }
    FIT_TEXT_CACHE.set(cacheKey, text);
    return text;
  }
  let low = 1, high = text.length, best = 1;
  while (low <= high) {
    const mid = (low + high) >> 1;
    const cand = text.slice(0, mid) + '…';
    if (measureTextMemo(ctx, cand, effectiveFont) <= maxWidth) {
      best = mid;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  ctx.restore();
  const res = text.slice(0, best) + '…';
  if (FIT_TEXT_CACHE.size > 1200) {
    const firstKey = FIT_TEXT_CACHE.keys().next().value;
    FIT_TEXT_CACHE.delete(firstKey);
  }
  FIT_TEXT_CACHE.set(cacheKey, res);
  return res;
}

/**
 * 防遮挡流式游标排版器 (Flow Layout Cursor Engine)
 * 专为小游戏移动端、短屏/窄屏机型与适老化放大字号设计的流式排版计算器
 * 自动累加多行折叠高度、保护左右双栏不冲突、按比例安全裁剪
 */
function createFlowCursor(startY = 0, baseGap = 6) {
  const scale = (typeof getScreenScaleFactor === 'function') ? getScreenScaleFactor() : 1.0;
  return {
    y: startY,
    baseGap: baseGap,
    scale: scale,
    drawLine(c, text, x, font, color, align = 'left', maxWidth = null) {
      if (!text || !c) return 0;
      const fontStr = getTypographyFont(font);
      const effectiveFont = elevateFontSize(fontStr, 10);
      c.save();
      c.font = effectiveFont;
      c.fillStyle = color || COLOR_TOKENS.text.secondary;
      c.textAlign = align;
      c.textBaseline = 'top';

      let outText = String(text);
      if (typeof maxWidth === 'number' && maxWidth > 0) {
        outText = fitText(outText, maxWidth, effectiveFont);
      }

      c.fillText(outText, x, this.y);
      c.restore();

      let pxSize = 13;
      const m = effectiveFont.match(/(\d+(\.\d+)?)px/);
      if (m) pxSize = parseFloat(m[1]) || 13;
      const lineH = Math.round(pxSize * 1.35 + this.baseGap);
      this.y += lineH;
      return lineH;
    },
    drawRowPair(c, leftText, rightText, x, totalWidth, leftFont, rightFont, leftColor, rightColor, leftRatio = 0.58) {
      if (!c) return 0;
      const safeGap = 8;
      const leftW = Math.max(20, Math.floor((totalWidth - safeGap) * leftRatio));
      const rightW = Math.max(20, Math.floor(totalWidth - safeGap - leftW));

      const effLeftFont = elevateFontSize(getTypographyFont(leftFont), 10);
      const effRightFont = elevateFontSize(getTypographyFont(rightFont), 10);

      c.save();
      c.textBaseline = 'top';

      // 左侧
      c.font = effLeftFont;
      c.fillStyle = leftColor || COLOR_TOKENS.text.primary;
      c.textAlign = 'left';
      const fitLeft = fitText(String(leftText || ''), leftW, effLeftFont);
      c.fillText(fitLeft, x, this.y);

      // 右侧
      c.font = effRightFont;
      c.fillStyle = rightColor || COLOR_TOKENS.text.muted;
      c.textAlign = 'right';
      const fitRight = fitText(String(rightText || ''), rightW, effRightFont);
      c.fillText(fitRight, x + totalWidth, this.y);

      c.restore();

      let leftPx = 13, rightPx = 13;
      const mL = effLeftFont.match(/(\d+(\.\d+)?)px/);
      if (mL) leftPx = parseFloat(mL[1]) || 13;
      const mR = effRightFont.match(/(\d+(\.\d+)?)px/);
      if (mR) rightPx = parseFloat(mR[1]) || 13;

      const maxPx = Math.max(leftPx, rightPx);
      const rowH = Math.round(maxPx * 1.35 + this.baseGap);
      this.y += rowH;
      return rowH;
    },
    drawParagraph(c, text, x, maxWidth, font, color, lineHeight = null) {
      if (!text || !c) return 0;
      const fontStr = getTypographyFont(font);
      const effectiveFont = elevateFontSize(fontStr, 10);
      c.save();
      c.font = effectiveFont;
      c.fillStyle = color || COLOR_TOKENS.text.secondary;
      c.textAlign = 'left';
      c.textBaseline = 'top';

      let recommendedLineH = lineHeight;
      if (!recommendedLineH) {
        if (typeof font === 'string' && TYPOGRAPHY[font] && TYPOGRAPHY[font].lineHeight) {
          recommendedLineH = Math.round(TYPOGRAPHY[font].lineHeight * this.scale);
        } else {
          let pxSize = 13;
          const m = effectiveFont.match(/(\d+(\.\d+)?)px/);
          if (m) pxSize = parseFloat(m[1]) || 13;
          recommendedLineH = Math.round(pxSize * 1.45);
        }
      }

      const usedH = drawWrappedText(c, String(text), x, this.y, maxWidth, recommendedLineH);
      c.restore();
      this.y += usedH + this.baseGap;
      return usedH;
    },
    drawIconLine(c, icon, text, x, font = 'body', color = null, align = 'left', maxWidth = null) {
      if (!text || !c) return 0;
      const fontStr = getTypographyFont(font);
      const effectiveFont = elevateFontSize(fontStr, 10);
      c.save();
      c.font = effectiveFont;
      c.textAlign = align;
      c.textBaseline = 'top';

      let iconWidth = 0;
      if (icon) {
        c.fillStyle = '#ffffff';
        c.fillText(icon, x, this.y);
        iconWidth = c.measureText(icon).width + ICON_SPEC.sizes.inlineSpacing;
      }

      c.fillStyle = color || COLOR_TOKENS.text.secondary;
      let outText = String(text);
      if (typeof maxWidth === 'number' && maxWidth > 0) {
        outText = fitText(outText, Math.max(20, maxWidth - iconWidth), effectiveFont);
      }
      c.fillText(outText, x + iconWidth, this.y);
      c.restore();

      let pxSize = 13;
      const m = effectiveFont.match(/(\d+(\.\d+)?)px/);
      if (m) pxSize = parseFloat(m[1]) || 13;
      const lineH = Math.round(pxSize * 1.35 + this.baseGap);
      this.y += lineH;
      return lineH;
    },
    gap(px) {
      const added = Math.round((px || 0) * this.scale);
      this.y += added;
      return this.y;
    }
  };
}

