function archiveLegacySaveData(rawJsonOrObj, reason = 'legacy_mode_incompatible') {
  try {
    const payload = JSON.stringify({
      archivedAt: Date.now(),
      reason,
      content: rawJsonOrObj
    });
    if (typeof wx !== 'undefined' && typeof wx.setStorageSync === 'function') {
      wx.setStorageSync(LEGACY_ARCHIVE_STORAGE_KEY, payload);
      LEGACY_SAVE_STORAGE_KEYS.forEach(k => {
        try { wx.removeStorageSync(k); } catch (_) {}
      });
    } else if (typeof localStorage !== 'undefined') {
      localStorage.setItem(LEGACY_ARCHIVE_STORAGE_KEY, payload);
      LEGACY_SAVE_STORAGE_KEYS.forEach(k => {
        try { localStorage.removeItem(k); } catch (_) {}
      });
    }
  } catch (_) {}
}

function migrateSaveData(parsed) {
  if (!parsed || typeof parsed !== 'object') return null;
  // 彻底阻断任何现代遗留旧档（如 1972 年存档）或模式不符的旧档污染华夏世家大系（公元100~300年第一赛季）
  if ((parsed.year && parsed.year >= 1900) || (parsed.birthYear && parsed.birthYear >= 1900)) {
    archiveLegacySaveData(parsed, 'modern_year_forbidden');
    return null;
  }
  if (parsed.mode && parsed.mode !== CLAN_SEASON_MODE_V1) {
    archiveLegacySaveData(parsed, 'unsupported_mode');
    return null;
  }
  parsed.mode = CLAN_SEASON_MODE_V1;
  const ver = parsed.version || 1;
  parsed.endgameSettled = !!parsed.endgameSettled;
  parsed.bonusMaxAp = parsed.bonusMaxAp || 0;
  parsed.completedPactsCount = parsed.completedPactsCount || 0;
  parsed.inactionYears = parsed.inactionYears || 0;
  // 迁移旧版职级（旧版 govLevel 可达 7~8，新版严格钳制于 1~5 并同步 lifetimeMaxRank）
  const rawLvl = Math.max(parsed.govLevel || 1, parsed.rankIndex || 1, parsed.lifetimeMaxRank || 1);
  const clampedLvl = (parsed.age || 0) < 18 ? 0 : Math.max(1, Math.min(5, Math.round(rawLvl)));
  parsed.govLevel = clampedLvl;
  parsed.rankIndex = clampedLvl;
  parsed.lifetimeMaxRank = clampedLvl;
  // 迁移旧版工作方针（修正遗留 'overwork' 或非法键名）
  if (parsed.strategy === 'overwork') {
    parsed.strategy = 'aggressive';
  } else if (!['balanced', 'aggressive', 'clean', 'network', 'wellness'].includes(parsed.strategy)) {
    parsed.strategy = 'balanced';
  }
  // 迁移旧版寿数上限与过劳/调摄轨迹字段
  if (typeof parsed.lifespanCeiling !== 'number' || parsed.lifespanCeiling < 62 || parsed.lifespanCeiling > 92) {
    parsed.lifespanCeiling = 75;
  }
  parsed.baseLifespanSeed = typeof parsed.baseLifespanSeed === 'number' ? parsed.baseLifespanSeed : parsed.lifespanCeiling;
  parsed.overworkYears = Math.max(0, Math.min(25, parsed.overworkYears || 0));
  parsed.wellnessYears = Math.max(0, Math.min(40, parsed.wellnessYears || 0));
  parsed.decisionSuccessCount = Math.max(0, parsed.decisionSuccessCount || 0);
  parsed.decisionFailCount = Math.max(0, parsed.decisionFailCount || 0);
  parsed.auditCrisisCount = Math.max(0, parsed.auditCrisisCount || 0);
  parsed.debtCrisisCount = Math.max(0, parsed.debtCrisisCount || 0);
  parsed.healthCrisisCount = Math.max(0, parsed.healthCrisisCount || 0);
  clampCoreStats(parsed);
  if (ver < SAVE_VERSION) {
    parsed.version = SAVE_VERSION;
    if (true) {
      reportGameMilestone('save_migrated', { fromVersion: ver, toVersion: SAVE_VERSION, age: parsed.age || 0 });
    }
  }
  return parsed;
}

