let _lastCloudSyncTs = 0;
function syncSaveToCloud(saveData) {
  if (!saveData || !saveData.name) return;
  const now = Date.now();
  if (now - _lastCloudSyncTs < 12000) return; // 12秒节流，避免高频写网络
  _lastCloudSyncTs = now;

  try {
    const meta = {
      version: saveData.version,
      savedAt: saveData.savedAt || now,
      year: saveData.year,
      age: saveData.age,
      name: saveData.name,
      jobTitle: saveData.jobTitle,
      rankName: saveData.rankName,
      capital: saveData.capital,
      track: saveData.track
    };
    const metaStr = JSON.stringify(meta);
    const saveStr = JSON.stringify(saveData);

    // 1. 微信原生用户云存储 (免自建服务器，随微信号漫游，换机/清缓存防丢档)
    if (typeof wx !== 'undefined' && typeof wx.setUserCloudStorage === 'function') {
      wx.setUserCloudStorage({
        KVDataList: [
          { key: 'lifesim_cloud_meta', value: metaStr },
          { key: 'lifesim_cloud_backup', value: saveStr }
        ],
        success() {
          state._cloudSyncSuccess = true;
          state._lastCloudSyncTime = now;
        },
        fail(err) {
          logDebugError('wx.setUserCloudStorage', err);
        }
      });
    }

    // 2. 微信云开发数据库存档同步 (若开通 wx.cloud)
    if (typeof wx !== 'undefined' && wx.cloud && typeof wx.cloud.database === 'function') {
      try {
        const db = wx.cloud.database();
        db.collection('user_archives').doc('active_save').set({
          data: {
            saveData,
            meta,
            updatedAt: db.serverDate ? db.serverDate() : now
          }
        }).catch(() => {});
      } catch (_) {}
    }

    // 3. 抖音小游戏环境云存储
    if (typeof tt !== 'undefined' && typeof tt.setUserGroupStorage === 'function') {
      try {
        tt.setUserGroupStorage({
          KVDataList: [{ key: 'lifesim_cloud_backup', value: metaStr }]
        });
      } catch (_) {}
    }
  } catch (err) {
    logDebugError('syncSaveToCloud', err);
  }
}

function restoreFromCloudSave(callback) {
  if (typeof wx !== 'undefined' && typeof wx.getUserCloudStorage === 'function') {
    try {
      wx.getUserCloudStorage({
        keyList: ['lifesim_cloud_backup', 'lifesim_cloud_meta'],
        success(res) {
          if (res && Array.isArray(res.KVDataList)) {
            const backupItem = res.KVDataList.find(i => i.key === 'lifesim_cloud_backup');
            if (backupItem && backupItem.value) {
              try {
                const parsed = JSON.parse(backupItem.value);
                if (parsed && parsed.name && parsed.year) {
                  // 云备份严格校验模式与年代
                  if ((parsed.year >= 1900) || (parsed.birthYear >= 1900) || (parsed.mode && parsed.mode !== CLAN_SEASON_MODE_V1)) {
                    archiveLegacySaveData(backupItem.value, 'cloud_legacy_forbidden');
                    if (typeof callback === 'function') callback(null);
                    return;
                  }
                  wx.setStorageSync(SAVE_STORAGE_KEY, backupItem.value);
                  _cachedSaveSource = 'cloud_backup';
                  _cachedSaveRaw = backupItem.value;
                  _cachedSaveParsed = migrateSaveData(parsed);
                  showToast("☁️ 已从微信云端恢复您的生涯档案！", "gold");
                  if (typeof callback === 'function') callback(_cachedSaveParsed);
                  requestRender();
                  return;
                }
              } catch (_) {}
            }
          }
          if (typeof callback === 'function') callback(null);
        },
        fail() {
          if (typeof callback === 'function') callback(null);
        }
      });
      return;
    } catch (_) {}
  }
  if (typeof callback === 'function') callback(null);
}

let _cachedSaveRaw = undefined;
let _cachedSaveParsed = null;

function loadGameState(forceReload = false) {
  if (!forceReload && _cachedSaveRaw !== undefined && typeof window !== 'undefined') {
    return _cachedSaveParsed;
  }
  try {
    if (typeof archiveService !== 'undefined' && archiveService && typeof archiveService.loadGameState === 'function') {
      const parsed = archiveService.loadGameState();
      if (!parsed) {
        _cachedSaveRaw = null;
        _cachedSaveParsed = null;
        _cachedSaveSource = 'none';
        restoreFromCloudSave();
        return null;
      }
      if (parsed && ((parsed.year && parsed.year >= 1900) || (parsed.birthYear && parsed.birthYear >= 1900) || (parsed.mode && parsed.mode !== CLAN_SEASON_MODE_V1))) {
        archiveLegacySaveData(parsed, 'mode_or_year_mismatch');
        clearSavedGame();
        _cachedSaveRaw = null;
        _cachedSaveParsed = null;
        _cachedSaveSource = 'none';
        return null;
      }
      _cachedSaveRaw = JSON.stringify(parsed);
      _cachedSaveParsed = parsed;
      _cachedSaveSource = 'archive_service';
      return parsed;
    }
    let json = null;
    let migratedFromLegacyKey = false;
    if (typeof wx !== 'undefined' && typeof wx.getStorageSync === 'function') {
      json = wx.getStorageSync(SAVE_STORAGE_KEY);
      if (!json) {
        for (let i = 0; i < LEGACY_SAVE_STORAGE_KEYS.length; i++) {
          const oldJson = wx.getStorageSync(LEGACY_SAVE_STORAGE_KEYS[i]);
          if (oldJson) {
            json = oldJson;
            migratedFromLegacyKey = true;
            break;
          }
        }
      }
    } else if (typeof localStorage !== 'undefined') {
      json = localStorage.getItem(SAVE_STORAGE_KEY);
      if (!json) {
        for (let i = 0; i < LEGACY_SAVE_STORAGE_KEYS.length; i++) {
          const oldJson = localStorage.getItem(LEGACY_SAVE_STORAGE_KEYS[i]);
          if (oldJson) {
            json = oldJson;
            migratedFromLegacyKey = true;
            break;
          }
        }
      }
    }
    if (!json || (typeof json === 'string' && !json.trim())) {
      _cachedSaveRaw = null;
      _cachedSaveParsed = null;
      _cachedSaveSource = 'none';
      // 本地无档时静默发起云端恢复检测 (换机/新装无缝恢复)
      restoreFromCloudSave();
      return null;
    }
    if (json === _cachedSaveRaw && _cachedSaveParsed) {
      return _cachedSaveParsed;
    }
    const parsed = typeof json === 'string' ? JSON.parse(json) : json;
    if (parsed && ((parsed.year && parsed.year >= 1900) || (parsed.birthYear && parsed.birthYear >= 1900) || (parsed.mode && parsed.mode !== CLAN_SEASON_MODE_V1))) {
      archiveLegacySaveData(parsed, 'mode_or_year_mismatch');
      clearSavedGame();
      _cachedSaveRaw = null;
      _cachedSaveParsed = null;
      _cachedSaveSource = 'none';
      return null;
    }
    if (parsed && parsed.year && parsed.name) {
      _cachedSaveSource = migratedFromLegacyKey ? 'migrated_legacy' : 'local_v5';
      _cachedSaveRaw = json;
      _cachedSaveParsed = migrateSaveData(parsed);
      if (!_cachedSaveParsed) {
        clearSavedGame();
        _cachedSaveRaw = null;
        _cachedSaveSource = 'none';
        return null;
      }
      if (migratedFromLegacyKey) {
        const migratedJson = JSON.stringify(_cachedSaveParsed);
        if (typeof wx !== 'undefined' && typeof wx.setStorageSync === 'function') {
          wx.setStorageSync(SAVE_STORAGE_KEY, migratedJson);
        } else if (typeof localStorage !== 'undefined') {
          localStorage.setItem(SAVE_STORAGE_KEY, migratedJson);
        }
      }
      return _cachedSaveParsed;
    }
  } catch (e) {
    logDebugError('loadGameState', e);
  }
  _cachedSaveRaw = null;
  _cachedSaveParsed = null;
  return null;
}

function hasSavedGame() {
  if (typeof archiveService !== 'undefined' && archiveService && typeof archiveService.hasSavedGame === 'function') {
    const s = archiveService.loadGameState();
    return s !== null && !!s.year;
  }
  const s = _cachedSaveRaw !== undefined ? _cachedSaveParsed : loadGameState();
  return s !== null && !!s.year;
}

function resumeSavedGame() {
  const s = loadGameState(true);
  if (!s) return false;
  
  Object.keys(s).forEach(k => {
    if (k !== 'version' && k !== 'savedAt') {
      state[k] = s[k];
    }
  });
  clampCoreStats(state);
  state.isStarted = true;
  state.gameScene = 'game';
  state.activeModal = state.endgameSettled ? 'endgame' : null;
  state.pendingPhoneCrisis = null;
  state.isPlaying = false;
  if (typeof s.bgmEnabled === 'boolean') {
    bgmEnabled = s.bgmEnabled;
    state.bgmEnabled = bgmEnabled;
    if (_soundMgr && typeof _soundMgr.setBgmEnabled === 'function') {
      _soundMgr.setBgmEnabled(bgmEnabled);
    }
  }
  if (typeof s.sfxEnabled === 'boolean') {
    sfxEnabled = s.sfxEnabled;
    state.sfxEnabled = sfxEnabled;
    state.soundEnabled = sfxEnabled;
    if (_soundMgr && typeof _soundMgr.setSfxEnabled === 'function') {
      _soundMgr.setSfxEnabled(sfxEnabled);
    }
  }
  if (typeof s.hapticEnabled === 'boolean') {
    state.hapticEnabled = s.hapticEnabled;
  }
  if (s.runSeed) {
    state.runSeed = s.runSeed;
    if (typeof _initialGameSeed !== 'undefined') _initialGameSeed = s.runSeed;
  }
  if (typeof s.rewardedAdWatchedThisRun === 'number') {
    state.rewardedAdWatchedThisRun = s.rewardedAdWatchedThisRun;
  }
  if (typeof s.lastRewardedAdTs === 'number') {
    _lastRewardedAdTs = s.lastRewardedAdTs;
    state.lastRewardedAdTs = s.lastRewardedAdTs;
  }

  // 确保真实运营赛季与世家底色特权加成同步激活
  if (typeof syncRealSeason === 'function') {
    syncRealSeason();
  }
  if (state.familyProfile && state.familyProfile.vocationId && typeof _familySystemMod !== 'undefined' && _familySystemMod.VOCATION_ORIGIN_PROFILES) {
    const voc = _familySystemMod.VOCATION_ORIGIN_PROFILES[state.familyProfile.vocationId];
    if (voc && voc.statBonus) {
      if (state.tradeSuccessBonus === undefined) state.tradeSuccessBonus = voc.statBonus.tradeSuccessBonus || 0;
      if (state.epidemicResist === undefined) state.epidemicResist = voc.statBonus.epidemicResist || 0;
      if (state.cultureBonus === undefined) state.cultureBonus = voc.statBonus.cultureBonus || 0;
      if (state.techInventionBonus === undefined) state.techInventionBonus = voc.statBonus.techInventionBonus || 0;
      if (state.healthCapBonus === undefined) state.healthCapBonus = voc.statBonus.healthCapBonus || 0;
    }
  }
  
  playSoundEffect('fanfare');
  if (bgmEnabled && typeof startBGM === 'function') {
    startBGM();
  }
  if (typeof triggerInkWashTransition === 'function') {
    triggerInkWashTransition();
  }
  showToast(`已续接 ${state.year}年·${state.name} 履职征程！`, 'gold');
  requestRender();
  return true;
}

function clearSavedGame() {
  _cachedSaveRaw = null;
  _cachedSaveParsed = null;
  if (typeof archiveService !== 'undefined' && archiveService && typeof archiveService.clearSavedGame === 'function') {
    archiveService.clearSavedGame();
  }
  try {
    if (typeof wx !== 'undefined' && typeof wx.removeStorageSync === 'function') {
      wx.removeStorageSync(SAVE_STORAGE_KEY);
      LEGACY_SAVE_STORAGE_KEYS.forEach(k => wx.removeStorageSync(k));
    } else if (typeof localStorage !== 'undefined') {
      localStorage.removeItem(SAVE_STORAGE_KEY);
      LEGACY_SAVE_STORAGE_KEYS.forEach(k => localStorage.removeItem(k));
    }
  } catch (e) { logDebugError("caughtException_" + 15, e); }
}

