function checkMemoryAlbumMilestones() {
  if (!state.memoryAlbum) state.memoryAlbum = [];
  if (!state.unlockedMemories) state.unlockedMemories = state.memoryAlbum;
  const yr = state.year;
  const age = state.age;

  function tryUnlockMemory(id) {
    if (state.memoryAlbum.includes(id)) return;
    const mem = MEMORY_ALBUM_DATABASE.find(m => m.id === id);
    if (!mem) return;
    unlockMemoryCard(id);
    playSoundEffect('bell');
    showToast(`📷 岁月相册解锁珍贵纪实：【${mem.title}】！`, 'gold');
    addChronicleItem(age, yr, `【岁月图景】生平相册永久收录珍贵历史相片《${mem.title}》（${mem.desc.slice(0, 30)}…）！`, "岁月留影", "promo");
    requestRender();
  }

  if (state.age >= 20) tryUnlockMemory('album_first_job');
  if (state.originKey === 'scholar' || (state.iq >= 80 && state.age >= 21)) tryUnlockMemory('album_gaokao');
  if (state.family && state.family.spouseName && state.age >= 24) tryUnlockMemory('album_wedding');
  if (state.capital >= 50000 || (state.rep >= 60 && state.age >= 26)) tryUnlockMemory('album_first_pot');
  if (state.family && ((state.family.livingLevel || 1) >= 2 || (state.family.endowmentFund || 0) >= 50000)) tryUnlockMemory('album_housing');
  if (state.year >= 2001 && (state.track === 'biz' || state.track === 'tech' || state.rep >= 70)) tryUnlockMemory('album_overseas');
  if (state.activeShield || state.handledEvents['swan_1998'] || state.handledEvents['swan_2003'] || state.handledEvents['swan_2020']) tryUnlockMemory('album_crisis_shield');
  if (state.rep >= 80 || state.govLevel >= 4) tryUnlockMemory('album_model_worker');
  if (state.handledEvents['swan_2018'] || (state.track === 'tech' && state.rep >= 85) || (state.unlockedHeirlooms && state.unlockedHeirlooms.length >= 2)) tryUnlockMemory('album_patent_breakthrough');
  if (state.family && (state.family.educationLevel || 1) >= 3) tryUnlockMemory('album_children_success');
  if (state.rep >= 90 && state.age >= 50) tryUnlockMemory('album_hall_of_fame');
  if (state.age >= 60) tryUnlockMemory('album_retire_reflection');
}

function openMemoryAlbumModal() {
  state.activeModal = 'memory_album';
  playSoundEffect('paper');
  requestRender();
}

function unlockMemoryCard(id) {
  if (!state.memoryAlbum) state.memoryAlbum = [];
  if (!state.unlockedMemories) state.unlockedMemories = state.memoryAlbum;
  if (!state.memoryAlbum.includes(id)) {
    state.memoryAlbum.push(id);
    if (!state.unlockedMemories.includes(id)) state.unlockedMemories.push(id);
    saveGameState();
  }
}

