function performDivination() {
  if (state.fortuneHexagram && state.fortuneHexagram.year === state.year) {
    const existingHex = DIVINATION_HEXAGRAMS.find(h => h.key === state.fortuneHexagram.key || (state.fortuneHexagram.name && state.fortuneHexagram.name.includes(h.name.slice(0, 1)))) || DIVINATION_HEXAGRAMS[0];
    state.activeDivinationResult = existingHex;
    state.activeModal = 'divination';
    showToast(`本年度已研析岁时节律【${state.fortuneHexagram.name}】，重览当年岁策！`, "info");
    requestRender();
    return;
  }
  if (state.ap < 1) {
    showToast("精力不足，岁时研策需消耗 1 点精力！", "alert");
    return;
  }
  state.ap -= 1;
  if (true) {
    progressThreeYearPact(12, '岁时推演');
  }
  playSoundEffect('dice');
  triggerHaptic('medium');
  
  const picked = DIVINATION_HEXAGRAMS[Math.floor(seededRandom() * DIVINATION_HEXAGRAMS.length)];
  picked.apply();
  state.lastDivinationYear = state.year;
  if (state.fortuneHexagram) {
    state.fortuneHexagram.omen = picked.title;
    state.fortuneHexagram.effectDesc = picked.bonusText;
    state.fortuneHexagram.lines = picked.lines;
    state.fortuneHexagram.title = picked.title;
    state.fortuneHexagram.verdict = picked.verdict;
    state.fortuneHexagram.bonusText = picked.bonusText;
  }
  state.yearlyOmen = { name: picked.name, desc: picked.bonusText, year: state.year };
  state.activeDivinationResult = picked;
  state.activeModal = 'divination';
  
  addChronicleItem(state.age, state.year, `【岁时策照】静思推演时代时运与治业脉络，参悟先哲启迪【${picked.name}】（${picked.title}）！${picked.bonusText}`, "岁时格物", "promo");
  playSoundEffect('bell');
  saveGameState();
  requestRender();
}

