function getMacroClimate(year) {
  if (year < MACRO_CLIMATES[0].startYear) return MACRO_CLIMATES[0];
  const c = MACRO_CLIMATES.find(m => year >= m.startYear && year <= m.endYear);
  return c || MACRO_CLIMATES[MACRO_CLIMATES.length - 1];
}

