function plantKarmaSeed(key, choice, title) {
  if ((state.age || 0) < 22) return;
  if (!state.karmaPledges) state.karmaPledges = {};
  if (state.karmaPledges[key]) return;
  state.karmaPledges[key] = {
    choice: choice,
    title: title || key,
    age: state.age,
    year: state.year
  };
  addChronicleItem(state.age, state.year, `【因果伏笔】你的战略决断《${title || key}》已被写入历史因果簿，数载之后必有时代回响。`, "因果伏笔", "history");
}

function checkKarmaEchoes(age, year) {
  if (!state.karmaPledges || age < 32) return;
  if (!state.karmaHistory) state.karmaHistory = [];

  for (let i = 0; i < KARMA_ECHO_DEFINITIONS.length; i++) {
    const echo = KARMA_ECHO_DEFINITIONS[i];
    if (state.handledEvents['echo_' + echo.id]) continue;
    const pledge = state.karmaPledges[echo.seedKey];
    if (pledge && pledge.choice === echo.seedChoice && (year - pledge.year) >= echo.minYearsElapsed) {
      state.handledEvents['echo_' + echo.id] = true;
      echo.apply(state);
      clampCoreStats(state);
      state.karmaHistory.push({
        id: echo.id,
        title: echo.title,
        desc: echo.desc,
        impactDesc: echo.impactDesc,
        year: year,
        age: age
      });
      playSoundEffect('gong');
      triggerHaptic('heavy');
      showToast(`🔮 触发历史因果回响：${echo.title}！`, 'gold');
      addChronicleItem(age, year, `${echo.title} ${echo.desc} 时代收益：${echo.impactDesc}`, "因果回响", "promo");
      break;
    }
  }
}


// ==========================================
// 六.J 动态购买力与时代通胀系统 (Dynamic Purchasing Power & Era Inflation)
// ==========================================
function getEraInflationScale(yr) {
  const y = typeof yr === 'number' ? yr : ((state && state.year) || 1992);
  return Math.max(1, 1 + Math.max(0, y - 1992) * 0.08);
}

function getCurrentEraRival(age) {
  const a = typeof age === 'number' ? age : ((state && state.age) || 18);
  if (a < 22 || a > 52) return null;
  const isHanWei = (typeof state !== 'undefined' && state && (isDynasticEra(state.year) || (state.year && state.year <= 300)));
  const pool = isHanWei ? HAN_WEI_RIVALS_DATABASE : ERA_RIVALS_DATABASE;
  if (!pool || pool.length === 0) return null;
  if (a <= 25) return pool.find(r => r.age === 25) || pool[0];
  if (a <= 33) return pool.find(r => r.age === 33) || pool[1];
  if (a <= 41) return pool.find(r => r.age === 41) || pool[2];
  return pool.find(r => r.age === 49) || pool[3];
}

function ensureRivalMomentumState() {
  if (typeof state.rivalMomentum !== 'number') state.rivalMomentum = 50;
  if (typeof state.playerMomentum !== 'number') state.playerMomentum = 50;
  state.rivalMomentum = Math.max(0, Math.min(100, Math.round(state.rivalMomentum)));
  state.playerMomentum = Math.max(0, Math.min(100, Math.round(state.playerMomentum)));
  return { playerMomentum: state.playerMomentum, rivalMomentum: state.rivalMomentum };
}

