function registerCausalSeed(seedId, title, year, desc) {
  state.causalSeeds = state.causalSeeds || {};
  if (!state.causalSeeds[seedId]) {
    state.causalSeeds[seedId] = {
      id: seedId,
      title: title,
      year: year,
      desc: desc,
      isEchoed: false
    };
    playSoundEffect('causal_nexus_echo');
    showToast(`🦋【因果伏线种下】${title}（伏线将在数十年后激荡回响）`, 'gold');
    addChronicleItem(state.age, year, `【因果结缘】种下命运因果之种：${title}。${desc}`, '命运伏笔', 'promo');
  }
}

function triggerCausalEcho(echoId, seedId, title, year, echoDesc, buffFn) {
  state.causalEchoes = state.causalEchoes || [];
  if (!state.causalEchoes.includes(echoId)) {
    state.causalEchoes.push(echoId);
    if (state.causalSeeds && state.causalSeeds[seedId]) {
      state.causalSeeds[seedId].isEchoed = true;
    }
    const beforeStats = {
      clean: state.clean,
      rep: state.rep,
      health: state.health,
      capital: state.capital,
      iq: state.iq,
      eq: state.eq,
      courage: state.courage,
      resilience: state.resilience
    };
    if (typeof buffFn === 'function') buffFn(state);
    clampCoreStats(state);

    const changedKeys = [];
    for (const k in beforeStats) {
      if (state[k] !== beforeStats[k]) {
        changedKeys.push(k);
      }
    }
    if (changedKeys.length === 0) changedKeys.push('rep', 'capital');
    triggerStatPulseHighlight(changedKeys, 1200, '#f59e0b');

    playSoundEffect('storm_surge_strings');
    playSoundEffect('fanfare');
    triggerScreenShake(9, 320);
    spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 110, '#f59e0b');
    spawnGoldSpiral(screenWidth / 2, screenHeight / 2, 40);
    showToast(`⚡【因果应验·回响爆发】${title}！`, 'gold');
    addChronicleItem(state.age, year, `【命运回响】当年伏脉今日应验！${title}。${echoDesc}`, '大国因果', 'promo');
    return true;
  }
  return false;
}

function isCausalSeedActive(seedId) {
  return !!(state.causalSeeds && state.causalSeeds[seedId]);
}

// ==========================================
// 🚀 V17 性能加速引擎：高频文字宽度 LRU 缓存与粒子对象池
// ==========================================
const _measureTextCache = new Map();
const MEASURE_TEXT_CACHE = _measureTextCache;
function measureTextMemo(context, text, font) {
  const key = (font || '') + '::' + String(text || '');
  if (MEASURE_TEXT_CACHE.has(key)) {
    const val = MEASURE_TEXT_CACHE.get(key);
    MEASURE_TEXT_CACHE.delete(key);
    MEASURE_TEXT_CACHE.set(key, val);
    return val;
  }
  if (context && typeof context.measureText === 'function') {
    if (font) context.font = font;
    const res = context.measureText(text) || { width: 0 };
    if (MEASURE_TEXT_CACHE.size > 800) {
      const firstKey = MEASURE_TEXT_CACHE.keys().next().value;
      MEASURE_TEXT_CACHE.delete(firstKey);
    }
    MEASURE_TEXT_CACHE.set(key, res.width);
    return res.width;
  }
  return (String(text || '').length) * 12;
}

