// ------------------------------------------
function checkMinorCurfew() {
  const curHour = new Date().getHours();
  const isCurfew = (curHour >= 22 || curHour < 8);
  return {
    isCurfew,
    message: isCurfew ? "夜色已深，劳逸结合是国士长远之道，请保持充沛作息，尽早安歇。" : "合理安排时间，享受健康生活。"
  };
}

