    showToast(`定海神针！注资平准基金力挽狂澜，底池扩至 ¥${state.stabilizationFundPool.toLocaleString()}！`, 'gold');
    addChronicleItem(state.age, state.year, `【报国济世】带头注资国家宏观平准基金 ¥${amt.toLocaleString()} 元，筑牢金融抗风险安全防波堤。`, '平准安邦', 'promo');
