function isPreceptAdopted(preceptId) {
  const list = (state.family && state.family.adoptedPrecepts) || state.adoptedPrecepts || [];
  return list.includes(preceptId);
}

function adoptAncestralPrecept(preceptId) {
  state.family = state.family || {};
  state.family.adoptedPrecepts = state.family.adoptedPrecepts || state.adoptedPrecepts || [];
  state.adoptedPrecepts = state.family.adoptedPrecepts;
  if (state.family.adoptedPrecepts.includes(preceptId)) return false;
  if ((state.age || 18) < 30) {
    showToast("立身满三十而立（30岁）后，方可于宗祠主持订立传世祖训！", "info");
    return false;
  }
  if (state.family.adoptedPrecepts.length >= 3) {
    showToast("宗族祖训堂至多铭刻三条立身祖训！", "alert");
    return false;
  }
  if (state.lastPreceptYear === state.year) {
    showToast("本年度已主持过宗祠立训大典，请待来年再续！", "info");
    return false;
  }
  if (state.ap < 1) {
    showToast("当年精力不足，主持宗祠立训需消耗 1 点精力！", "alert");
    return false;
  }
  state.ap -= 1;
  state.lastPreceptYear = state.year;
  state.family.adoptedPrecepts.push(preceptId);
  state.adoptedPrecepts = state.family.adoptedPrecepts;
  if (true) {
    progressThreeYearPact(12, '宗祠立训');
  }
  const prec = ANCESTRAL_PRECEPTS_DATABASE.find(p => p.id === preceptId);
  if (prec) {
    if (preceptId === 'precept_integrity') addStat("clean", 5, 50);
    if (preceptId === 'precept_scholarly') addStat("iq", 5, 50);
    if (preceptId === 'precept_enterprise') { state.capital = (state.capital || 0) + 8000; addStat("eq", 3, 50); }
    if (preceptId === 'precept_courage') { addStat("courage", 5, 50); addStat("resilience", 3, 50); }
    if (preceptId === 'precept_benevolence') addStat("rep", 5, 50);
    playSoundEffect('bianzhong_chime');
    spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 90, 'rgba(217, 119, 6, 0.45)');
    spawnGoldSpiral(screenWidth / 2, screenHeight / 2, 35);
    addChronicleItem(state.age, state.year, `【宗法立言】于祖宗宗祠正式订立传世祖训${prec.name}：“${prec.motto}”！门风丕振，泽被子孙！`, '家族祖训', 'promo');
    showToast(`祖训【${prec.name}】已铭刻家谱！${prec.buffText}`, 'gold');
  }
  return true;
}

