// ==========================================
// 📜 V24 中式水墨卷轴开合过渡与宣纸装裱引擎 (Silk Scroll Framing Engine)
// ==========================================
const _silkScrollFrameCache = new Map();
function drawSilkScrollFrame(ctx, x, y, w, h, borderColor = '#b45309', rollerColor = '#d97706') {
  const rw = Math.round(w);
  const rh = Math.round(h);
  const cacheKey = `${rw}_${rh}_${borderColor}_${rollerColor}`;

  let cached = _silkScrollFrameCache.get(cacheKey);
  if (!cached) {
    const offCanvas = createOffscreenCanvasBuffer(rw + 24, rh + 20);
    if (offCanvas) {
      const offCtx = offCanvas.getContext('2d');
      if (offCtx) {
        offCtx.save();
        offCtx.translate(12, 10);
        // 1. 底层沉稳宣纸装裱衬底 (提升明暗层次对比)
        try {
          const sGrad = offCtx.createLinearGradient(0, 0, 0, rh);
          sGrad.addColorStop(0, '#161e2e');
          sGrad.addColorStop(1, '#0e1320');
          offCtx.fillStyle = sGrad;
        } catch (_) {
          offCtx.fillStyle = '#101424';
        }
        roundRect(offCtx, 0, 0, rw, rh, 10, true, true, borderColor, 2);

        // 2. 卷轴顶部与底部实木轴杆与鎏金轴头
        const rollerH = 7;
        // 顶部轴杆
        offCtx.fillStyle = rollerColor;
        roundRect(offCtx, -4, -5, rw + 8, rollerH, 3, true, true, '#fbbf24', 1);
        // 顶部左右金轴头
        offCtx.fillStyle = '#f59e0b';
        offCtx.fillRect(-8, -6, 5, rollerH + 2);
        offCtx.fillRect(rw + 3, -6, 5, rollerH + 2);

        // 底部轴杆
        offCtx.fillStyle = rollerColor;
        roundRect(offCtx, -4, rh - 2, rw + 8, rollerH, 3, true, true, '#fbbf24', 1);
        // 底部左右金轴头
        offCtx.fillStyle = '#f59e0b';
        offCtx.fillRect(-8, rh - 3, 5, rollerH + 2);
        offCtx.fillRect(rw + 3, rh - 3, 5, rollerH + 2);

        // 3. 经典四角如意祥云锦缎纹样
        drawCornerOrnaments(offCtx, 0, 0, rw, rh, 8, '#fef08a');
        drawCloudFiligreeBorders(offCtx, 0, 0, rw, rh, borderColor);
        offCtx.restore();

        if (_silkScrollFrameCache.size > 15) {
          const firstKey = _silkScrollFrameCache.keys().next().value;
          _silkScrollFrameCache.delete(firstKey);
        }
        _silkScrollFrameCache.set(cacheKey, offCanvas);
        cached = offCanvas;
      }
    }
  }

  if (cached) {
    try {
      ctx.drawImage(cached, x - 12, y - 10);
      return;
    } catch (_) {}
  }

  // 降级兜底直接绘制
  ctx.save();
  ctx.fillStyle = '#0a0d18';
  roundRect(ctx, x, y, w, h, 10, true, true, borderColor, 2);
  const rollerH = 7;
  ctx.fillStyle = rollerColor;
  roundRect(ctx, x - 4, y - 5, w + 8, rollerH, 3, true, true, '#fbbf24', 1);
  ctx.fillStyle = '#f59e0b';
  ctx.fillRect(x - 8, y - 6, 5, rollerH + 2);
  ctx.fillRect(x + w + 3, y - 6, 5, rollerH + 2);
  ctx.fillStyle = rollerColor;
  roundRect(ctx, x - 4, y + h - 2, w + 8, rollerH, 3, true, true, '#fbbf24', 1);
  ctx.fillStyle = '#f59e0b';
  ctx.fillRect(x - 8, y + h - 3, 5, rollerH + 2);
  ctx.fillRect(x + w + 3, y + h - 3, 5, rollerH + 2);
  drawCornerOrnaments(ctx, x, y, w, h, 8, '#fef08a');
  drawCloudFiligreeBorders(ctx, x, y, w, h, borderColor);
  ctx.restore();
}

// 4. 天候晨昏四时微光系统 (Diurnal Sky Ambient Lighting)
// 🌨️ 水墨天幕风雨雷雪动态微粒子系统 (Pre-allocated, 0 GC)
const SKY_WEATHER_PARTICLES = Array.from({ length: 28 }, (_, i) => ({
  x: (i * 17) % 360,
  y: (i * 23) % 240,
  vx: (i % 2 === 0 ? 0.3 : -0.2),
  vy: 0.8 + (i % 5) * 0.35,
  len: 5 + (i % 4) * 3,
  size: 1.2 + (i % 3) * 0.8,
  alpha: 0.15 + (i % 4) * 0.08
}));

const SKY_CLOUDS = [
  { x: 30, y: 18, w: 85, h: 22, vx: 0.14, alpha: 0.22 },
  { x: 160, y: 38, w: 110, h: 26, vx: 0.09, alpha: 0.18 },
  { x: 290, y: 14, w: 75, h: 20, vx: 0.16, alpha: 0.20 }
];

const SKY_RAIN_TERMS = new Set(['雨水', '惊蛰', '清明', '谷雨', '小满', '芒种']);
const SKY_SNOW_TERMS = new Set(['小雪', '大雪', '冬至', '小寒', '大寒']);
const _cachedDiurnalSkyGrads = {};

function getDiurnalSkyGradient(ctx, cycle) {
  if (_cachedDiurnalSkyGrads[cycle]) return _cachedDiurnalSkyGrads[cycle];
  const grad = ctx.createLinearGradient(0, 0, 0, 180);
  let topColor, botColor;
  if (cycle === 0) {
    topColor = 'rgba(251, 146, 60, 0.06)';
    botColor = 'rgba(254, 215, 170, 0.02)';
  } else if (cycle === 1) {
    topColor = 'rgba(56, 189, 248, 0.06)';
    botColor = 'rgba(186, 230, 253, 0.02)';
  } else if (cycle === 2) {
    topColor = 'rgba(244, 63, 94, 0.06)';
    botColor = 'rgba(251, 207, 232, 0.02)';
  } else {
    topColor = 'rgba(99, 102, 241, 0.07)';
    botColor = 'rgba(30, 27, 75, 0.02)';
  }
  grad.addColorStop(0, topColor);
  grad.addColorStop(1, botColor);
  _cachedDiurnalSkyGrads[cycle] = grad;
  return grad;
}

function renderDiurnalSkyAura(ctx) {
  if (!ctx || !state.isStarted || state.activeModal) return;

  // ☁️ 四时舒卷流云天幕微动效
  ctx.save();
  SKY_CLOUDS.forEach(cloud => {
    cloud.x += cloud.vx;
    if (cloud.x > screenWidth + 80) cloud.x = -cloud.w - 20;

    ctx.fillStyle = 'rgba(254, 240, 138, ' + cloud.alpha + ')';
    ctx.beginPath();
    if (typeof ctx.ellipse === 'function') {
      ctx.ellipse(cloud.x, cloud.y, Math.max(1, cloud.w / 2), Math.max(1, cloud.h / 2), 0, 0, Math.PI * 2);
    } else {
      ctx.save();
      ctx.translate(cloud.x, cloud.y);
      ctx.scale(Math.max(1, cloud.w / 2), Math.max(1, cloud.h / 2));
      ctx.arc(0, 0, 1, 0, Math.PI * 2);
      ctx.restore();
    }
    ctx.fill();
  });

  // 🌦️ 风雨雷雪水墨微动效
  const curTerm = state.currentSolarTerm || (typeof SOLAR_TERMS !== 'undefined' ? SOLAR_TERMS[Math.floor(Math.abs((state.year || 1980)) % 24)].name : '');
  const isRainWeather = SKY_RAIN_TERMS.has(curTerm);
  const isSnowWeather = SKY_SNOW_TERMS.has(curTerm);

  SKY_WEATHER_PARTICLES.forEach(p => {
    p.x += p.vx;
    p.y += p.vy;
    if (p.y > screenHeight + 20) {
      p.y = -20;
      p.x = seededRandom() * (screenWidth + 40) - 20;
    }
    if (p.x > screenWidth + 20) p.x = -10;
    if (p.x < -20) p.x = screenWidth + 10;

    if (isRainWeather) {
      ctx.strokeStyle = 'rgba(186, 230, 253, ' + p.alpha + ')';
      ctx.lineWidth = 1.0;
      ctx.beginPath();
      ctx.moveTo(p.x, p.y);
      ctx.lineTo(p.x + p.vx * 3, p.y + p.len);
      ctx.stroke();
    } else if (isSnowWeather) {
      ctx.fillStyle = 'rgba(254, 249, 195, ' + (p.alpha * 1.2) + ')';
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
      ctx.fill();
    } else {
      ctx.fillStyle = 'rgba(251, 191, 36, ' + (p.alpha * 0.4) + ')';
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.size * 0.7, 0, Math.PI * 2);
      ctx.fill();
    }
  });
  ctx.restore();

  // 晨昏四时动态天光 (复用预构建渐变对象)
  ctx.save();
  const cycle = Math.abs((state.year || 1980) % 4);
  ctx.fillStyle = getDiurnalSkyGradient(ctx, cycle);
  ctx.fillRect(0, 0, screenWidth, 180);
  ctx.restore();
}

// ==========================================
// 🚀 V37 粒子对象池与垃圾回收平滑器 (Particle Object Pool & GC Accelerator)
// ==========================================
const PARTICLE_OBJECT_POOL = [];
function obtainPooledParticle(initFn) {
  let p = PARTICLE_OBJECT_POOL.pop();
  if (!p) p = {};
  if (initFn) initFn(p);
  return p;
}
function releasePooledParticle(p) {
  if (p && PARTICLE_OBJECT_POOL.length < 250) {
    PARTICLE_OBJECT_POOL.push(p);
  }
}

// ==========================================
// 🌸 V23 四时流转动态粒子系统 (Four-Season Dynamic Particle Ambiance)
// ==========================================
const SEASONAL_PARTICLES = [];
for (let i = 0; i < 28; i++) {
  SEASONAL_PARTICLES.push({
    x: seededRandom() * 400,
    y: seededRandom() * 800,
    vx: (seededRandom() - 0.5) * 0.8,
    vy: 0.4 + seededRandom() * 0.8,
    size: 2 + seededRandom() * 3,
    alpha: 0.3 + seededRandom() * 0.5,
    rot: seededRandom() * Math.PI * 2,
    rotSpeed: (seededRandom() - 0.5) * 0.04
  });
}

const SEASONAL_PREFIX_COLORS = [
  'rgba(225, 112, 85, ',  // 春·落英微红
  'rgba(217, 119, 6, ',   // 夏·暗金流萤
  'rgba(180, 83, 9, ',    // 秋·金屑银杏
  'rgba(243, 237, 226, '  // 冬·宣纸细雪
];

function updateAndRenderSeasonalParticles(ctx) {
  if (!ctx || !state.isStarted || state.activeModal) return;
  const isHanWeiEra = (state.year && state.year <= 500) || (typeof isDynasticEra === 'function' && isDynasticEra(state.year));
  const sIdx = Math.abs((state.year || 1980) % 4);
  const prefix = SEASONAL_PREFIX_COLORS[sIdx];
  const nowTime = Date.now();
  ctx.save();
  for (let i = 0; i < SEASONAL_PARTICLES.length; i++) {
    const p = SEASONAL_PARTICLES[i];
    p.y += p.vy;
    p.x += p.vx + Math.sin(nowTime * 0.002 + i) * 0.3;
    p.rot += p.rotSpeed;

    if (p.y > screenHeight + 10) {
      p.y = -10;
      p.x = fxRandom() * screenWidth;
    }
    if (p.x < -10) p.x = screenWidth + 10;
    if (p.x > screenWidth + 10) p.x = -10;

    ctx.save();
    ctx.translate(p.x, p.y);
    ctx.rotate(p.rot);
    // 汉魏古风下降低粒子饱和度与尺寸，杜绝彩色几何礼花违和感
    const particleAlpha = isHanWeiEra ? (p.alpha * 0.28) : (p.alpha * 0.55);
    const particleSize = isHanWeiEra ? (p.size * 0.65) : p.size;
    ctx.fillStyle = prefix + particleAlpha + ')';

    if (sIdx === 0) {
      // 桃花瓣 / 落英
      ctx.beginPath();
      if (typeof ctx.ellipse === 'function') {
        ctx.ellipse(0, 0, particleSize * 1.2, particleSize * 0.6, 0, 0, Math.PI * 2);
      } else {
        ctx.save();
        ctx.scale(particleSize * 1.2, particleSize * 0.6);
        ctx.arc(0, 0, 1, 0, Math.PI * 2);
        ctx.restore();
      }
      ctx.fill();
    } else if (sIdx === 1) {
      // 夏夜金萤 / 暗金微尘
      const pulse = 0.4 + Math.sin(nowTime * 0.004 + i) * 0.4;
      ctx.fillStyle = prefix + (particleAlpha * pulse) + ')';
      ctx.beginPath();
      ctx.arc(0, 0, particleSize * 0.85, 0, Math.PI * 2);
      ctx.fill();
    } else if (sIdx === 2) {
      // 银杏叶 / 金屑
      ctx.beginPath();
      ctx.arc(0, 0, particleSize, -0.3, Math.PI + 0.3);
      ctx.fill();
    } else {
      // 飘雪花 / 细雪
      ctx.lineWidth = 0.8;
      ctx.strokeStyle = prefix + (particleAlpha * 0.85) + ')';
      ctx.beginPath();
      ctx.moveTo(-particleSize, 0); ctx.lineTo(particleSize, 0);
      ctx.moveTo(0, -particleSize); ctx.lineTo(0, particleSize);
      ctx.stroke();
    }
    ctx.restore();
  }
  ctx.restore();
}


// ==========================================
// ⛈️ 命运黑天鹅气象与破晓晨曦粒子动效 (Atmospheric FX Engine)
// ==========================================
let stormRainAnim = {
  active: false,
  durationMs: 0,
  startTime: 0
};

let dawnSunbeamAnim = {
  active: false,
  durationMs: 0,
  startTime: 0
};

function triggerStormGaleFX(durationMs = 4500) {
  stormRainAnim.active = true;
  stormRainAnim.durationMs = durationMs;
  stormRainAnim.startTime = Date.now();
  playSoundEffect('storm_gale');
  triggerScreenShake(8, 400);
}

function triggerDawnSunbeamFX(durationMs = 4000) {
  dawnSunbeamAnim.active = true;
  dawnSunbeamAnim.durationMs = durationMs;
  dawnSunbeamAnim.startTime = Date.now();
  playSoundEffect('bamboo_flute');
  spawnGoldSpiral(screenWidth / 2, screenHeight / 2, 35);
  spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 120, 'rgba(245, 158, 11, 0.45)');
}

function renderAtmosphericFX(ctx) {
  const now = Date.now();

  // 1. 暴风骤雨寒霜粒子流
  if (stormRainAnim.active) {
    const elapsed = now - stormRainAnim.startTime;
    if (elapsed > stormRainAnim.durationMs) {
      stormRainAnim.active = false;
    } else {
      const alpha = Math.min(0.65, (1 - elapsed / stormRainAnim.durationMs) * 0.85);
      ctx.save();
      // 屏幕边缘暗角阴霾
      const vigGrad = ctx.createRadialGradient(screenWidth / 2, screenHeight / 2, screenWidth * 0.3, screenWidth / 2, screenHeight / 2, screenWidth * 0.85);
      vigGrad.addColorStop(0, 'rgba(15, 23, 42, 0)');
      vigGrad.addColorStop(1, `rgba(15, 23, 42, ${alpha * 0.7})`);
      ctx.fillStyle = vigGrad;
      ctx.fillRect(0, 0, screenWidth, screenHeight);

      // 暴雨斜线 (单路径批处理)
      ctx.strokeStyle = `rgba(148, 163, 184, ${alpha * 0.85})`;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      for (let i = 0; i < 35; i++) {
        const rx = (now * 0.65 + i * 37) % screenWidth;
        const ry = (now * 1.8 + i * 43) % screenHeight;
        ctx.moveTo(rx, ry);
        ctx.lineTo(rx - 8, ry + 22);
      }
      ctx.stroke();
      ctx.restore();
    }
  }

  // 2. 破晓晨曦金色光柱与浮光微粒
  if (dawnSunbeamAnim.active) {
    const elapsed = now - dawnSunbeamAnim.startTime;
    if (elapsed > dawnSunbeamAnim.durationMs) {
      dawnSunbeamAnim.active = false;
    } else {
      const progress = elapsed / dawnSunbeamAnim.durationMs;
      const alpha = Math.sin(progress * Math.PI) * 0.45;
      ctx.save();
      ctx.globalAlpha = alpha;
      // 金色朝阳从右上斜射光柱
      const beamGrad = ctx.createLinearGradient(screenWidth, 0, 0, screenHeight * 0.75);
      beamGrad.addColorStop(0, 'rgba(254, 240, 138, 0.45)');
      beamGrad.addColorStop(0.5, 'rgba(245, 158, 11, 0.2)');
      beamGrad.addColorStop(1, 'rgba(245, 158, 11, 0)');
      ctx.fillStyle = beamGrad;
      ctx.fillRect(0, 0, screenWidth, screenHeight);

      // 上浮的金色晨光尘埃 (单路径批处理)
      ctx.fillStyle = '#fef08a';
      ctx.beginPath();
      for (let i = 0; i < 18; i++) {
        const px = (Math.sin(now * 0.001 + i) * 30 + i * (screenWidth / 18)) % screenWidth;
        const py = (screenHeight - (now * 0.05 + i * 45) % screenHeight);
        ctx.moveTo(px + 1.8, py);
        ctx.arc(px, py, 1.8, 0, Math.PI * 2);
      }
      ctx.fill();
      ctx.restore();
    }
  }
}
