// ==========================================
// 🌟 关键属性变动“来源高亮”流光脉冲系统 (Stat Source Pulse Highlight Engine)
// 记录受到因果回响或述职大考改变的属性，在仪表盘上展示 1.2 秒金色流光脉冲边框
// ==========================================
const _statPulseHighlights = {};

function triggerStatPulseHighlight(keys, durationMs = 1200, color = '#f59e0b') {
  const now = Date.now();
  const arr = Array.isArray(keys) ? keys : [keys];
  arr.forEach(k => {
    _statPulseHighlights[k] = {
      startTime: now,
      duration: durationMs || 1200,
      color: color || '#f59e0b'
    };
  });
  if (typeof requestRender === 'function') requestRender();
}
const triggerStatPulse = triggerStatPulseHighlight;
if (typeof global !== 'undefined') global.triggerStatPulse = triggerStatPulseHighlight;

function getStatPulseProgress(key) {
  const item = _statPulseHighlights[key];
  if (!item) return -1;
  const elapsed = Date.now() - item.startTime;
  if (elapsed >= item.duration) {
    delete _statPulseHighlights[key];
    return -1;
  }
  return elapsed / item.duration; // 0.0 ~ 1.0
}

function hasActiveStatPulseHighlights() {
  const now = Date.now();
  for (const k in _statPulseHighlights) {
    if (_statPulseHighlights[k] && (now - _statPulseHighlights[k].startTime) < _statPulseHighlights[k].duration) {
      return true;
    }
  }
  return false;
}

function drawStatPulseBorder(ctx, x, y, w, h, key) {
  let progress = getStatPulseProgress(key);
  let pulseColor = '#f59e0b';
  if (progress < 0 && key === 'competency') {
    const subKeys = ['competency', 'iq', 'eq', 'courage', 'resilience'];
    for (const sk of subKeys) {
      const p = getStatPulseProgress(sk);
      if (p >= 0) {
        progress = p;
        if (_statPulseHighlights[sk] && _statPulseHighlights[sk].color) {
          pulseColor = _statPulseHighlights[sk].color;
        }
        break;
      }
    }
  } else if (progress >= 0 && _statPulseHighlights[key] && _statPulseHighlights[key].color) {
    pulseColor = _statPulseHighlights[key].color;
  }
  if (progress < 0 || progress >= 1.0) return;

  ctx.save();
  // 1.2s 金色流光波浪与多拍多频脉冲
  const pulse = Math.sin(progress * Math.PI * 3.5);
  const alpha = Math.max(0, (1 - progress * 0.75) * (0.35 + 0.65 * Math.abs(pulse)));

  ctx.shadowColor = pulseColor || '#fbbf24';
  ctx.shadowBlur = 8 * alpha;

  ctx.strokeStyle = `rgba(245, 158, 11, ${alpha})`;
  ctx.lineWidth = 1.6;
  roundRect(ctx, x - 1, y - 1, w + 2, h + 2, 4, false, true, `rgba(245, 158, 11, ${alpha})`, 1.6);

  ctx.fillStyle = `rgba(254, 240, 138, ${alpha})`;
  ctx.font = 'bold 8.5px sans-serif';
  ctx.textAlign = 'right';
  ctx.textBaseline = 'top';
  ctx.fillText('⚡', x + w - 2, y);

  ctx.shadowColor = 'transparent';
  ctx.shadowBlur = 0;
  ctx.shadowOffsetX = 0;
  ctx.shadowOffsetY = 0;
  ctx.restore();
}

