  state.awardedMedals = state.awardedMedals || [];
  state.awardedMedals.push(mId);
  playSoundEffect('fanfare');
  playInstrumentTone('suona_heroic', 587.33, 2.0, 0.25);
  spawnInspirationSparks(screenWidth / 2, screenHeight / 2, 35);
  const m = STATE_MEDALS_DATABASE.find(item => item.id === mId);
