function hasHeirloom(heirloomId) {
  return (state.unlockedHeirlooms || []).includes(heirloomId);
}

function unlockHeirloom(heirloomId) {
  if (hasHeirloom(heirloomId)) return;
  const h = HEIRLOOMS_DATABASE.find(item => item.id === heirloomId);
  if (!h) return;
  if (!state.unlockedHeirlooms) state.unlockedHeirlooms = [];
  state.unlockedHeirlooms.push(heirloomId);

  playSoundEffect('fanfare');
  triggerHaptic('heavy');
  showToast(`🏺 荣获传世重器：【${h.name}】！`, 'gold');
  addChronicleItem(state.age, state.year, `【重器传家】迎请入室传世重宝【${h.name}】（${h.origin} · ${h.rarity}）！传家余荫：${h.buffText}`, "传世珍宝", "promo");
  requestRender();
}

// ==========================================
// 六.M 时代行情大盘与风口运营系统 (Market Ticker)
// ==========================================
function updateMarketTrends(year) {
  if (!state.marketTrends) {
    state.marketTrends = {
      realEstatePrice: 10000,
      realEstateChange: '+5%',
      realEstateTrend: 'bull',
      techPrice: 50,
      techChange: '0%',
      techTrend: 'flat',
      commodityPrice: 100,
      commodityChange: '+3%',
      commodityTrend: 'bull',
      insiderTip: '南巡春风拂面，沿海特区土地与实业迎来首轮腾飞风口！'
    };
  }
  const climate = getMacroClimate(year);
  let rChange = 0;
  let tChange = 0;
  let cChange = 0;
  let tip = climate.desc;

  if (year >= 1992 && year <= 1996) {
    rChange = 0.15 + seededRandom() * 0.15;
    tChange = 0.05 + seededRandom() * 0.10;
    cChange = 0.08 + seededRandom() * 0.12;
    tip = "特区土地划拨与转让掀起热浪，沿海不动产呈现爆发式溢价！";
  } else if (year >= 1997 && year <= 2000) {
    rChange = -0.12 - seededRandom() * 0.10;
    tChange = 0.02 + seededRandom() * 0.08;
    cChange = -0.08 - seededRandom() * 0.08;
    tip = "亚洲金融风暴波及，银根信贷大幅紧缩，现金与高信誉资产为王。";
  } else if (year >= 2001 && year <= 2007) {
    rChange = 0.20 + seededRandom() * 0.15;
    tChange = 0.15 + seededRandom() * 0.20;
    cChange = 0.18 + seededRandom() * 0.15;
    tip = "入世红利井喷！国际供应链大转移，大宗工业物资与科技外贸全线暴涨！";
  } else if (year >= 2008 && year <= 2014) {
    rChange = 0.25 + seededRandom() * 0.25;
    tChange = 0.12 + seededRandom() * 0.18;
    cChange = 0.20 + seededRandom() * 0.18;
    tip = "四万亿强力驱动，高铁网与大基建日新月异，核心不动产迎来黄金十年！";
  } else if (year >= 2015 && year <= 2019) {
    rChange = 0.08 + seededRandom() * 0.10;
    tChange = 0.35 + seededRandom() * 0.40;
    cChange = 0.05 + seededRandom() * 0.08;
    tip = "双创与移动互联网资本狂飙，硬核科技估值一日千里，独角兽神话频现！";
  } else if (year >= 2020 && year <= 2027) {
    rChange = 0.02 + seededRandom() * 0.05;
    tChange = 0.25 + seededRandom() * 0.20;
    cChange = 0.10 + seededRandom() * 0.10;
    tip = "自主突围卡脖子技术，硬科技与国家重点重器享受最高政策贴息红利！";
  } else {
    rChange = 0.06 + seededRandom() * 0.06;
    tChange = 0.15 + seededRandom() * 0.12;
    cChange = 0.08 + seededRandom() * 0.08;
    tip = "新质生产力全面领航，战略性新兴产业稳健跨越式复利增长。";
  }

  state.marketTrends.realEstatePrice = Math.max(1000, Math.round(state.marketTrends.realEstatePrice * (1 + rChange)));
  state.marketTrends.realEstateChange = (rChange >= 0 ? '+' : '') + Math.round(rChange * 100) + '%';
  state.marketTrends.realEstateTrend = rChange >= 0 ? 'bull' : 'bear';

  state.marketTrends.techPrice = Math.max(10, Math.round(state.marketTrends.techPrice * (1 + tChange)));
  state.marketTrends.techChange = (tChange >= 0 ? '+' : '') + Math.round(tChange * 100) + '%';
  state.marketTrends.techTrend = tChange >= 0 ? 'bull' : 'bear';

  state.marketTrends.commodityPrice = Math.max(20, Math.round(state.marketTrends.commodityPrice * (1 + cChange)));
  state.marketTrends.commodityChange = (cChange >= 0 ? '+' : '') + Math.round(cChange * 100) + '%';
  state.marketTrends.commodityTrend = cChange >= 0 ? 'bull' : 'bear';

  state.marketTrends.insiderTip = tip;
}

function buyMarketAsset(assetKey, amount) {
  if (state.capital < amount) {
    showToast(`结余资本不足，需 ¥${amount.toLocaleString()}`, 'alert');
    return;
  }
  if (!state.heldAssets) state.heldAssets = { realEstateShares: 0, techShares: 0, commodityShares: 0 };
  state.lastMarketBuyYear = state.lastMarketBuyYear || {};
  state.lastMarketBuyYear[assetKey] = state.year;
  state.capital -= amount;
  state.heldAssets[assetKey] = (state.heldAssets[assetKey] || 0) + amount;
  playSoundEffect('coin');
  showToast(`笃定增持 ¥${(amount/10000)}万 产业标的（跨年沉淀，静待春华秋实）`, 'good');
  requestRender();
}

function sellMarketAsset(assetKey, amount) {
  if (!state.heldAssets || (state.heldAssets[assetKey] || 0) < amount) {
    showToast("持仓份额不足，无法变现平仓！", "alert");
    return;
  }
  if (state.lastMarketBuyYear && state.lastMarketBuyYear[assetKey] === state.year) {
    showToast("新购入份额须跨年度持有（T+1年）方可赎回交割！", "info");
    return;
  }
  state.lastMarketYieldYear = state.lastMarketYieldYear || {};
  const changeStr = state.marketTrends ? (state.marketTrends[assetKey.replace('Shares', 'Change')] || '0%') : '0%';
  let rawRate = (parseFloat(changeStr) || 0) / 100;

  // 特区绝密内参保驾护航：消除一切投资亏损，且顺应风口额外斩获 +12% 特许红利
  const hasIntel = state.specialZoneIntelUnlocked && (!state.specialZoneIntelExpireYear || state.year <= state.specialZoneIntelExpireYear);
  if (hasIntel) {
    if (rawRate < 0) rawRate = 0.05;
    else rawRate += 0.12;
  }

  const rate = (rawRate > 0 && state.lastMarketYieldYear[assetKey] === state.year) ? 1 : (1 + rawRate);
  if (rawRate > 0) state.lastMarketYieldYear[assetKey] = state.year;
  const returnVal = Math.max(0, Math.round(amount * rate));

  state.heldAssets[assetKey] -= amount;
  state.capital += returnVal;
  playSoundEffect('coin');
  showToast(hasIntel
    ? `📡【特区内参兜底兑现】决胜平仓回收活期本金 ¥${returnVal.toLocaleString()}（零亏损保护生效中）！`
    : `落袋为安！决胜平仓回收活期本金 ¥${returnVal.toLocaleString()}`, 'gold');
  requestRender();
}

function openRivalShowdown(rival) {
  if (!rival) return false;
  state.activeRival = rival;
  state.activeModal = 'rival_showdown';
  playSoundEffect('alert');
  triggerHaptic('heavy');
  requestRender();
  return true;
}


