const CLAN_PROFILE_STORAGE_KEY = 'lifesim_clan_profile_v1';
const _clanCloudMod = _loadModule('./src/platform/clanCloudService.js') || {};
let _isClanProfileLoadingFromCloud = false;

function loadClanProfile() {
  try {
    let json = null;
    if (typeof wx !== 'undefined' && typeof wx.getStorageSync === 'function') {
      json = wx.getStorageSync(CLAN_PROFILE_STORAGE_KEY);
    } else if (typeof localStorage !== 'undefined') {
      json = localStorage.getItem(CLAN_PROFILE_STORAGE_KEY);
    }
    if (json) {
      const parsed = typeof json === 'string' ? JSON.parse(json) : json;
      if (parsed && parsed.surname && parsed.hallName) {
        return parsed;
      }
    }
  } catch (e) {
    if (typeof logDebugError === 'function') logDebugError('loadClanProfile failed', e);
  }
  // 若本地为空，尝试从云端拉取跨设备存档迎回宗族 (竞态防御与状态跟踪)
  if (_clanCloudMod && typeof _clanCloudMod.recoverFamilyFromCloud === 'function' && (typeof wx === 'undefined' || (wx && wx.cloud && typeof wx.cloud.callFunction === 'function'))) {
    _isClanProfileLoadingFromCloud = true;
    if (typeof state !== 'undefined' && state) {
      state.isClanProfileLoadingFromCloud = true;
    }
    _clanCloudMod.recoverFamilyFromCloud((err, cloudProfile) => {
      _isClanProfileLoadingFromCloud = false;
      if (typeof state !== 'undefined' && state) {
        state.isClanProfileLoadingFromCloud = false;
      }
      if (cloudProfile && cloudProfile.surname && cloudProfile.hallName) {
        // 关键埋点：云恢复世家成功上报
        reportGameMilestone('clan_cloud_recover_success', {
          familyId: cloudProfile.familyId || '',
          surname: cloudProfile.surname,
          hallName: cloudProfile.hallName,
          ancestorsCount: (cloudProfile.genealogyList && cloudProfile.genealogyList.length) || 0
        });

        if (typeof state !== 'undefined' && state) {
          const localAncestors = (state.familyProfile && state.familyProfile.genealogyList) ? state.familyProfile.genealogyList.length : 0;
          const cloudAncestors = (cloudProfile.genealogyList) ? cloudProfile.genealogyList.length : 0;
          // 本地无档案，或本地仅为刚创建的空壳（0代），而云端有真实先祖记录，迎回并恢复
          if (!state.familyProfile || (localAncestors === 0 && cloudAncestors > 0)) {
            state.familyProfile = cloudProfile;
            try {
              const raw = JSON.stringify(cloudProfile);
              if (typeof wx !== 'undefined' && typeof wx.setStorageSync === 'function') {
                wx.setStorageSync(CLAN_PROFILE_STORAGE_KEY, raw);
              } else if (typeof localStorage !== 'undefined') {
                localStorage.setItem(CLAN_PROFILE_STORAGE_KEY, raw);
              }
            } catch (_) {}
            // 若玩家正停留在立族大典弹窗，立即关闭并顺利继续
            if (state.activeModal === 'clan_establishment') {
              state.activeModal = null;
              if (state._pendingCreationAfterClanEstablishment) {
                state._pendingCreationAfterClanEstablishment = false;
                if (typeof startCharacterCreation === 'function') {
                  startCharacterCreation(false);
                }
              }
            }
            if (typeof showToast === 'function') {
              showToast(`已从云端迎回传世世家：【${cloudProfile.fullName}】！`, 'gold');
            }
            if (typeof requestRender === 'function') requestRender();
          }
        }
      } else {
        // 关键埋点：云恢复世家失败或查无档案
        reportGameMilestone('clan_cloud_recover_failed', {
          error: err ? (err.message || String(err)) : 'NO_CLOUD_PROFILE'
        });
      }
    });
  }
  return null;
}

function compactGenealogyForStorage(profile) {
  if (!profile || !Array.isArray(profile.genealogyList) || profile.genealogyList.length <= 80) {
    return profile;
  }
  const cloned = { ...profile };
  const total = cloned.genealogyList.length;
  const recentThreshold = total - 50; // 最近 50 世保留全部详细字段

  cloned.genealogyList = cloned.genealogyList.map((anc, idx) => {
    // 最近 50 世或名垂青史（S级/四品以上显官）保留完整字段
    if (idx >= recentThreshold || anc.evaluationTier === 'S' || (anc.rankLevel && anc.rankLevel >= 4)) {
      return anc;
    }
    // 早期世代剥离冗余明细字段，保留完整宗族世系档案，彻底防范 1MB LocalStorage 爆仓
    return {
      recordId: anc.recordId,
      playOrder: anc.playOrder,
      generation: anc.generation,
      branchName: anc.branchName,
      eraIndex: anc.eraIndex,
      eraName: anc.eraName,
      successorOrigin: anc.successorOrigin,
      successorRole: anc.successorRole,
      fullName: anc.fullName || anc.name,
      name: anc.fullName || anc.name,
      ziHao: anc.ziHao,
      lifespan: anc.lifespan || anc.reignYears,
      reignYears: anc.reignYears || anc.lifespan,
      officialTitle: anc.officialTitle,
      posthumousTitle: anc.posthumousTitle,
      track: anc.track,
      rankLevel: anc.rankLevel,
      bequeathedMoney: anc.bequeathedMoney,
      prestigeGain: anc.prestigeGain,
      evaluationTier: anc.evaluationTier || 'A',
      compacted: true
    };
  });
  return cloned;
}

function saveClanProfile(profile) {
  if (!profile) return;
  if (typeof state !== 'undefined' && state && state.familyProfile && state.familyProfile.isImmutable) {
    if (profile.surname !== state.familyProfile.surname || profile.province !== state.familyProfile.province) {
      console.warn('[ClanProfile] 家族档案不可更改，拒绝非法篡改姓氏或籍贯');
      return;
    }
  }
  profile.isImmutable = true;
  try {
    const compactProfile = compactGenealogyForStorage(profile);
    const json = JSON.stringify(compactProfile);
    if (typeof wx !== 'undefined' && typeof wx.setStorageSync === 'function') {
      wx.setStorageSync(CLAN_PROFILE_STORAGE_KEY, json);
    } else if (typeof localStorage !== 'undefined') {
      localStorage.setItem(CLAN_PROFILE_STORAGE_KEY, json);
    }
  } catch (e) {
    if (typeof logDebugError === 'function') logDebugError('saveClanProfile failed', e);
  }
  // 触发异步云端同步与防篡改签名上行 (处理服务端防重拒斥并自愈迎回)
  if (_clanCloudMod && typeof _clanCloudMod.syncFamily === 'function') {
    const cloudPayload = compactGenealogyForStorage(profile);
    _clanCloudMod.syncFamily(cloudPayload, (err, res) => {
      if (err && err.message === 'CLAN_ALREADY_EXISTS' && res && res.existingProfile) {
        console.warn('[ClanProfile] 云端已存在传世宗门，客户端以云端档案为准纠偏迎回');
        if (typeof state !== 'undefined' && state) {
          state.familyProfile = res.existingProfile;
          try {
            const raw = JSON.stringify(res.existingProfile);
            if (typeof wx !== 'undefined' && typeof wx.setStorageSync === 'function') {
              wx.setStorageSync(CLAN_PROFILE_STORAGE_KEY, raw);
            } else if (typeof localStorage !== 'undefined') {
              localStorage.setItem(CLAN_PROFILE_STORAGE_KEY, raw);
            }
          } catch (_) {}
          if (typeof showToast === 'function') {
            showToast(`检测到云端传世世家【${res.existingProfile.fullName}】，已为您恢复正统家脉！`, 'gold');
          }
          if (typeof requestRender === 'function') requestRender();
        }
      }
    });
  }
}

