function hasClanRelic(relicId) {
  const fam = (typeof state !== 'undefined' && state && state.familyProfile) ||
              (typeof loadClanProfile === 'function' ? loadClanProfile() : null);
  if (!fam || !fam.clanTrust || !Array.isArray(fam.clanTrust.relics)) return false;
  return fam.clanTrust.relics.some(r => (typeof r === 'string' ? r === relicId : (r && r.id === relicId)));
}

function ensureClanProfileForCurrentRun(allowTestFallback = true) {
  if (state.familyProfile && state.familyProfile.surname) return state.familyProfile;
  let stored = null;
  if (typeof loadClanProfile === 'function') stored = loadClanProfile();
  if (stored && stored.surname) {
    state.familyProfile = stored;
    return state.familyProfile;
  }

  // 严格杜绝在真实游戏运行态中静默伪造随机家族锁定：
  // 立族大典为开局必经之礼，未立族时由 startCharacterCreation 引导唤起立族大典弹窗。
  // 仅在无微信环境的自动化单测 (Node.js) 中保留兜底兼容 mock。
  const isNodeTestEnv = (typeof wx === 'undefined' && typeof process !== 'undefined' && process.env);
  if (!isNodeTestEnv && !allowTestFallback) {
    return null;
  }

  const sName = (state.name && state.name.length > 0) ? state.name[0] : ((state.creation && state.creation.surname) ? state.creation.surname : '陈');
  const prov = (state.birthProfile && state.birthProfile.region && typeof BIRTH_REGIONS !== 'undefined' && BIRTH_REGIONS.find(r => r.id === state.birthProfile.region)) ? '河南' : '河南';
  let hall = '颍川长社房';
  if (_familySystemMod && _familySystemMod.FAMOUS_HALL_MAPPING && _familySystemMod.FAMOUS_HALL_MAPPING[sName]) {
    const rawH = _familySystemMod.FAMOUS_HALL_MAPPING[sName];
    hall = Array.isArray(rawH) ? (rawH[0] || '颍川长社房') : (typeof rawH === 'string' ? rawH : '颍川长社房');
  }
  const openid = (_clanCloudMod && typeof _clanCloudMod.getUserOpenId === 'function')
    ? _clanCloudMod.getUserOpenId()
    : null;
  if (_familySystemMod && typeof _familySystemMod.createFamilyProfile === 'function') {
    state.familyProfile = _familySystemMod.createFamilyProfile(sName, prov, hall, 'study_scholar', null, openid);
  } else {
    state.familyProfile = {
      familyId: `fam_${Date.now()}_${Math.floor(Math.random() * 10000)}`,
      openid: openid,
      surname: sName,
      province: prov,
      hallName: hall,
      fullName: `${prov}·${sName}氏·${hall}`,
      vocationId: 'study_scholar',
      vocationName: '耕读传家',
      isImmutable: true,
      clanTrust: {
        trustFundMoney: 10000,
        prestigeScore: 50,
        ancestralTempleTier: 1,
        relics: [],
        mottoList: [{ era: '立族初训', text: '崇德重道，诗书传家', effectDesc: '初祖手订家箴' }]
      },
      genealogyList: [],
      timeline: { currentEpochIndex: 1, currentYear: 100 }
    };
  }
  // 关键埋点：隐式建族上报
  reportGameMilestone('clan_implicit_created', {
    familyId: state.familyProfile.familyId,
    surname: sName,
    province: prov,
    hallName: hall,
    openid: openid || ''
  });
  if (typeof saveClanProfile === 'function') saveClanProfile(state.familyProfile);
  return state.familyProfile;
}

function evaluatePosthumousTitle(s, arch) {
  s = s || (typeof state !== 'undefined' ? state : {});
  const rep = s.rep || 50;
  const tr = s.track || 'gov';
  const grade = arch ? arch.grade : 'B';
  if (tr === 'gov') {
    if (grade === 'S' || rep >= 85) return '文肃公';
    if (grade === 'A' || rep >= 70) return '忠宪公';
    if (rep >= 50) return '明惠公';
    return '靖穆公';
  } else if (tr === 'biz' || tr === 'trade') {
    if (grade === 'S' || (s.capital || 0) >= 2000000) return '通惠公';
    if (grade === 'A' || (s.capital || 0) >= 500000) return '敦裕公';
    return '兴商公';
  } else if (tr === 'tech' || tr === 'industry') {
    if (grade === 'S' || rep >= 85) return '格致公';
    if (grade === 'A' || rep >= 70) return '工毅公';
    return '宣明公';
  } else if (tr === 'med') {
    if (grade === 'S' || rep >= 85) return '仁康公';
    return '济元公';
  } else if (tr === 'education' || tr === 'art') {
    if (grade === 'S' || rep >= 85) return '文昭公';
    return '博雅公';
  } else if (tr === 'military') {
    if (grade === 'S' || rep >= 85) return '武毅公';
    return '昭武公';
  }
  return rep >= 60 ? '弘德公' : '孝谨公';
}

function generateLifeMotto(s, arch) {
  s = s || (typeof state !== 'undefined' ? state : {});
  const tr = s.track || 'gov';
  if (tr === 'gov') return '清慎勤明，以公心立于天下';
  if (tr === 'biz' || tr === 'trade') return '商道酬信，义利兼达不欺心';
  if (tr === 'tech' || tr === 'industry') return '格物致知，精诚所至金石开';
  if (tr === 'med') return '医者仁心，悬壶救苦庇桑梓';
  if (tr === 'education' || tr === 'art') return '立德立言，培桃育李传道义';
  if (tr === 'military') return '铁骨丹心，守土安民无愧天';
  return '勤勉慎独，耕读继世延家声';
}

function inscribePlayerToClanGenealogy(s, arch) {
  s = s || (typeof state !== 'undefined' ? state : {});
  const fam = ensureClanProfileForCurrentRun();
  if (!fam) return null;

  const curGen = (fam.genealogyList ? fam.genealogyList.length : 0) + 1;
  const pTitle = evaluatePosthumousTitle(s, arch);
  const newMottoText = generateLifeMotto(s, arch);
  const capContribution = Math.max(0, Math.floor((s.capital || 0) * 0.3));
  const prestigeAddition = arch && arch.grade === 'S' ? 120 : (arch && arch.grade === 'A' ? 80 : (arch && arch.grade === 'B' ? 50 : 30));

  const seasonObj = (typeof _seasonConfigMod !== 'undefined' && _seasonConfigMod.getSeasonByYear)
    ? _seasonConfigMod.getSeasonByYear(s.year || 100)
    : ((typeof getSeasonByYear === 'function') ? getSeasonByYear(s.year || 100) : null);
  const y = s.year || 100;
  const isS1HanWei = (fam.currentSeasonId === 'season_1_han_wei' || !fam.currentSeasonId || y <= 300);
  const calcEraIndex = isS1HanWei ? 1 : (seasonObj ? Math.min(15, seasonObj.seasonIndex) : Math.min(15, Math.max(1, Math.floor((y - 100) / 200) + 1)));
  let eraLabel = '汉魏风骨';
  if (isS1HanWei) {
    if (y <= 145) eraLabel = '永元筑基';
    else if (y <= 190) eraLabel = '党锢黄巾';
    else if (y <= 235) eraLabel = '建安风骨';
    else eraLabel = '正始太康';
  } else {
    eraLabel = seasonObj ? seasonObj.name : getDynastyEraName(y);
  }

  const succOrigin = (s.dynasticInheritance && s.dynasticInheritance.successorOrigin) || 'lineage_heir';
  const succRole = (s.dynasticInheritance && s.dynasticInheritance.successorRole) || '宗门嫡长';
  const succBranch = (s.dynasticInheritance && s.dynasticInheritance.branchName) || s.clanBranch || '长房嫡脉';

  const runRecordId = `run_${Date.now()}_${s.name || 'anc'}_${curGen}`;
  const ancestorRecord = {
    recordId: runRecordId,
    isGenerationalRun: true,
    generation: s.lineageGeneration || curGen,
    playOrder: curGen,
    branchName: succBranch,
    eraIndex: calcEraIndex,
    eraName: eraLabel,
    successorOrigin: succOrigin,
    successorRole: succRole,
    fullName: s.name || `${fam.surname}氏传人`,
    ziHao: (s.name && s.name.length > 1) ? `德${s.name.slice(1)}` : '明德',
    lifespan: [Math.max(100, (s.year || 2026) - (s.age || 60)), s.year || 2026],
    officialTitle: `${s.rankName || '基层砥柱'} · ${s.jobTitle || '技术骨干'}`,
    posthumousTitle: pTitle,
    epitaph: (arch && arch.summary) ? arch.summary : '躬耕立世，勤勉为本，德泽后昆。',
    finalDeeds: [
      `【${arch ? arch.title : '勤勉立业'}】（${succRole}）享寿 ${s.age || 60} 岁`,
      `为宗族积淀公积 ${formatCurrency(capContribution, s.year)} · 增添声望 ${prestigeAddition} 分`,
      `传世家规：“${newMottoText}”`
    ],
    bequeathedMoney: s.capital || 0,
    prestigeGain: prestigeAddition,
    track: s.track,
    rankLevel: s.rankLevel || s.govLevel || 1,
    newMotto: {
      era: `第${curGen}世家训`,
      text: newMottoText,
      effectDesc: `${s.name}公毕生践履之训，永庇子孙`
    },
    passedRelic: (s.unlockedHeirlooms && s.unlockedHeirlooms.length > 0)
      ? { id: `relic_${curGen}`, name: `${s.name}公手书遗训与印信` }
      : null,
    recordedTimestamp: Date.now()
  };

  if (clanSystem && typeof clanSystem.recordAncestorToGenealogy === 'function') {
    clanSystem.recordAncestorToGenealogy(fam, ancestorRecord);
  }
  if (_familySystemMod && typeof _familySystemMod.recordAncestorToGenealogy === 'function') {
    _familySystemMod.recordAncestorToGenealogy(fam, ancestorRecord);
  } else {
    fam.genealogyList = fam.genealogyList || [];
    fam.genealogyList.push(ancestorRecord);
    fam.clanTrust = fam.clanTrust || { trustFundMoney: 5000, prestigeScore: 50 };
    fam.clanTrust.trustFundMoney = (fam.clanTrust.trustFundMoney || 0) + capContribution;
    fam.clanTrust.prestigeScore = (fam.clanTrust.prestigeScore || 50) + prestigeAddition;
    fam.clanTrust.mottoList = fam.clanTrust.mottoList || [];
    fam.clanTrust.mottoList.push(ancestorRecord.newMotto);
  }

  s.lastInscribedAncestor = ancestorRecord;
  saveClanProfile(fam);
  return ancestorRecord;
}

// 交互热区管理与零分配对象池 (Hitbox Object Pool)
const HITBOX_OBJECT_POOL = [];
function obtainHitboxObj(id, x, y, width, height, handler, priority) {
  let box = HITBOX_OBJECT_POOL.pop();
  if (!box) {
    box = { id: '', x: 0, y: 0, width: 0, height: 0, handler: null, priority: 0 };
  }
  box.id = id;
  box.x = x;
  box.y = y;
  box.width = width;
  box.height = height;
  box.handler = handler;
  box.priority = priority || 0;
  return box;
}

function recycleHitboxes(list) {
  for (let i = 0; i < list.length; i++) {
    const box = list[i];
    box.handler = null;
    if (HITBOX_OBJECT_POOL.length < 300) {
      HITBOX_OBJECT_POOL.push(box);
    }
  }
  list.length = 0;
}

let hitboxes = [];
function registerHitbox(id, x, y, width, height, handler, priority) {
  hitboxes.push(obtainHitboxObj(id, x, y, width, height, handler, priority));
}

let scrollHitboxes = [];
function registerScrollHitbox(id, x, y, width, height, handler, priority) {
  if (state.activeModal) return;
  scrollHitboxes.push(obtainHitboxObj(id, x, y, width, height, handler, priority));
}

// 按钮触控按下沉降态与微质感反馈追踪 (Touch Pressed Visual Feedback)
let pressedHitboxId = null;

/**
 * 标准化微质感触觉按钮绘制器 (Tactile Physical Button Engine)
 * 统一处理按下检测 (pressedHitboxId)、Y轴物理下沉 (translate dy)、底色加深、边框高亮、文本居中排版与 hitbox 注册
 */
function drawTactileButton(contextOrOpts, maybeOpts) {
  let context, opts;
  if (maybeOpts !== undefined) {
    context = contextOrOpts;
    opts = maybeOpts;
  } else {
    context = (typeof ctx !== 'undefined') ? ctx : contextOrOpts;
    opts = contextOrOpts;
  }

  if (!opts || opts.w <= 0 || opts.h <= 0) return false;

  const {
    id, x, y, w, h,
    radius = 4,
    bg = '#251e22',
    pressedBg = null,
    border = null,
    borderColor = null,
    pressedBorder = null,
    borderWidth = 1,
    text = '',
    font = 'bold 13.5px ' + FONT_CHRONICLE,
    textColor = '#fef08a',
    pressedTextColor = null,
    dy = 0,
    onClick = null,
    priority = 10,
    renderContent = null,
    renderCustom = null,
    isScroll = false
  } = opts;

  const isPressed = (pressedHitboxId === id);

  context.save();
  if (isPressed) {
    // 物理内聚按压缩放 (Scale 0.985 围绕按钮中心，提供玉石压感与金石回弹)
    const btnCx = x + w / 2;
    const btnCy = y + h / 2;
    context.translate(btnCx, btnCy);
    context.scale(0.985, 0.985);
    context.translate(-btnCx, -btnCy);
    if (dy !== 0) {
      context.translate(0, dy);
    }
  }

  let finalBg = bg;
  if (isPressed) {
    finalBg = pressedBg || (
      bg === '#251e22' ? '#171215' :
      (bg === '#1e293b' || bg === '#1f1a1d' || bg === '#221714' || bg === '#1c1519' || bg === '#181216') ? '#130e11' :
      (bg === '#78350f' ? '#592607' :
      (bg === '#0369a1' ? '#075985' :
      (bg === '#991b1b' ? '#7f1d1d' : bg)))
    );
  }

  // 严谨区分“显式声明无边框(null/none/transparent)”与“缺省默认值”
  const hasExplicitNoBorder = border === null || borderColor === null || border === 'none' || border === 'transparent' || borderColor === 'none' || borderColor === 'transparent';
  const rawBorder = hasExplicitNoBorder ? null : (borderColor !== undefined ? borderColor : (border !== undefined ? border : '#785d45'));
  let finalBorder = rawBorder;
  if (isPressed && finalBorder) {
    finalBorder = pressedBorder || (
      rawBorder === '#785d45' || rawBorder === '#856447' ? '#d97706' :
      (rawBorder === '#475569' ? '#856447' :
      (rawBorder === '#f59e0b' ? '#fef08a' :
      (rawBorder === '#38bdf8' ? '#7dd3fc' :
      (rawBorder === '#ef4444' ? '#fca5a5' : rawBorder))))
    );
  }

  // 按钮主体填充与单线金石雅框 (Flat Calligraphic Bones & Traditional Mounting)
  if (finalBg && finalBg !== 'transparent') {
    context.fillStyle = finalBg;
    roundRect(context, x, y, w, h, radius, true, !!finalBorder, finalBorder, borderWidth);

    // 按下时轻微内含琥珀光晕 (落墨凝神反馈，绝无外凸塑料弹簧跳动)
    if (isPressed) {
      context.fillStyle = 'rgba(245, 158, 11, 0.08)';
      roundRect(context, x, y, w, h, radius, true, false);
    }
  } else if (finalBorder && finalBorder !== 'transparent') {
    roundRect(context, x, y, w, h, radius, false, true, finalBorder, borderWidth);
  }

  if (typeof renderContent === 'function') {
    renderContent(context, isPressed);
  } else if (typeof renderCustom === 'function') {
    renderCustom(isPressed, context);
  } else if (text) {
    const elevated = elevateFontSize(font, 10);
    context.font = elevated;
    context.fillStyle = isPressed ? (pressedTextColor || '#ffffff') : textColor;
    context.textAlign = 'center';
    context.textBaseline = 'middle';
    const safeW = Math.max(12, w - 8);
    const displayText = fitText(text, safeW, elevated);
    context.fillText(displayText, x + w / 2, y + h / 2);
  }

  context.restore();

  if (onClick) {
    if (isScroll) {
      registerScrollHitbox(id, x, y, w, h, onClick, priority);
    } else {
      registerHitbox(id, x, y, w, h, onClick, priority);
    }
  }
  return isPressed;
}

