// Toast 队列
let toastQueue = [];
if (typeof global !== 'undefined') global.toastQueue = toastQueue;

function showToast(text, type) {
  if (typeof global !== 'undefined') {
    if (typeof global.onToastPushed === 'function') global.onToastPushed(text, type);
    global.latestToast = { text, type };
  }
  toastQueue.push({
    text: text,
    type: type || 'info',
    alpha: 1.0,
    startTime: Date.now()
  });
  if (toastQueue.length > 3) toastQueue.shift();
  requestRender();
}

function addChronicleItem(age, year, text, tag = "履职", type = "history") {
  state.chronicleHistory.unshift({ age, year, text, tag, type });
  if (state.chronicleHistory.length > 120) {
    state.chronicleHistory.length = 120;
  }
}

