const TIANGAN = ['甲', '乙', '丙', '丁', '戊', '己', '庚', '辛', '壬', '癸'];
const DIZHI = ['子', '丑', '寅', '卯', '辰', '巳', '午', '未', '申', '酉', '戌', '亥'];
const SHENGXIAO = ['鼠', '牛', '虎', '兔', '龙', '蛇', '马', '羊', '猴', '鸡', '狗', '猪'];
const YIJI_LIST = [
  { yi: '笃学立志 踏实苦干', ji: '骄矜浮躁 投机取巧' },
  { yi: '深耕基层 勤俭持家', ji: '孤芳自赏 盲目冒进' },
  { yi: '守望相助 广结善缘', ji: '损人利己 寡恩薄义' },
  { yi: '敢为人先 顺应天时', ji: '墨守成规 畏葸不前' },
  { yi: '孝悌力田 尊师重道', ji: '忘本轻狂 忤逆失和' }
];

function getYearGanzhi(year) {
  const y = year || 100;
  const offset = y - 1984; // 1984 为甲子年
  const tgIdx = (offset % 10 + 10) % 10;
  const dzIdx = (offset % 12 + 12) % 12;
  const str = TIANGAN[tgIdx] + DIZHI[dzIdx] + '年';
  const zodiac = SHENGXIAO[dzIdx];
  const yiji = YIJI_LIST[Math.abs(y) % YIJI_LIST.length];
  return { str, zodiac, yiji: '宜: ' + yiji.yi + '  忌: ' + yiji.ji };
}

// 撕老式黄历飞舞微动效状态
let calendarTearAnim = {
  active: false,
  year: 100,
  ganzhi: '庚子年',
  zodiac: '鼠',
  yiji: '宜: 笃学立志  忌: 骄矜浮躁',
  x: 0,
  y: 0,
  vx: 0,
  vy: 0,
  rot: 0,
  vrot: 0,
  alpha: 0
};

function triggerCalendarTear(newYear) {
  const y = newYear || state.year || 100;
  const gz = getYearGanzhi(y);
  calendarTearAnim = {
    active: true,
    year: y,
    ganzhi: gz.str,
    zodiac: gz.zodiac,
    yiji: gz.yiji,
    x: screenWidth / 2 - 58,
    y: getTopBarH() + 20,
    vx: (fxRandom() - 0.5) * 1.8,
    vy: 2.6,
    rot: (fxRandom() - 0.5) * 0.1,
    vrot: (fxRandom() > 0.5 ? 1 : -1) * 0.02,
    alpha: 1.0
  };
  playSoundEffect('paper');
  triggerHaptic('light');
  if (typeof spawnInspirationSparks === 'function') {
    spawnInspirationSparks(screenWidth / 2, getTopBarH() + 30, 8);
  }
}

// 灵光一闪金色火花粒子系统
let inspirationSparks = [];
function spawnInspirationSparks(cx, cy, count = 20) {
  if (inspirationSparks.length > 60) {
    inspirationSparks.splice(0, inspirationSparks.length - 40);
  }
  const startX = cx || (screenWidth / 2);
  const startY = cy || (screenHeight / 2);
  for (let i = 0; i < count; i++) {
    const angle = fxRandom() * Math.PI * 2;
    const speed = 1.6 + fxRandom() * 4.2;
    inspirationSparks.push({
      x: startX,
      y: startY,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed - 1.2,
      radius: 1.5 + fxRandom() * 2.2,
      color: ['#fef08a', '#f59e0b', '#fbbf24', '#38bdf8', '#ffffff'][Math.floor(fxRandom() * 5)],
      alpha: 1.0,
      decay: 0.025 + fxRandom() * 0.025
    });
  }
}

function getSolarTerm(year, age) {
  const y = year || (state && state.year) || 1992;
  const a = age || (state && state.age) || 22;
  const idx = Math.abs((y * 5 + a * 3) % SOLAR_TERMS.length);
  return SOLAR_TERMS[idx];
}

function drawStar(ctx, cx, cy, spikes, outerRadius, innerRadius, color) {
  let rot = Math.PI / 2 * 3;
  let x = cx;
  let y = cy;
  const step = Math.PI / spikes;

  ctx.save();
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(cx, cy - outerRadius);
  for (let i = 0; i < spikes; i++) {
    x = cx + Math.cos(rot) * outerRadius;
    y = cy + Math.sin(rot) * outerRadius;
    ctx.lineTo(x, y);
    rot += step;

    x = cx + Math.cos(rot) * innerRadius;
    y = cy + Math.sin(rot) * innerRadius;
    ctx.lineTo(x, y);
    rot += step;
  }
  ctx.lineTo(cx, cy - outerRadius);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function drawCinnabarSeal(ctx, text, cx, cy, radius = 34, angle = -0.08, scale = 1.0) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(angle);
  ctx.scale(scale, scale);

  const sealColor = 'rgba(185, 28, 28, 0.95)';
  const sealInnerColor = 'rgba(185, 28, 28, 0.08)';
  const side = Math.round(radius * 1.8);
  const half = side / 2;

  // 汉魏正统方印外廓 (Square Seal with Han Cinnabar Ink)
  ctx.fillStyle = sealInnerColor;
  roundRect(ctx, -half, -half, side, side, 3, true, false);

  // 外重粗边框与内重细回线 (Double Inscription Borders)
  ctx.strokeStyle = sealColor;
  ctx.lineWidth = 2.5;
  roundRect(ctx, -half, -half, side, side, 3, false, true, sealColor, 2.5);

  const innerInset = 3.5;
  ctx.lineWidth = 0.8;
  roundRect(ctx, -half + innerInset, -half + innerInset, side - innerInset * 2, side - innerInset * 2, 1.5, false, true, sealColor, 0.8);

  // 汉印篆文四字经典排版 (右上一、右下一、左上一、左下一；汉魏金石古韵)
  const cleanStr = String(text || '平生无愧').replace(/[★☆\s]/g, '');
  ctx.fillStyle = sealColor;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  if (cleanStr.length === 4) {
    const sealFont = `bold ${Math.round(side * 0.34)}px ` + FONT_CHRONICLE;
    ctx.font = sealFont;
    const offX = side * 0.22;
    const offY = side * 0.22;
    // 传统右向排版：右上 -> 右下 -> 左上 -> 左下
    ctx.fillText(cleanStr[0], offX, -offY);
    ctx.fillText(cleanStr[1], offX, offY);
    ctx.fillText(cleanStr[2], -offX, -offY);
    ctx.fillText(cleanStr[3], -offX, offY);
  } else {
    const sealFont = `bold ${Math.round(side * 0.28)}px ` + FONT_CHRONICLE;
    ctx.font = sealFont;
    ctx.fillText(cleanStr, 0, 0);
  }

  ctx.restore();
}

