  state.butterflyNexus = [];
  state.lifeWaveHistory = [];
  state.lifeTrajectory = [];
  state.trajectoryPoints = [];
  state.memoryAlbum = [];
  state.unlockedMemories = [];
  state.fortuneHexagram = null;
