// ==========================================
// 九、 核心流转驱动与全剧情串联 (tickOneYear)
// ==========================================

// ====================================================================
// 🎒 童年（0~18岁）沙盘推演驱动引擎与高考放榜分流
// ====================================================================

function drawZhuazhouModal() {
  const { x: cardX, y: cardY, w: cardW, h: cardH } = getModalSafeRect(350, 480);

  drawElevatedCard(ctx, cardX, cardY, cardW, cardH, {
    elevation: 2,
    radius: 6,
    bg: '#1c131a',
    borderColor: '#856447',
    borderWidth: 1.5,
    hasCornerOrnaments: true,
    cornerLength: 8
  });

  const cursor = createFlowCursor(cardY + 12, 4);

  // 标题与婴儿徽章
  ctx.save();
  drawTraditionalSealBadge(ctx, 'baby', screenWidth / 2 - 105, cursor.y + 10, 8, COLOR_TOKENS.gold.highlight);
  drawTraditionalSealBadge(ctx, 'baby', screenWidth / 2 + 105, cursor.y + 10, 8, COLOR_TOKENS.gold.highlight);
  ctx.restore();

  const isHanWeiZhua = state && isDynasticEra(state.year);
  const zhuaTitle = isHanWeiZhua ? `周岁初度 · 抓周定乾坤 (${getDynastyEraName(state.year)}世家)` : "周岁初度 · 抓周定乾坤";
  cursor.drawLine(ctx, zhuaTitle, screenWidth / 2, 'titleL', COLOR_TOKENS.gold.highlight, 'center', cardW - 60);
  cursor.drawLine(ctx, isHanWeiZhua ? "试儿设席陈简剑布币，指掌所触皆启门第家运" : "试儿置物辨器识器，指掌所触皆启命运伏线", screenWidth / 2, 'caption', COLOR_TOKENS.gold.primary, 'center', cardW - 32);
  cursor.gap(4);

  const startY = cursor.y;
  const availGridH = cardY + cardH - startY - 12;
  const itemH = Math.max(76, Math.floor((availGridH - 20) / 3));
  const itemW = Math.floor((cardW - 36) / 2);

  const zhuaPool = (isHanWeiZhua && Array.isArray(HAN_WEI_ZHUAZHOU_ITEMS)) ? HAN_WEI_ZHUAZHOU_ITEMS : ZHUAZHOU_ITEMS;
  zhuaPool.forEach((item, idx) => {
    const col = idx % 2;
    const row = Math.floor(idx / 2);
    const ix = cardX + 12 + col * (itemW + 12);
    const iy = startY + row * (itemH + 10);

    drawTactileButton(ctx, {
      id: `zhuazhou_${item.id}`,
      x: ix,
      y: iy,
      w: itemW,
      h: itemH,
      radius: 6,
      bg: '#261b2a',
      border: COLOR_TOKENS.gold.deep,
      borderWidth: 1,
      priority: 100,
      renderContent: (c) => {
        c.textAlign = 'left';
        c.textBaseline = 'top';
        c.font = getTypographyFont('titleM');
        c.fillStyle = COLOR_TOKENS.gold.highlight;
        c.fillText(item.name, ix + 10, iy + 10);

        c.font = getTypographyFont('badge');
        c.fillStyle = COLOR_TOKENS.gold.accent;
        c.fillText(`【${item.domain}】`, ix + 10, iy + 28);

        c.font = getTypographyFont('bodySecondary');
        c.fillStyle = COLOR_TOKENS.text.secondary;
        const lines = wrapTextLines(item.desc, itemW - 20, getTypographyFont('bodySecondary'));
        const lCount = Math.min(3, lines.length);
        for (let li = 0; li < lCount; li++) {
          c.fillText(lines[li], ix + 10, iy + 46 + li * 14);
        }
      },
      onClick: () => {
        state.zhuazhouItem = item;
        registerCausalSeed(item.seed, `抓周：${item.name}`, state.year, item.desc);
        state.childhoodKarmaSeeds = state.childhoodKarmaSeeds || [];
        state.childhoodKarmaSeeds.push({
          id: item.seed,
          age: 1,
          year: state.year,
          title: `抓周：${item.name}`,
          desc: item.desc
        });
        state.tags['seed_' + item.seed] = true;
        state.activeModal = null;
        playSoundEffect('fanfare');
        triggerHaptic('heavy');
        addChronicleItem(
          1,
          state.year,
          `【一周岁抓周】在大红毡毯上，你毫不犹豫地爬向正中，一把牢牢攥紧了【${item.name}】！祖辈长辈抚掌大笑：此子天生注定将是【${item.domain}】的命格！`,
          "命途定鼎",
          "promo"
        );
        showToast(`抓周命定：【${item.name}】！`, 'gold');
        requestRender();
      }
    });
  });

  ctx.restore();
}


