function _matchesProceduralTrack(evtTrack, userTrack) {
  if (evtTrack === 'all') return true;
  if (evtTrack === userTrack) return true;
  const aliasMap = {
    gov: ['gov', 'grassroots', 'official'],
    official: ['official', 'gov'],
    scholar: ['scholar', 'education', 'tech'],
    merchant: ['merchant', 'biz', 'trade'],
    recluse: ['recluse', 'agri', 'grassroots', 'med'],
    tech: ['tech', 'education', 'scholar'],
    biz: ['biz', 'trade', 'merchant'],
    trade: ['trade', 'biz', 'merchant'],
    industry: ['industry', 'military'],
    military: ['military', 'industry', 'gov'],
    agri: ['agri', 'grassroots', 'recluse'],
    grassroots: ['grassroots', 'agri', 'gov', 'recluse'],
    art: ['art', 'education', 'scholar'],
    education: ['education', 'art', 'tech', 'scholar'],
    med: ['med', 'tech', 'art', 'recluse'],
    law: ['law', 'gov', 'art', 'official']
  };
  const allowed = aliasMap[userTrack] || [userTrack];
  return allowed.includes(evtTrack);
}

