function triggerNationalLaurelCeremony() {
  if (state.activeModal) return false;
  const age = state.age;
  if (age >= 68 && age <= 73 && (!state.handledEvents || !state.handledEvents['national_laurel_ceremony'])) {
    if (getStat("resilience", 50) >= 75 || getStat("rep", 0) >= 75) {
      state.handledEvents = state.handledEvents || {};
      state.handledEvents['national_laurel_ceremony'] = true;
      state.activeModal = 'national_laurel';

      playSoundEffect('bianzhong_sacred_hymn');
      triggerScreenShake(8, 400);
      spawnGoldSpiral(screenWidth / 2, screenHeight / 2, 45);
      requestRender();
      return true;
    }
  }
  return false;
}

