function triggerButterflyNexusStage() {
  if (state.activeModal) return false;
  const age = state.age;
  state.butterflyNexus = state.butterflyNexus || [];

  // 1. 检查是否有已种下的链处于 Stage 1，并在中年触发 Stage 2
  for (let record of state.butterflyNexus) {
    if (record.stage === 1) {
      const chain = CASCADING_BUTTERFLY_NEXUS.chains.find(c => c.id === record.chainId);
      if (chain && chain.stage2 && age >= chain.stage2.minAge && age <= chain.stage2.maxAge && !record.stage2Done) {
        record.stage2Done = true;
        record.stage = 2;
        state.lastMajorEventAge = age;

        playSoundEffect('fanfare');
        playSoundEffect('heartbeat_dilemma');
        triggerScreenShake(6, 250);

        openDecisionModal({
          id: 'butterfly_stage2_' + chain.id,
          title: chain.stage2.title,
          desc: chain.stage2.desc,
          choices: chain.stage2.choices.map(c => ({
            ...c,
            text: c.text,
            outcomeText: c.outcomeText,
            effects: c.effects,
            tag: c.tag,
            action: () => {
              playSoundEffect('bell_grand_chime');
              showToast(`🦋【蝴蝶因果·中阶破茧】${c.tag}！`, 'gold');
              addChronicleItem(state.age, state.year, `【因果回响】${chain.stage2.title}：${c.outcomeText}`, c.tag, 'promo');
            }
          }))
        });
        return true;
      }
    }
  }

  // 2. 检查是否有已处于 Stage 2 的链，在晚年触发 Stage 3 终极大成
  for (let record of state.butterflyNexus) {
    if (record.stage === 2) {
      const chain = CASCADING_BUTTERFLY_NEXUS.chains.find(c => c.id === record.chainId);
      if (chain && chain.stage3 && age >= chain.stage3.minAge && age <= chain.stage3.maxAge && !record.stage3Done) {
        record.stage3Done = true;
        record.stage = 3;
        state.lastMajorEventAge = age;

        playSoundEffect('triumph_brass');
        triggerScreenShake(10, 400);

        openDecisionModal({
          id: 'butterfly_stage3_' + chain.id,
          title: chain.stage3.title,
          desc: chain.stage3.desc,
          choices: chain.stage3.choices.map(c => ({
            ...c,
            text: c.text,
            outcomeText: c.outcomeText,
            effects: c.effects,
            tag: c.tag,
            action: () => {
              playSoundEffect('triumph_brass');
              showToast(`👑【蝴蝶因果·大成圆满】${c.tag}！万世垂范！`, 'gold');
              addChronicleItem(state.age, state.year, `【因果大成】${chain.stage3.title}：${c.outcomeText}`, c.tag, 'promo');
            }
          }))
        });
        return true;
      }
    }
  }

  // 3. 青年期初次种下蝴蝶因果之种 (Age 21~32，若未达到上限)
  if (state.butterflyNexus.length < 2 && age >= 21 && age <= 32 && seededRandom() < 0.55) {
    const existingIds = state.butterflyNexus.map(r => r.chainId);
    const availableChains = CASCADING_BUTTERFLY_NEXUS.chains.filter(c => !existingIds.includes(c.id) && age >= c.stage1.minAge && age <= c.stage1.maxAge);
    if (availableChains.length > 0) {
      const pickedChain = availableChains[Math.floor(seededRandom() * availableChains.length)];
      state.lastMajorEventAge = age;

      playSoundEffect('causal_nexus_echo');
      triggerScreenShake(5, 200);

      openDecisionModal({
        id: 'butterfly_stage1_' + pickedChain.id,
        title: pickedChain.stage1.title,
        desc: pickedChain.stage1.desc,
        choices: pickedChain.stage1.choices.map(c => ({
          ...c,
          text: c.text,
          outcomeText: c.outcomeText,
          effects: c.effects,
          tag: c.tag,
          action: () => {
            state.butterflyNexus.push({
              chainId: pickedChain.id,
              name: pickedChain.name,
              stage: 1,
              seedYear: state.year,
              seedAge: state.age,
              choiceTag: c.tag,
              summary: c.outcomeText
            });
            playSoundEffect('bell_grand_chime');
            showToast(`🌱【蝴蝶因果·种下因由】${pickedChain.name}（伏脉千里，数十年后必有回响）`, 'gold');
            addChronicleItem(state.age, state.year, `【因果初萌】${pickedChain.stage1.title}：${c.outcomeText}`, c.tag, 'promo');
          }
        }))
      });
      return true;
    }
  }

  return false;
}

// 沧海横流无常命运触发器
function triggerVicissitudesEvent() {
  if (state.activeModal) return false;
  const age = state.age;

  const eligible = VICISSITUDES_OF_LIFE_ENGINE.events.filter(e => {
    if (state.handledEvents && state.handledEvents['vic_' + e.id]) return false;
    if (e.minAge && age < e.minAge) return false;
    if (e.maxAge && age > e.maxAge) return false;
    return true;
  });

  if (eligible.length === 0) return false;

  const picked = eligible[Math.floor(seededRandom() * eligible.length)];
  state.handledEvents = state.handledEvents || {};
  state.handledEvents['vic_' + picked.id] = true;
  state.lastMajorEventAge = age;

  playSoundEffect('heartbeat_dilemma');
  playSoundEffect('guqin_melancholy');
  triggerScreenShake(7, 300);

  openDecisionModal({
    id: picked.id,
    title: picked.title,
    desc: picked.desc,
    choices: picked.choices.map(c => ({
      ...c,
      text: c.text,
      outcomeText: c.outcomeText,
      effects: c.effects,
      tag: c.tag,
      action: () => {
        playSoundEffect('bell_grand_chime');
        showToast(`【${c.tag}】历经波澜，心性淬炼！`, 'gold');
        addChronicleItem(state.age, state.year, `【人生波澜】${picked.title}：${c.outcomeText}`, c.tag || '沧海横流', 'promo');
      }
    }))
  });

  return true;
}

