// ==========================================
// 🌌 岁月长河：十年/二十年因果回响回收触发器 (Causal Echo Nexus Trigger)
// ==========================================
function checkAndTriggerCausalEchoEvent() {
  if (state.activeModal || (state.age || 0) < 28) return false;
  if (!state.causalSeeds || typeof CAUSAL_ECHO_EVENT_DECK === 'undefined' || !Array.isArray(CAUSAL_ECHO_EVENT_DECK)) return false;

  const currentYear = state.year;
  const currentAge = state.age;

  for (const echoDef of CAUSAL_ECHO_EVENT_DECK) {
    if (state.handledEvents && state.handledEvents['causal_echo_' + echoDef.id]) continue;

    let matchedSeed = null;
    let matchedSeedId = null;
    if (Array.isArray(echoDef.seedId)) {
      for (const sid of echoDef.seedId) {
        if (state.causalSeeds[sid] && !state.causalSeeds[sid].isEchoed) {
          matchedSeed = state.causalSeeds[sid];
          matchedSeedId = sid;
          break;
        }
      }
    } else if (state.causalSeeds[echoDef.seedId] && !state.causalSeeds[echoDef.seedId].isEchoed) {
      matchedSeed = state.causalSeeds[echoDef.seedId];
      matchedSeedId = echoDef.seedId;
    }

    if (!matchedSeed) continue;

    const seedPlantYear = matchedSeed.year || (currentYear - 15);
    const yearsElapsed = currentYear - seedPlantYear;
    if (yearsElapsed >= (echoDef.minYearsElapsed || 10) && currentAge >= (echoDef.minAge || 28) && currentAge <= (echoDef.maxAge || 85)) {
      state.handledEvents = state.handledEvents || {};
      state.handledEvents['causal_echo_' + echoDef.id] = true;
      state.lastMajorEventAge = currentAge;

      const seedTitle = matchedSeed.title || '当年抉择';
      const seedDesc = matchedSeed.desc || seedTitle;
      const seedPlantAge = matchedSeed.age || Math.max(1, currentAge - yearsElapsed);

      openDecisionModal({
        id: `causal_echo_${echoDef.id}_${currentYear}`,
        title: `⚡【命运回响 · 岁月的伏笔】当年“${seedTitle}”的选择回来找你了！`,
        desc: `【草蛇灰线，伏脉千里 · 历经 ${yearsElapsed} 载历史沧桑】\n在 ${seedPlantYear} 年（你当年 ${seedPlantAge} 岁），你曾做出关键抉择：“${seedDesc}”。\n\n${echoDef.scene}`,
        scene: `【草蛇灰线，伏脉千里 · 历经 ${yearsElapsed} 载历史沧桑】\n在 ${seedPlantYear} 年（你当年 ${seedPlantAge} 岁），你曾做出关键抉择：“${seedDesc}”。\n\n${echoDef.scene}`,
        choices: echoDef.choices.map(c => ({
          text: c.text,
          statReq: c.statReq,
          reqVal: c.reqVal,
          effects: c.effects,
          successText: c.successText,
          failText: c.failText,
          echoSeedId: matchedSeedId,
          echoId: `echo_${echoDef.id}_${currentYear}`,
          action: () => {
            triggerCausalEcho(
              `echo_${echoDef.id}_${currentYear}`,
              matchedSeedId,
              echoDef.title,
              currentYear,
              c.successText || echoDef.title
            );
            if (typeof c.action === 'function') c.action(state);
          }
        }))
      });
      return true;
    }
  }
  return false;
}

// 🏛️ 华夏世家大系：历朝重大历史事件触发器 (100~3100年全通史关隘)
function checkAndTriggerHanWeiHistoricalEvent() {
  if (state.activeModal || (state.age || 0) < 16) return false;
  if (!state.year) return false;

  let allChronoEvents = [];
  if (state.year <= 300) {
    allChronoEvents = (_historicalMilieuMod && _historicalMilieuMod.HAN_WEI_CRITICAL_CHRONO_EVENTS) || [];
  } else if (state.year <= 500) {
    allChronoEvents = (_historicalMilieuMod && _historicalMilieuMod.LIU_CHAO_CRITICAL_CHRONO_EVENTS) || [];
  } else if (state.year <= 2100) {
    if (_seasonConfigMod && typeof _seasonConfigMod.getSeasonEvents === 'function') {
      const sIdx = Math.min(10, Math.max(3, Math.floor((state.year - 100) / 200) + 1));
      allChronoEvents = _seasonConfigMod.getSeasonEvents(sIdx) || [];
    } else if (_ancientMasterMod && _ancientMasterMod.EPOCHS_TWO_TO_TEN_DATABASE) {
      const epObj = _ancientMasterMod.EPOCHS_TWO_TO_TEN_DATABASE.find(e => state.year >= e.timeSpan[0] && state.year <= e.timeSpan[1]);
      allChronoEvents = epObj ? (epObj.historicalEvents || []) : [];
    }
  } else {
    allChronoEvents = (_futureFrontierMod && _futureFrontierMod.FUTURE_DECADE_SCENARIOS) || [];
  }
  if (!Array.isArray(allChronoEvents) || allChronoEvents.length === 0) return false;

  for (let i = 0; i < allChronoEvents.length; i++) {
    const hEvt = allChronoEvents[i];
    const evtId = hEvt.id || ('event_' + hEvt.year);
    const evtKey = 'dyn_chrono_' + evtId;
    if (state.handledEvents && state.handledEvents[evtKey]) continue;

    // 触发判定：年份在对应历史大事件年份前后 1 年内 (2100年后未来推演节点前后 5 年内)
    const windowYears = state.year > 2100 ? 5 : 1;
    if (Math.abs(state.year - hEvt.year) <= windowYears) {
      state.handledEvents = state.handledEvents || {};
      state.handledEvents[evtKey] = true;

      const choices = (hEvt.options || []).map((opt) => {
        const costVal = (opt.cost && (opt.cost.money || opt.cost.capital)) || 0;
        let statKey = opt.reqStat;
        if (!statKey) {
          const tr = String(opt.reqTrack || '').toLowerCase();
          if (['official', 'gov', 'politics'].includes(tr)) statKey = 'rep';
          else if (['scholar', 'edu', 'study', 'literature'].includes(tr)) statKey = 'iq';
          else if (['merchant', 'biz', 'trade', 'finance'].includes(tr)) statKey = 'iq';
          else if (['military', 'soldier', 'army'].includes(tr)) statKey = 'courage';
          else if (['recluse', 'hermit', 'taoist'].includes(tr)) statKey = 'clean';
          else if (['medical', 'doctor', 'herb'].includes(tr)) statKey = 'health';
          else if (['craft', 'industry', 'tech', 'engineer'].includes(tr)) statKey = 'iq';
          else if (['agri', 'farmer'].includes(tr)) statKey = 'health';
          else if (['art', 'culture'].includes(tr)) statKey = 'culture';
          else statKey = 'courage';
        }

        // 精准计算门槛与专业契合度：
        let reqThreshold = opt.reqVal;
        if (typeof reqThreshold !== 'number') {
          if (opt.cost && costVal > 0) reqThreshold = 45;
          else if (['courage', 'iq'].includes(statKey)) reqThreshold = 55;
          else if (['rep', 'clean'].includes(statKey)) reqThreshold = 50;
          else reqThreshold = 50;
        }

        // 专业对口加成：若玩家当前赛道/世家主业与选项需求赛道对口，降低门槛 10 点
        const fam = state.familyProfile;
        const curPlayerTrack = String(state.track || (fam && fam.vocationId) || '').toLowerCase();
        const tr = String(opt.reqTrack || '').toLowerCase();
        const isTrackAligned = tr && (
          curPlayerTrack === tr ||
          (tr === 'official' && ['official', 'gov'].includes(curPlayerTrack)) ||
          (tr === 'merchant' && ['merchant', 'biz', 'trade'].includes(curPlayerTrack)) ||
          (tr === 'scholar' && ['scholar', 'tech', 'edu'].includes(curPlayerTrack)) ||
          (tr === 'military' && ['military'].includes(curPlayerTrack)) ||
          (tr === 'recluse' && ['recluse', 'med', 'grassroots'].includes(curPlayerTrack)) ||
          (tr === 'medical' && ['medical', 'med', 'recluse'].includes(curPlayerTrack))
        );
        if (isTrackAligned) {
          reqThreshold = Math.max(30, reqThreshold - 10);
        }

        // 成功时纯收益 (单源扣减：不预先在此扣减 costVal，由统一支付逻辑执行真实扣款)
        const succEff = { ...(opt.successReward || {}) };
        if (typeof succEff.money === 'number') {
          succEff.capital = (succEff.capital || 0) + succEff.money;
        }
        delete succEff.money;
        delete succEff.text;
        delete succEff.heirloom;
        delete succEff.officialTitle;
        delete succEff.newMottoTag;
        delete succEff.southEstateUnlocked;
        delete succEff.branchFlag;

        // 失败时纯惩罚 (由统一扣费与灾害损耗处理，杜绝双重扣除)
        const failEff = { ...(opt.failPenalty || {}) };
        if (typeof failEff.money === 'number') {
          failEff.capital = (failEff.capital || 0) + failEff.money;
        } else if (costVal > 0) {
          // 若已有 upfront cost，且 failPenalty 未显式指定额外金钱损失，则不施加通用 capital 扣减
          failEff.capital = 0;
        }
        delete failEff.money;
        delete failEff.text;

        // 🌟 杏林世家大疫抗性联动 (epidemicResist 真实生效)
        const isEpidemicEvent = String(hEvt.id || '').includes('epidemic') || String(hEvt.title || '').includes('疫') || String(hEvt.title || '').includes('疠');
        if (isEpidemicEvent && (state.epidemicResist > 0 || (state.familyProfile && state.familyProfile.vocationId === 'medical_herb'))) {
          const resistRate = state.epidemicResist || 0.4;
          if (failEff.health && failEff.health < 0) {
            failEff.health = Math.round(failEff.health * (1 - resistRate));
          }
          if (succEff.health) {
            succEff.health += 10;
          }
        }

        const costLabel = costVal > 0 ? `（需消耗 ${formatCurrency(costVal, state.year)}）` : '';

        return {
          text: opt.text + costLabel,
          rawText: opt.text,
          tag: '历史关隘',
          statReq: statKey,
          reqVal: reqThreshold,
          costVal: costVal,
          hasCustomCostHandling: costVal > 0,
          effects: succEff,
          failEffects: failEff,
          successText: (opt.successReward && opt.successReward.text) || (opt.successReward && opt.successReward.chronicleText) || opt.text,
          failText: (opt.failPenalty && opt.failPenalty.text) || (opt.failPenalty && opt.failPenalty.chronicleText) || '行事受阻，未能功成，折损甚众。',
          outcomeText: (opt.successReward && opt.successReward.text) || (opt.successReward && opt.successReward.chronicleText) || opt.text,
          action: (st) => {
            let fam = (st && st.familyProfile) || state.familyProfile;
            if (!fam && typeof ensureClanProfileForCurrentRun === 'function') {
              fam = ensureClanProfileForCurrentRun(true);
            }
            if (fam) {
              if (st && !st.familyProfile) st.familyProfile = fam;
              if (!state.familyProfile) state.familyProfile = fam;
            }
            // 单一数据源：若未在上层扣款，在此执行原子扣费
            if (costVal > 0 && !opt._costPaid) {
              executeChoiceCostDeduction(costVal, st);
              opt._costPaid = true;
            }
            // 杏林医圣特质回响
            if (isEpidemicEvent && (state.epidemicResist > 0 || (fam && fam.vocationId === 'medical_herb'))) {
              if (typeof showToast === 'function') showToast('🌿 【杏林遗泽】凭借世家大医精诚底蕴，化解疫疠兵燹凶险！', 'gold');
            }
            // 商业世家贸易额外红利 (tradeSuccessBonus 真实生效)
            if (succEff.capital && (opt.reqTrack === 'merchant' || String(opt.text || '').includes('商') || String(opt.text || '').includes('货殖')) && state.tradeSuccessBonus) {
              const tradeExtra = Math.round(succEff.capital * state.tradeSuccessBonus);
              state.capital = (state.capital || 0) + tradeExtra;
              if (typeof showToast === 'function') showToast(`🪙 【通商世家】商道敏锐，获额外红利 +¥${tradeExtra.toLocaleString()}`, 'gold');
            }
            // 耕读世家文脉与声誉额外红利 (cultureBonus 真实生效)
            if (state.cultureBonus && (opt.reqTrack === 'scholar' || String(opt.text || '').includes('文') || String(opt.text || '').includes('经') || String(opt.text || '').includes('学'))) {
              const cultRepExtra = Math.max(1, Math.round(5 * state.cultureBonus));
              addStat('rep', cultRepExtra);
              if (typeof showToast === 'function') showToast(`📜 【耕读传家】家学渊源，文名盛传，声望额外 +${cultRepExtra}`, 'gold');
            }
            // 百工机巧科技攻关额外红利 (techInventionBonus 真实生效)
            if (state.techInventionBonus && (opt.reqTrack === 'military' || opt.reqTrack === 'tech' || String(opt.text || '').includes('工') || String(opt.text || '').includes('技') || String(opt.text || '').includes('堡'))) {
              const techIqExtra = Math.max(1, Math.round(6 * state.techInventionBonus));
              addStat('iq', techIqExtra);
              if (typeof showToast === 'function') showToast(`⚒️ 【百工机巧】匠心通达，攻坚得法，智谋额外 +${techIqExtra}`, 'gold');
            }
            if (opt.successReward) {
              if (fam && fam.clanTrust && typeof opt.successReward.clanPrestige === 'number') {
                fam.clanTrust.prestigeScore = (fam.clanTrust.prestigeScore || 50) + opt.successReward.clanPrestige;
              }
              if (opt.successReward.officialTitle) {
                if (st) st.officialTitle = opt.successReward.officialTitle;
                state.officialTitle = opt.successReward.officialTitle;
              }
              if (opt.successReward.relicId || opt.successReward.heirloom) {
                const targetKey = String(opt.successReward.relicId || opt.successReward.heirloom).toLowerCase();
                const relicDb = (_historicalMilieuMod && _historicalMilieuMod.HAN_WEI_RELICS_DATABASE) || [];
                const matchedRelic = relicDb.find(r =>
                  r.id === targetKey ||
                  r.id === 'relic_' + targetKey ||
                  targetKey.includes(r.id.replace('relic_', ''))
                ) || { id: targetKey, name: `${getDynastyEraName(hEvt.year)}传家重宝` };

                if (fam) {
                  fam.clanTrust = fam.clanTrust || {};
                  fam.clanTrust.relics = fam.clanTrust.relics || [];
                  if (!fam.clanTrust.relics.some(r => r.id === matchedRelic.id)) {
                    fam.clanTrust.relics.push(matchedRelic);
                  }
                }
                state.unlockedHeirlooms = state.unlockedHeirlooms || [];
                if (!state.unlockedHeirlooms.includes(matchedRelic.id)) {
                  state.unlockedHeirlooms.push(matchedRelic.id);
                }
                showToast(`🏆 荣获传世重宝【${matchedRelic.name}】！入藏宗祠公积！`, 'gold');
              }
            }
          },
          onFail: (st) => {
            const fam = (st && st.familyProfile) || state.familyProfile || (typeof ensureClanProfileForCurrentRun === 'function' ? ensureClanProfileForCurrentRun(true) : null);
            // 单一数据源：若未在上层扣款，在此执行原子扣费
            if (costVal > 0 && !opt._costPaid) {
              executeChoiceCostDeduction(costVal, st);
              opt._costPaid = true;
            }
            if (opt.failPenalty && fam && fam.clanTrust && typeof opt.failPenalty.clanPrestige === 'number') {
              fam.clanTrust.prestigeScore = Math.max(0, (fam.clanTrust.prestigeScore || 50) + opt.failPenalty.clanPrestige);
            }
          }
        };
      });

      const eraTitle = getDynastyEraName(hEvt.year);
      const ctxText = hEvt.historicalContext || hEvt.context || '大争之世，天下扰攘。名门进退维谷，存亡在此一举。';
      const sourceLine = hEvt.historicalSource ? `\n\n📜【史料考据】${hEvt.historicalSource}` : '';
      openDecisionModal({
        id: evtKey,
        __normalizedP0: true,
        title: `🏛️【${eraTitle} · 公元${hEvt.year}年】${hEvt.title}`,
        desc: `【重大历史转折关隘 · 宗族命运在此一念之间】\n${ctxText}${sourceLine}`,
        choices: choices
      });
      return true;
    }
  }
  return false;
}

