function resolveCurrentRealSeason(optionalTs) {
  const now = (optionalTs !== undefined && optionalTs !== null)
    ? (typeof optionalTs === 'string' ? new Date(optionalTs).getTime() : Number(optionalTs))
    : ((typeof getServerTime === 'function' && getServerTime()) ? getServerTime() : Date.now());
  if (_seasonConfigMod && typeof _seasonConfigMod.getRealSeasonByDate === 'function') {
    const matched = _seasonConfigMod.getRealSeasonByDate(now);
    if (matched) return matched;
  }
  const reg = (_seasonConfigMod && _seasonConfigMod.REAL_WORLD_SEASONS_REGISTRY) || [];
  return reg[0] || {
    realSeasonId: 'RS_2026_Q4_HANWEI',
    realSeasonIndex: 1,
    worldSeasonId: 'season_1_han_wei',
    name: '创世第1赛季 · 汉魏风骨 (100~300年)',
    durationWeeks: 7,
    startDate: '2026-10-15',
    endDate: '2026-12-03',
    frontierYear: 2035,
    leaderboardResetKey: 'rs_1_leaderboard'
  };
}

function syncRealSeason(optionalTs) {
  const active = resolveCurrentRealSeason(optionalTs);
  if (typeof WORLD_CHRONO_CONFIG !== 'undefined') {
    WORLD_CHRONO_CONFIG.realSeason = active;
    WORLD_CHRONO_CONFIG.currentRealSeasonId = active.realSeasonId;
    WORLD_CHRONO_CONFIG.currentWorldSeasonId = active.worldSeasonId;
    WORLD_CHRONO_CONFIG.frontierYear = active.frontierYear || 2035;
  }
  if (typeof state !== 'undefined' && state) {
    state.currentRealSeason = active;
    state.currentRealSeasonId = active.realSeasonId;
    state.currentWorldSeasonId = active.worldSeasonId;
    state.currentFrontierYear = active.frontierYear || 2035;
  }
  return active;
}

