function getDailyChallengeDateStr() {
  if (typeof getTodayDateString === 'function') {
    return getTodayDateString();
  }
  const now = new Date();
  const beijingTime = new Date(now.getTime() + (8 * 60 + now.getTimezoneOffset()) * 60000);
  const y = beijingTime.getFullYear();
  const m = String(beijingTime.getMonth() + 1).padStart(2, '0');
  const d = String(beijingTime.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

function getDailyChallengeSeed(dateStr = getDailyChallengeDateStr()) {
  const clean = String(dateStr).replace(/\D/g, '');
  if (clean.length === 8) {
    const num = parseInt(clean, 10);
    if (!Number.isNaN(num) && num > 0) return num;
  }
  let hash = 0;
  for (let i = 0; i < dateStr.length; i++) {
    hash = (Math.imul(31, hash) + dateStr.charCodeAt(i)) | 0;
  }
  return Math.abs(hash) || 20261014;
}

function calcDailyChallengeScore(targetState = state) {
  if (!targetState) return 0;
  const age = targetState.age || 18;
  const rep = typeof getStat === 'function' ? getStat('rep', 50) : (targetState.rep || 50);
  const clean = typeof getStat === 'function' ? getStat('clean', 70) : (targetState.clean || 70);
  const capital = targetState.capital || 0;
  const medals = (targetState.awardedMedals && targetState.awardedMedals.length) || 0;
  const echoes = (targetState.causalEchoes && targetState.causalEchoes.length) || 0;
  const govLevel = targetState.govLevel || targetState.rankIndex || 1;
  const arch = targetState.endgameArchetype || (typeof evaluateEndgameArchetype === 'function' ? evaluateEndgameArchetype(targetState) : null);
  const gradeBonus = (arch && arch.grade === 'S') ? 1200 : ((arch && arch.grade === 'A') ? 800 : ((arch && arch.grade === 'B') ? 500 : 200));

  const capBonus = Math.min(3000, Math.floor(Math.max(0, capital) / 1000));
  const total = Math.round(age * 120 + rep * 40 + clean * 30 + govLevel * 300 + medals * 500 + echoes * 400 + capBonus + gradeBonus);
  return Math.max(100, total);
}

function uploadDailyChallengeScore(finalScore) {
  const dateStr = (state && state.dailyChallengeDate) || getDailyChallengeDateStr();
  const seed = (state && state.dailyChallengeSeed) || getDailyChallengeSeed(dateStr);
  const theme = (state && state.dailyChallengeTheme) || '全服同命挑战';
  try {
    if (typeof wx !== 'undefined' && typeof wx.setStorageSync === 'function') {
      const bestKey = `daily_challenge_best_${dateStr}`;
      const prevBest = wx.getStorageSync(bestKey) || 0;
      if (finalScore > prevBest) {
        wx.setStorageSync(bestKey, finalScore);
      }
    }
    if (typeof wx !== 'undefined' && typeof wx.getOpenDataContext === 'function') {
      const odc = wx.getOpenDataContext();
      if (odc && typeof odc.postMessage === 'function') {
        odc.postMessage({
          type: 'UPDATE_DAILY_SCORE',
          date: dateStr,
          seed: seed,
          score: finalScore,
          theme: theme,
          name: (state && state.name) || '生员'
        });
      }
    }
  } catch (e) {
    logDebugError('uploadDailyChallengeScore', e);
  }
}

function getDailyChallengeDetails() {
  const dateStr = getDailyChallengeDateStr();
  const seed = getDailyChallengeSeed(dateStr);
  const themeIndex = (Math.abs(seed) % DAILY_CHALLENGE_THEMES.length);
  const theme = DAILY_CHALLENGE_THEMES[themeIndex] || DAILY_CHALLENGE_THEMES[0];
  return { dateStr, seed, themeIndex, theme };
}

function openDailyChallengeModal() {
  state.activeModal = 'daily_challenge_hub';
  playSoundEffect('paper');
  triggerHaptic('light');
  requestRender();
}

function drawDailyChallengeModal() {
  if (!ctx) return;
  const cardW = Math.min(350, screenWidth - 24);
  const cardH = 490;
  const cardX = (screenWidth - cardW) / 2;
  const cardY = Math.max(12, Math.round((screenHeight - cardH) / 2));
  const details = getDailyChallengeDetails();
  const theme = details.theme;

  ctx.save();
  ctx.fillStyle = '#18121f';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, '#f59e0b', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🔥 全服每日同命挑战赛", cardX + cardW / 2, cardY + 16);

  ctx.font = '12px ' + FONT_UI;
  ctx.fillStyle = '#f59e0b';
  ctx.fillText(`📅 今日赛期：${details.dateStr} · 同命溯源码 #${details.seed}`, cardX + cardW / 2, cardY + 40);

  // 时代主题大卡片
  const themeBoxW = cardW - 24;
  const themeBoxH = 265;
  const themeBoxX = cardX + 12;
  const themeBoxY = cardY + 62;

  ctx.fillStyle = 'rgba(26, 20, 32, 0.9)';
  roundRect(ctx, themeBoxX, themeBoxY, themeBoxW, themeBoxH, 8, true, true, '#d97706', 1);

  ctx.textAlign = 'left';
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fde68a';
  ctx.fillText(`【${theme.title}】`, themeBoxX + 12, themeBoxY + 12);

  ctx.font = '12px ' + FONT_UI;
  ctx.fillStyle = '#38bdf8';
  ctx.fillText(`🏛️ 时代坐标：${theme.eraYear} 年 · 阶层起点：${theme.classType}`, themeBoxX + 12, themeBoxY + 36);

  // 苦难背景描述
  ctx.font = '12px ' + FONT_UI;
  ctx.fillStyle = '#cbd5e1';
  const descLines = [
    theme.openingDesc.slice(0, 22),
    theme.openingDesc.slice(22, 44),
    theme.openingDesc.slice(44)
  ].filter(Boolean);
  descLines.forEach((dl, i) => {
    ctx.fillText(dl, themeBoxX + 12, themeBoxY + 60 + i * 20);
  });

  // 时代词条特质
  const buffBoxY = themeBoxY + 126;
  const buffBoxH = 68;
  ctx.fillStyle = 'rgba(180, 83, 9, 0.18)';
  roundRect(ctx, themeBoxX + 10, buffBoxY, themeBoxW - 20, buffBoxH, 6, true, true, '#f59e0b', 1);

  ctx.font = 'bold 12px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("⚡ 时代词条加持与掣肘：", themeBoxX + 18, buffBoxY + 10);

  ctx.font = '11.5px ' + FONT_UI;
  ctx.fillStyle = '#fde68a';
  ctx.fillText(fitText(theme.buffDesc, themeBoxW - 36, '11.5px ' + FONT_UI), themeBoxX + 18, buffBoxY + 32);
  ctx.fillStyle = '#a7f3d0';
  ctx.fillText("比拼 60 岁终局评分与走势图，全服同台竞技！", themeBoxX + 18, buffBoxY + 49);

  // 赛事规则提示
  ctx.font = '11px ' + FONT_UI;
  ctx.fillStyle = '#94a3b8';
  ctx.fillText("※ 全服今日同一确定性随机种子，同一起点直接踏入成年立世与履职。", themeBoxX + 12, themeBoxY + 204);
  ctx.fillText("※ 局终可生成带小程序码的宣纸沉浮走势海报分享战果！", themeBoxX + 12, themeBoxY + 224);

  // 底部两枚按钮
  const btnH = 38;
  const btnY = cardY + cardH - btnH - 16;
  const btnW = Math.floor((cardW - 32) / 2);
  const leftX = cardX + 12;
  const rightX = leftX + btnW + 8;

  drawTactileButton(ctx, {
    id: 'start_daily_challenge_btn',
    x: leftX,
    y: btnY,
    w: btnW,
    h: btnH,
    radius: 6,
    bg: '#991b1b',
    border: '#fde047',
    borderWidth: 1.5,
    text: "⚔️ 投身今日挑战 ➔",
    font: 'bold 13px ' + FONT_CHRONICLE,
    textColor: '#ffffff',
    priority: 100,
    onClick: () => {
      startDailyChallengeRun();
    }
  });

  drawTactileButton(ctx, {
    id: 'close_daily_challenge_btn',
    x: rightX,
    y: btnY,
    w: btnW,
    h: btnH,
    radius: 6,
    bg: '#334155',
    border: '#64748b',
    borderWidth: 1.2,
    text: "✖️ 暂且返回",
    font: 'bold 13px ' + FONT_UI,
    textColor: '#cbd5e1',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      requestRender();
    }
  });

  ctx.restore();
}

function startDailyChallengeRun() {
  const details = getDailyChallengeDetails();
  const theme = details.theme || DAILY_CHALLENGE_THEMES[0];

  // 1. 强制灌注全服今日统一确定性随机种子
  state.runSeed = details.seed;
  if (typeof initDeterministicRandom === 'function') {
    initDeterministicRandom(details.seed);
  }
  if (typeof setRandomSeed === 'function') {
    setRandomSeed(details.seed);
  }
  _gameSeed = details.seed;

  // 2. 调用标准创角初始化流程（重置全局与局内状态、重置数值、生成完整身世档案）
  if (typeof startCharacterCreation === 'function') {
    startCharacterCreation(false);
  }

  // 3. 注入每日同命挑战专属数据
  state.isDailyChallenge = true;
  state.dailyChallengeDate = details.dateStr;
  state.dailyChallengeTheme = theme.title;
  state.dailyChallengeTag = theme.tag;

  // 时代年出生回推：保证成年时恰好置身于时代大潮起点
  state.birthYear = theme.eraYear - 18;
  state.selectedBirthYear = state.birthYear;
  if (state.birthProfile) {
    state.birthProfile.birthYear = state.birthYear;
    if (state.birthProfile.parents) {
      state.birthProfile.parents.classType = theme.classType;
    }
  }

  // 4. 直接倍速求学直奔 18 岁
  if (typeof skipChildhoodToAdulthood === 'function') {
    skipChildhoodToAdulthood();
  }

  // 5. 灌注时代专属词条与苦难修正
  if (typeof theme.initModifier === 'function') {
    theme.initModifier(state);
  }

  addChronicleItem(18, theme.eraYear, `【🔥 每日同命挑战】全服同命于 ${theme.eraYear} 年踏入历史洪流！今日时代主题：【${theme.title}】。${theme.openingDesc}`, '同命挑战', 'promo');

  state.gameScene = 'game';
  playSoundEffect('fanfare');
  triggerHaptic('heavy');
  showToast(`⚔️ 已开启今日同命挑战：【${theme.title}】！`, 'gold');
  requestRender();
}

// ==========================================
// 十二·丁、 宣纸沉浮走势朋友圈海报与系统相册保存系统 (Life Trajectory Poster System)
// ==========================================
function generateLifeTrajectoryPoster(callback) {
  try {
    const posterW = 750;
    const posterH = 1334;
    const posterCanvas = createOffscreenCanvasBuffer(posterW, posterH);
    if (!posterCanvas) {
      if (typeof callback === 'function') callback(null, new Error('Canvas create failed'));
      return null;
    }

    const pCtx = posterCanvas.getContext('2d');
    if (!pCtx) {
      if (typeof callback === 'function') callback(null, new Error('Context2D unavailable'));
      return null;
    }

    // 1. 宣纸底色与水墨基调
    pCtx.save();
    pCtx.fillStyle = '#f6efe2';
    pCtx.fillRect(0, 0, posterW, posterH);

    // 2. 双线回纹宋代边框
    pCtx.strokeStyle = '#b45309';
    pCtx.lineWidth = 4;
    pCtx.strokeRect(20, 20, 710, 1294);

    pCtx.strokeStyle = 'rgba(180, 83, 9, 0.45)';
    pCtx.lineWidth = 1.5;
    pCtx.strokeRect(28, 28, 694, 1278);

    // 3. 顶部印鉴与标题
    pCtx.textAlign = 'center';
    pCtx.textBaseline = 'top';

    const isDaily = !!state.isDailyChallenge;
    const headerTag = isDaily
      ? `🔥 全服每日同命挑战赛 · 终局华章 · 【${state.dailyChallengeTheme || '汉魏风骨'}】`
      : "✦ 华夏世家 · 汉魏风骨沉浮录 ✦";

    pCtx.font = 'bold 22px STKaiti, KaiTi, serif';
    pCtx.fillStyle = '#b45309';
    pCtx.fillText(headerTag, posterW / 2, 54);

    // 传主六旬走势大标题
    pCtx.font = 'bold 38px STKaiti, KaiTi, serif';
    pCtx.fillStyle = '#1c1917';
    pCtx.fillText(`【${state.name || '生员'}】六旬沉浮走势长卷`, posterW / 2, 92);

    // 生卒副标题
    const pClass = (state.birthProfile && state.birthProfile.parents && state.birthProfile.parents.classType) || '耕读传家';
    pCtx.font = '20px PingFang SC, sans-serif';
    const startY = state.birthYear || 100;
    const endY = state.year || (startY + (state.age || 60));
    const subDesc = `公元${startY}年 - 公元${endY}年 · 享年 ${state.age || 60} 岁 · 时任「${state.jobTitle || '名仕'}」 · 门第「${pClass}」`;
    pCtx.fillText(subDesc, posterW / 2, 148);

    // 4. 四维勋业统计徽标卡片
    const statBoxY = 194;
    const statBoxW = 670;
    const statBoxH = 76;
    const statBoxX = 40;

    pCtx.fillStyle = '#eae0cb';
    roundRect(pCtx, statBoxX, statBoxY, statBoxW, statBoxH, 8, true, true, '#b45309', 1.5);

    const capPosterStr = (typeof formatCurrency === 'function') ? formatCurrency(state.capital || 0) : `${((state.capital || 0) / 10000).toFixed(1)}万钱`;
    const sItems = [
      { l: '功名评级', v: `${state.endgameGrade || 'S'} 等` },
      { l: '结余族产', v: capPosterStr },
      { l: '乡里口碑', v: `${getStat('rep', 50)} 分` },
      { l: '世事回响', v: `${(state.causalEchoes && state.causalEchoes.length) || 0} 桩` }
    ];
    const sItemW = statBoxW / 4;
    sItems.forEach((si, idx) => {
      const sx = statBoxX + idx * sItemW + sItemW / 2;
      pCtx.font = '16px PingFang SC, sans-serif';
      pCtx.fillStyle = '#78350f';
      pCtx.fillText(si.l, sx, statBoxY + 14);
      pCtx.font = 'bold 22px STKaiti, KaiTi, serif';
      pCtx.fillStyle = '#991b1b';
      pCtx.fillText(si.v, sx, statBoxY + 38);
    });

    // 5. 核心图表：人生沉浮走势折线长卷
    const graphY = 290;
    const graphW = 670;
    const graphH = 430;
    const graphX = 40;

    pCtx.fillStyle = '#fdfbf7';
    roundRect(pCtx, graphX, graphY, graphW, graphH, 8, true, true, '#b45309', 1.5);

    pCtx.textAlign = 'left';
    pCtx.font = 'bold 22px STKaiti, KaiTi, serif';
    pCtx.fillStyle = '#78350f';
    pCtx.fillText("〔沉浮〕六旬生平沉浮走势长卷", graphX + 16, graphY + 16);

    pCtx.textAlign = 'right';
    pCtx.font = '16px PingFang SC, sans-serif';
    pCtx.fillStyle = '#64748b';
    pCtx.fillText("● 危机风暴  ★ 因果回响  ◆ 岁月高光", graphX + graphW - 16, graphY + 20);

    // 绘制高分辨率折线
    let pts = state.lifeTrajectory || [];
    if (pts.length < 2) {
      pts = [
        { age: 18, score: 50 },
        { age: 28, score: 68, impact: 'echo', eventTag: '成家立业' },
        { age: 38, score: 82, impact: 'peak', eventTag: '履职建功' },
        { age: 48, score: 72, impact: 'crisis', eventTag: '风波化险' },
        { age: 60, score: 90, impact: 'peak', eventTag: '功德圆满' }
      ];
    }

    const padL = 45;
    const padR = 25;
    const padT = 58;
    const padB = 40;
    const pPlotW = graphW - padL - padR;
    const pPlotH = graphH - padT - padB;

    const n = pts.length;
    const minAge = pts[0].age;
    const maxAge = Math.max(minAge + 10, pts[n - 1].age);
    let minScore = 9999, maxScore = -9999;
    for (let i = 0; i < n; i++) {
      if (pts[i].score < minScore) minScore = pts[i].score;
      if (pts[i].score > maxScore) maxScore = pts[i].score;
    }
    minScore = Math.max(0, minScore - 10);
    maxScore = maxScore + 10;
    const scoreSpan = Math.max(20, maxScore - minScore);
    const ageSpan = (maxAge - minAge) || 1;

    // 水平刻度线
    pCtx.strokeStyle = 'rgba(180, 83, 9, 0.2)';
    pCtx.lineWidth = 1;
    for (let s = 0; s <= 3; s++) {
      const ly = graphY + padT + (pPlotH / 3) * s;
      pCtx.beginPath();
      pCtx.moveTo(graphX + padL, ly);
      pCtx.lineTo(graphX + graphW - padR, ly);
      pCtx.stroke();
    }

    // 计算点坐标
    const coords = pts.map(p => ({
      x: graphX + padL + ((p.age - minAge) / ageSpan) * pPlotW,
      y: graphY + padT + pPlotH - ((p.score - minScore) / scoreSpan) * pPlotH,
      pt: p
    }));

    // 渐变面积填充
    const fillGrad = pCtx.createLinearGradient(0, graphY + padT, 0, graphY + padT + pPlotH);
    fillGrad.addColorStop(0, 'rgba(180, 83, 9, 0.28)');
    fillGrad.addColorStop(1, 'rgba(180, 83, 9, 0)');
    pCtx.fillStyle = fillGrad;
    pCtx.beginPath();
    const baseY = graphY + padT + pPlotH;
    pCtx.moveTo(coords[0].x, baseY);
    coords.forEach(c => pCtx.lineTo(c.x, c.y));
    pCtx.lineTo(coords[coords.length - 1].x, baseY);
    pCtx.closePath();
    pCtx.fill();

    // 水墨曲线描边
    pCtx.strokeStyle = '#b45309';
    pCtx.lineWidth = 3.8;
    pCtx.lineJoin = 'round';
    pCtx.beginPath();
    pCtx.moveTo(coords[0].x, coords[0].y);
    for (let i = 1; i < coords.length; i++) {
      pCtx.lineTo(coords[i].x, coords[i].y);
    }
    pCtx.stroke();

    // 标记节点
    coords.forEach(c => {
      const p = c.pt;
      if (!p.impact) return;
      if (p.impact === 'crisis') {
        pCtx.fillStyle = '#dc2626';
        pCtx.beginPath();
        pCtx.arc(c.x, c.y, 6.5, 0, Math.PI * 2);
        pCtx.fill();
        if (p.eventTag) {
          pCtx.font = '16px STKaiti, KaiTi, serif';
          pCtx.fillStyle = '#dc2626';
          pCtx.textAlign = 'center';
          pCtx.fillText(p.eventTag, c.x, c.y - 12);
        }
      } else if (p.impact === 'echo') {
        pCtx.fillStyle = '#d97706';
        pCtx.beginPath();
        pCtx.arc(c.x, c.y, 7.5, 0, Math.PI * 2);
        pCtx.fill();
        if (p.eventTag) {
          pCtx.font = 'bold 16px STKaiti, KaiTi, serif';
          pCtx.fillStyle = '#b45309';
          pCtx.textAlign = 'center';
          pCtx.fillText(p.eventTag, c.x, c.y - 14);
        }
      } else if (p.impact === 'peak') {
        pCtx.fillStyle = '#0284c7';
        pCtx.beginPath();
        pCtx.arc(c.x, c.y, 6.5, 0, Math.PI * 2);
        pCtx.fill();
        if (p.eventTag) {
          pCtx.font = 'bold 16px STKaiti, KaiTi, serif';
          pCtx.fillStyle = '#0369a1';
          pCtx.textAlign = 'center';
          pCtx.fillText(p.eventTag, c.x, c.y - 12);
        }
      }
    });

    // 6. 史官赞辞卡片
    const textY = 740;
    const textW = 670;
    const textH = 280;
    const textX = 40;

    pCtx.fillStyle = '#fcf9f2';
    roundRect(pCtx, textX, textY, textW, textH, 8, true, true, '#cbd5e1', 1);

    pCtx.textAlign = 'left';
    pCtx.font = 'bold 22px STKaiti, KaiTi, serif';
    pCtx.fillStyle = '#78350f';
    pCtx.fillText("〔赞辞〕太史公曰 · 终局赞辞", textX + 16, textY + 16);

    const memoir = state.activeMemoir || (typeof generateLifetimeMemoir === 'function' ? generateLifetimeMemoir() : null);
    const keyMoments = (memoir && memoir.keyMoments) || [
      '历经半生风霜砥砺，始终守正奉公。',
      '于时代浪潮关口敢破敢立，造福一隅。',
      '传家有训，门风端方，功名载于青史。'
    ];

    pCtx.font = '19px STKaiti, KaiTi, serif';
    pCtx.fillStyle = '#334155';
    keyMoments.slice(0, 4).forEach((km, idx) => {
      pCtx.fillText(`• ${fitText(km, textW - 140, '19px STKaiti, KaiTi, serif')}`, textX + 20, textY + 54 + idx * 36);
    });

    if (memoir && memoir.epitaph) {
      pCtx.font = 'bold 18px STKaiti, KaiTi, serif';
      pCtx.fillStyle = '#b45309';
      pCtx.fillText(`《铭赋》：${memoir.epitaph}`, textX + 20, textY + 220);
    }

    // 四象座右铭朱印 (drawCinnabarSeal)
    const isHanWeiPoster = (state.year && state.year <= 500) || (typeof isDynasticEra === 'function' && isDynasticEra(state.year));
    const sealText = isDaily ? "同命无悔" : (isHanWeiPoster ? (state.clean >= 75 ? "清操素砺" : (state.rep >= 70 ? "社稷之栋" : "家声克振")) : (state.clean >= 75 ? "廉洁奉公" : (state.rep >= 70 ? "大国栋梁" : "平生无愧")));
    if (typeof drawCinnabarSeal === 'function') {
      drawCinnabarSeal(pCtx, sealText, textX + textW - 65, textY + textH - 65, 38, -0.10, 1.15);
    } else {
      pCtx.fillStyle = '#b91c1c';
      pCtx.fillRect(textX + textW - 105, textY + textH - 100, 85, 85);
      pCtx.strokeStyle = '#fef08a';
      pCtx.lineWidth = 1.5;
      pCtx.strokeRect(textX + textW - 101, textY + textH - 96, 77, 77);
      pCtx.textAlign = 'center';
      pCtx.font = 'bold 20px STKaiti, KaiTi, serif';
      pCtx.fillStyle = '#fef08a';
      pCtx.fillText(sealText.slice(0, 2), textX + textW - 62, textY + textH - 84);
      pCtx.fillText(sealText.slice(2), textX + textW - 62, textY + textH - 52);
    }

    // 7. 底部朋友圈转化导流区 (小程序太阳码)
    const footY = 1040;
    const footW = 670;
    const footH = 240;
    const footX = 40;

    pCtx.fillStyle = '#f2ebdc';
    roundRect(pCtx, footX, footY, footW, footH, 10, true, true, '#b45309', 1.5);

    pCtx.textAlign = 'left';
    pCtx.font = 'bold 24px STKaiti, KaiTi, serif';
    pCtx.fillStyle = '#78350f';
    pCtx.fillText("✦ 风华年代 · 沧海沉浮录 ✦", footX + 22, footY + 28);

    pCtx.font = 'bold 19px PingFang SC, sans-serif';
    pCtx.fillStyle = '#b45309';
    pCtx.fillText(`全服同命溯源码: #${state.runSeed || '19780101'}`, footX + 22, footY + 68);

    pCtx.font = '17px PingFang SC, sans-serif';
    pCtx.fillStyle = '#64748b';
    pCtx.fillText(isHanWeiPoster ? "扫描右侧小程序码，入局汉魏世家大系" : "扫描右侧小程序码，开启属于你的风华甲子", footX + 22, footY + 104);
    pCtx.fillText(isHanWeiPoster ? "比拼三百年门阀底蕴与全服世家榜单" : "比拼 60 岁沉浮走势折线图与全服榜单", footX + 22, footY + 132);

    pCtx.font = 'bold 16px PingFang SC, sans-serif';
    pCtx.fillStyle = '#15803d';
    pCtx.fillText("✓ 微信小游戏 · 一键即玩无需下载", footX + 22, footY + 172);

    // 绘制精致矢量小程序太阳码 (Sun Code)
    const codeCx = footX + footW - 105;
    const codeCy = footY + 115;
    const outerR = 60;
    const innerR = 46;

    // 太阳码外圈花瓣光芒
    pCtx.save();
    pCtx.translate(codeCx, codeCy);
    pCtx.fillStyle = '#b45309';
    for (let r = 0; r < 24; r++) {
      const rad = (r * Math.PI * 2) / 24;
      pCtx.beginPath();
      pCtx.arc(Math.cos(rad) * (outerR - 2), Math.sin(rad) * (outerR - 2), 5, 0, Math.PI * 2);
      pCtx.fill();
    }

    // 太阳码白底核心
    pCtx.fillStyle = '#ffffff';
    pCtx.beginPath();
    pCtx.arc(0, 0, innerR, 0, Math.PI * 2);
    pCtx.fill();
    pCtx.strokeStyle = '#b45309';
    pCtx.lineWidth = 2;
    pCtx.stroke();

    // 太阳码中心风华金石圆印
    pCtx.fillStyle = '#991b1b';
    pCtx.beginPath();
    pCtx.arc(0, 0, 26, 0, Math.PI * 2);
    pCtx.fill();

    pCtx.font = 'bold 16px STKaiti, KaiTi, serif';
    pCtx.fillStyle = '#fef08a';
    pCtx.textAlign = 'center';
    pCtx.textBaseline = 'middle';
    pCtx.fillText("风华", 0, 0);
    pCtx.restore();

    pCtx.textAlign = 'center';
    pCtx.font = '14px PingFang SC, sans-serif';
    pCtx.fillStyle = '#78350f';
    pCtx.fillText("微信小程序码", codeCx, codeCy + outerR + 18);

    pCtx.restore();

    // 缓存离屏 Canvas 供页面预览调用
    state.lastGeneratedPosterCanvas = posterCanvas;

    // 导出临时图片路径
    let tempPath = null;
    if (typeof posterCanvas.toTempFilePathSync === 'function') {
      try {
        tempPath = posterCanvas.toTempFilePathSync({
          x: 0,
          y: 0,
          width: posterW,
          height: posterH,
          destWidth: posterW,
          destHeight: posterH,
          fileType: 'png',
          quality: 1.0
        });
        state.lastGeneratedPosterPath = tempPath;
        if (typeof callback === 'function') callback(tempPath);
        return tempPath;
      } catch (syncErr) {
        logDebugError('generateLifeTrajectoryPoster sync', syncErr);
      }
    }

    if (typeof posterCanvas.toTempFilePath === 'function') {
      posterCanvas.toTempFilePath({
        x: 0,
        y: 0,
        width: posterW,
        height: posterH,
        destWidth: posterW,
        destHeight: posterH,
        fileType: 'png',
        quality: 1.0,
        success: (res) => {
          state.lastGeneratedPosterPath = res.tempFilePath;
          if (typeof callback === 'function') callback(res.tempFilePath);
        },
        fail: (err) => {
          logDebugError('generateLifeTrajectoryPoster async', err);
          if (typeof callback === 'function') callback(null, err);
        }
      });
      return null;
    }

    if (typeof callback === 'function') callback(null);
    return null;
  } catch (err) {
    logDebugError('generateLifeTrajectoryPoster', err);
    if (typeof callback === 'function') callback(null, err);
    return null;
  }
}

function shareLifeTrajectoryPosterToMoments() {
  showToast('📜 正在精工摹绘宣纸丹青长卷...', 'info');

  generateLifeTrajectoryPoster((tempFilePath, err) => {
    if (!tempFilePath || err) {
      showToast('⚠️ 丹青长卷摹绘受阻，请稍候再试', 'alert');
      return;
    }

    if (typeof wx !== 'undefined' && typeof wx.showShareImageMenu === 'function') {
      wx.showShareImageMenu({
        path: tempFilePath,
        success: () => {
          playSoundEffect('fanfare');
          triggerHaptic('heavy');
          showToast('🖼️ 丹青长卷已就绪，已唤起朋友圈/好友分享！', 'gold');
        },
        fail: (shareErr) => {
          logDebugError('showShareImageMenu', shareErr);
          saveLifeTrajectoryPosterToAlbum();
        }
      });
    } else {
      saveLifeTrajectoryPosterToAlbum();
    }
  });
}

function saveLifeTrajectoryPosterToAlbum() {
  const saveApi = (typeof wx !== 'undefined' && typeof wx.saveImageToPhotosAlbum === 'function')
    ? wx.saveImageToPhotosAlbum.bind(wx)
    : ((typeof tt !== 'undefined' && typeof tt.saveImageToPhotosAlbum === 'function')
      ? tt.saveImageToPhotosAlbum.bind(tt)
      : null);

  if (!saveApi) {
    showToast('⚠️ 当前运行环境未提供相册写入能力，可直接长按截屏保存', 'info');
    return;
  }

  showToast('📜 正在精工摹绘宣纸海报...', 'info');

  generateLifeTrajectoryPoster((tempFilePath, err) => {
    if (!tempFilePath || err) {
      showToast('⚠️ 海报生成受阻，请稍候再试', 'alert');
      return;
    }

    saveApi({
      filePath: tempFilePath,
      success: () => {
        playSoundEffect('fanfare');
        triggerHaptic('heavy');
        showToast('🖼️ 宣纸长卷海报已保存至相册，快发朋友圈吧！', 'gold');
      },
      fail: (saveErr) => {
        const errMsg = (saveErr && saveErr.errMsg) || '';
        if (errMsg.includes('auth deny') || errMsg.includes('auth denied') || errMsg.includes('authorize:fail')) {
          const openSettingApi = (typeof wx !== 'undefined' && typeof wx.openSetting === 'function')
            ? wx.openSetting
            : ((typeof tt !== 'undefined' && typeof tt.openSetting === 'function') ? tt.openSetting : null);

          if (openSettingApi) {
            showToast('⚠️ 请在设置界面开启相册保存授权', 'alert');
            try {
              openSettingApi();
            } catch (_) {}
          } else {
            showToast('⚠️ 保存失败，请在小游戏权限设置中允许相册写入', 'alert');
          }
        } else {
          showToast('⚠️ 写入相册未果，可直接截屏长卷保存', 'info');
        }
      }
    });
  });
}

function openLifeTrajectoryPosterModal() {
  state.activeModal = 'life_trajectory_poster';
  playSoundEffect('paper');
  triggerHaptic('light');
  generateLifeTrajectoryPoster(() => {
    requestRender();
  });
  requestRender();
}

function drawLifeTrajectoryPosterModal() {
  if (!ctx) return;
  const cardW = Math.min(356, screenWidth - 20);
  const cardH = 525;
  const cardX = (screenWidth - cardW) / 2;
  const cardY = Math.max(10, Math.round((screenHeight - cardH) / 2));

  ctx.save();
  ctx.fillStyle = '#1c1524';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, '#f59e0b', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🖼️ 岁月华章 · 宣纸沉浮走势长卷", cardX + cardW / 2, cardY + 12);

  // 海报缩略预览框
  const previewW = cardW - 24;
  const previewH = 415;
  const previewX = cardX + 12;
  const previewY = cardY + 36;

  if (state.lastGeneratedPosterCanvas) {
    try {
      ctx.drawImage(state.lastGeneratedPosterCanvas, previewX, previewY, previewW, previewH);
    } catch (_) {
      _drawPosterVectorFallback(ctx, previewX, previewY, previewW, previewH);
    }
  } else {
    _drawPosterVectorFallback(ctx, previewX, previewY, previewW, previewH);
  }

  // 底部三枚按钮：发朋友圈/好友 & 保存到相册 & 返回
  const btnH = 38;
  const btnY = cardY + cardH - btnH - 12;
  const btnGap = 6;
  const btnW = Math.floor((cardW - 24 - btnGap * 2) / 3);
  const leftX = cardX + 12;
  const midX = leftX + btnW + btnGap;
  const rightX = midX + btnW + btnGap;

  drawTactileButton(ctx, {
    id: 'poster_share_moments_btn',
    x: leftX,
    y: btnY,
    w: btnW,
    h: btnH,
    radius: 6,
    bg: '#065f46',
    border: '#34d399',
    borderWidth: 1.5,
    text: "📤 发朋友圈",
    font: 'bold 11.5px ' + FONT_CHRONICLE,
    textColor: '#a7f3d0',
    priority: 100,
    onClick: () => {
      shareLifeTrajectoryPosterToMoments();
    }
  });

  drawTactileButton(ctx, {
    id: 'poster_save_album_btn',
    x: midX,
    y: btnY,
    w: btnW,
    h: btnH,
    radius: 6,
    bg: '#b45309',
    border: '#f59e0b',
    borderWidth: 1.5,
    text: "💾 存到相册",
    font: 'bold 11.5px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      saveLifeTrajectoryPosterToAlbum();
    }
  });

  drawTactileButton(ctx, {
    id: 'poster_close_modal_btn',
    x: rightX,
    y: btnY,
    w: btnW,
    h: btnH,
    radius: 6,
    bg: '#334155',
    border: '#64748b',
    borderWidth: 1.2,
    text: "✖️ 返回",
    font: 'bold 11.5px ' + FONT_UI,
    textColor: '#cbd5e1',
    priority: 100,
    onClick: () => {
      state.activeModal = 'endgame';
      playSoundEffect('paper');
      requestRender();
    }
  });

  ctx.restore();
}

function _drawPosterVectorFallback(c, x, y, w, h) {
  c.save();
  c.fillStyle = '#f6efe2';
  roundRect(c, x, y, w, h, 6, true, true, '#b45309', 1.5);

  c.textAlign = 'center';
  c.textBaseline = 'top';
  c.font = 'bold 14px ' + FONT_CHRONICLE;
  c.fillStyle = '#78350f';
  c.fillText(`【${state.name || '生员'}】六旬沉浮走势长卷`, x + w / 2, y + 16);

  c.font = '11px ' + FONT_UI;
  c.fillStyle = '#b45309';
  c.fillText(`全服同命溯源码: #${state.runSeed || '888888'}`, x + w / 2, y + 38);

  // 简要曲线
  c.strokeStyle = '#b45309';
  c.lineWidth = 2;
  c.beginPath();
  c.moveTo(x + 20, y + h * 0.55);
  c.lineTo(x + w * 0.35, y + h * 0.42);
  c.lineTo(x + w * 0.65, y + h * 0.62);
  c.lineTo(x + w - 20, y + h * 0.36);
  c.stroke();

  c.font = '12px ' + FONT_UI;
  c.fillStyle = '#475569';
  c.fillText("📜 宣纸长卷渲染中... 点击下方按钮直接存入相册", x + w / 2, y + h * 0.76);
  c.restore();
}

function openEndgameCodexModal() {
  state._previousModalBeforeCodex = state.activeModal;
  state.activeModal = 'endgame_codex';
  state.codexGradeFilter = state.codexGradeFilter || 'S';
  playSoundEffect('paper');
  triggerHaptic('light');
  requestRender();
}

function drawEndgameCodexModal() {
  const cardW = screenWidth - 28;
  const cardH = 490;
  const cardX = 14;
  const cardY = Math.max(12, Math.round((screenHeight - cardH) / 2));

  ctx.save();
  ctx.fillStyle = 'rgba(26, 20, 24, 0.96)';
  roundRect(ctx, cardX, cardY, cardW, cardH, 4, true, true, '#856447', 1.5);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#d97706');

  // 标题
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  drawTraditionalSealBadge(ctx, 'scroll', screenWidth / 2 - 126, cardY + 23, 9, '#fef08a');
  ctx.fillText("宿 命 图 鉴 · 百 代 浮 生 结 卷", screenWidth / 2 + 6, cardY + 14);
  drawTraditionalSealBadge(ctx, 'scroll', screenWidth / 2 + 138, cardY + 23, 9, '#fef08a');

  // 进度统计
  const unlocked = true ? getUnlockedEndings() : [];
  const totalCount = ENDGAME_ARCHETYPES_16.length;
  const unlockedCount = unlocked.length;
  const pct = Math.round((unlockedCount / totalCount) * 100);

  ctx.font = '12px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#d4c7b8';
  ctx.fillText(`“凡百事之成也，必在敬之” · 宿命解锁进度：${unlockedCount} / ${totalCount} (${pct}%)`, screenWidth / 2, cardY + 36);

  // 评级分签：[S·巅峰 (12)] [A·名家 (13)] [B·中坚 (5)] [C·警醒 (3)]
  const activeGrade = state.codexGradeFilter || 'S';
  const sCount = ENDGAME_ARCHETYPES_16.filter(a => a.grade === 'S').length;
  const aCount = ENDGAME_ARCHETYPES_16.filter(a => a.grade === 'A').length;
  const bCount = ENDGAME_ARCHETYPES_16.filter(a => a.grade === 'B').length;
  const cCount = ENDGAME_ARCHETYPES_16.filter(a => a.grade === 'C').length;
  const grades = [
    { key: 'S', label: `S·巅峰 (${sCount})`, color: '#fbbf24' },
    { key: 'A', label: `A·名家 (${aCount})`, color: '#34d399' },
    { key: 'B', label: `B·中坚 (${bCount})`, color: '#f59e0b' },
    { key: 'C', label: `C·警醒 (${cCount})`, color: '#cbd5e1' }
  ];
  const tabW = Math.floor((cardW - 32 - 18) / 4);
  const tabH = 26;
  const tabY = cardY + 56;

  grades.forEach((g, idx) => {
    const tx = cardX + 16 + idx * (tabW + 6);
    const isAct = activeGrade === g.key;
    drawTactileButton(ctx, {
      id: `codex_tab_${g.key}`,
      x: tx,
      y: tabY,
      w: tabW,
      h: tabH,
      radius: 4,
      bg: isAct ? '#38241b' : '#1f1618',
      border: isAct ? g.color : '#5c3a21',
      borderWidth: isAct ? 1.5 : 1,
      text: g.label,
      font: (isAct ? 'bold ' : '') + '12px ' + FONT_CHRONICLE,
      textColor: isAct ? g.color : '#8c7662',
      priority: 100,
      onClick: () => {
        state.codexGradeFilter = g.key;
        state.codexPage = 0;
        playSoundEffect('click');
        triggerHaptic('light');
        requestRender();
      }
    });
  });

  // 结局条目分页列表展示
  const allGradeItems = ENDGAME_ARCHETYPES_16.filter(a => a.grade === activeGrade);
  const pageSize = 4;
  const totalPages = Math.ceil(allGradeItems.length / pageSize) || 1;
  const curPage = Math.min(totalPages - 1, Math.max(0, state.codexPage || 0));
  state.codexPage = curPage;
  const items = allGradeItems.slice(curPage * pageSize, (curPage + 1) * pageSize);

  const listY = tabY + tabH + 8;
  const itemH = 68;
  const itemW = cardW - 32;

  items.forEach((item, idx) => {
    const iy = listY + idx * (itemH + 6);
    const isUnlocked = unlocked.includes(item.id);
    const gradeColor = grades.find(g => g.key === item.grade)?.color || '#f59e0b';

    ctx.fillStyle = isUnlocked ? 'rgba(38, 28, 22, 0.95)' : 'rgba(20, 15, 18, 0.95)';
    roundRect(ctx, cardX + 16, iy, itemW, itemH, 4, true, true, isUnlocked ? gradeColor : '#5c3a21', 1);

    // 第一行：标题与解锁状态
    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 13.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = isUnlocked ? gradeColor : '#8c7662';

    const titleText = isUnlocked ? `【${item.grade}级 · ${item.title}】` : `🔒 【${item.grade}级 · ${item.title}】`;
    ctx.fillText(titleText, cardX + 26, iy + 8);

    ctx.textAlign = 'right';
    ctx.font = '12px ' + FONT_CHRONICLE;
    ctx.fillStyle = isUnlocked ? '#6ee7b7' : '#8c7662';
    ctx.fillText(isUnlocked ? '✓ 已点亮' : '🔒 未解锁', cardX + 16 + itemW - 10, iy + 9);

    // 第二、三行：生平评语与破局指引
    ctx.textAlign = 'left';
    ctx.font = '12px ' + FONT_CHRONICLE;
    if (isUnlocked) {
      ctx.fillStyle = '#c8bbae';
      ctx.fillText(fitText(`生平：“${item.desc || ''}”`, itemW - 20, '12px ' + FONT_CHRONICLE), cardX + 26, iy + 28);
      ctx.fillStyle = '#a7f3d0';
      ctx.fillText(fitText(`要义：${item.hint || ''}`, itemW - 20, '12px ' + FONT_CHRONICLE), cardX + 26, iy + 48);
    } else {
      ctx.fillStyle = '#fbbf24';
      ctx.fillText(fitText(`破局指引：${item.hint || ''}`, itemW - 20, '12px ' + FONT_CHRONICLE), cardX + 26, iy + 28);
      ctx.fillStyle = '#8c7662';
      ctx.fillText(fitText(`下局线索：调整人生赛道与关键转折属性`, itemW - 20, '12px ' + FONT_CHRONICLE), cardX + 26, iy + 48);
    }
  });

  // 分页翻页栏与底部关闭按钮
  const pagerY = listY + pageSize * (itemH + 6) + 4;
  if (totalPages > 1) {
    const pageBtnW = 68;
    const pageBtnH = 24;
    drawTactileButton(ctx, {
      id: 'codex_prev_page_btn',
      x: cardX + 20,
      y: pagerY,
      w: pageBtnW,
      h: pageBtnH,
      radius: 4,
      bg: curPage > 0 ? '#38241b' : 'rgba(31, 22, 24, 0.4)',
      border: curPage > 0 ? '#856447' : '#5c3a21',
      text: '◀ 上一页',
      font: '11.5px ' + FONT_CHRONICLE,
      textColor: curPage > 0 ? '#fef08a' : '#5c4a3e',
      priority: 100,
      onClick: () => {
        if (curPage > 0) {
          state.codexPage = curPage - 1;
          playSoundEffect('click');
          requestRender();
        }
      }
    });

    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = 'bold 12px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#a89988';
    ctx.fillText(`第 ${curPage + 1} / ${totalPages} 页`, screenWidth / 2, pagerY + pageBtnH / 2);

    drawTactileButton(ctx, {
      id: 'codex_next_page_btn',
      x: cardX + cardW - pageBtnW - 20,
      y: pagerY,
      w: pageBtnW,
      h: pageBtnH,
      radius: 4,
      bg: curPage < totalPages - 1 ? '#38241b' : 'rgba(31, 22, 24, 0.4)',
      border: curPage < totalPages - 1 ? '#856447' : '#5c3a21',
      text: '下一页 ▶',
      font: '11.5px ' + FONT_CHRONICLE,
      textColor: curPage < totalPages - 1 ? '#fef08a' : '#5c4a3e',
      priority: 100,
      onClick: () => {
        if (curPage < totalPages - 1) {
          state.codexPage = curPage + 1;
          playSoundEffect('click');
          requestRender();
        }
      }
    });
  }

  // 底部关闭按钮
  const closeBtnW = cardW - 64;
  const closeBtnH = 32;
  const closeBtnX = cardX + 32;
  const closeBtnY = cardY + cardH - closeBtnH - 8;

  drawTactileButton(ctx, {
    id: 'close_endgame_codex_btn',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 4,
    bg: '#221714',
    border: '#6b4f3b',
    borderWidth: 1.2,
    text: "✕ 阖 上 卷 帙 · 返 回",
    font: 'bold 13.5px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      state.activeModal = state._previousModalBeforeCodex || null;
      state._previousModalBeforeCodex = null;
      playSoundEffect('paper');
      triggerHaptic('light');
      requestRender();
    }
  });

  ctx.restore();
}

