function executeParentFilialAction(actId, cost) {
  if (state.lastFilialActionYear === state.year) {
    showToast("今年已尽过一份孝心，细水长流，请来年再行反哺！", "info");
    playSoundEffect('alert');
    return;
  }
  if (actId === 'trip' && state.handledEvents && state.handledEvents['filial_trip_done']) {
    showToast("已陪二老圆梦天安门，这份珍贵记忆已永载家庭史册！", "info");
    playSoundEffect('alert');
    return;
  }
  if ((state.ap || 0) < 1) {
    showToast("今年精力已耗尽，请先迈入下一年！", "alert");
    playSoundEffect('alert');
    return;
  }
  if ((state.capital || 0) < cost) {
    showToast(`资费不足，需结余资金 ¥${cost.toLocaleString()} 元！`, 'alert');
    playSoundEffect('alert');
    return;
  }
  state.ap = Math.max(0, state.ap - 1);
  state.capital -= cost;
  state.lastFilialActionYear = state.year;
  if (true) {
    progressThreeYearPact(12, '慈乌反哺');
  }
  if (actId === 'nourish') {
    addStat("clean", 3, 95);
    addStat("health", 3, 95);
    playSoundEffect('tea');
    spawnInspirationSparks(screenWidth / 2, screenHeight / 2, 20);
    addChronicleItem(state.age, state.year, `【慈乌反哺】给家乡老父母寄去蜂王浆与麦乳精，二老气色红润喜笑颜开。百善孝为先，清廉操守+3！`, "父母高堂", "history");
    showToast("💊 置办营养品！二老康健，清廉+3，体魄+3！", "good");
  } else if (actId === 'house') {
    state.family.prestige = (state.family.prestige || 15) + 8;
    addStat("rep", 4, 10);
    playSoundEffect('fanfare');
    spawnInspirationSparks(screenWidth / 2, screenHeight / 2, 25);
    addChronicleItem(state.age, state.year, `【修缮祖屋】出资翻新老家旧宅门楼与青瓦红砖，乡亲邻里交口称赞！家族声望+8，社会声望+4！`, "光耀门楣", "promo");
    showToast("🏡 老宅修缮一新！家族声望+8，声望+4！", "gold");
  } else if (actId === 'trip') {
    state.handledEvents = state.handledEvents || {};
    state.handledEvents['filial_trip_done'] = true;
    addStat("rep", 6, 10);
    addStat("courage", 3, 45);
    playSoundEffect('fanfare');
    spawnInspirationSparks(screenWidth / 2, screenHeight / 2, 30);
    addChronicleItem(state.age, state.year, `【圆梦天安门】陪二老乘坐绿皮火车奔赴北京，站在天安门广场仰望五星红旗冉冉升起，父母热泪盈眶，完成了毕生夙愿！`, "高光圆满", "promo");
    showToast("🚩 圆梦天安门！父母热泪盈眶，声誉+6，魄力+3！", "gold");
  }
  requestRender();
}

