function drawCurioMarketModal() {
  const padX = 16;
  const cardW = screenWidth - padX * 2;
  const cardH = 380;
  const startX = padX;
  const startY = (screenHeight - cardH) / 2;

  ctx.save();
  ctx.fillStyle = '#171322';
  roundRect(ctx, startX, startY, cardW, cardH, 12, true, true, '#d97706', 2);
  drawCornerOrnaments(ctx, startX, startY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🏺 潘家园·信托古玩拍卖雅集", startX + cardW / 2, startY + 16);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#94a3b8';
  ctx.fillText(`结余现金: ¥${(state.capital || 0).toLocaleString()} 元 · 盛世藏古，抗跌硬通货`, startX + cardW / 2, startY + 40);

  // 3 件古玩藏品
  const itemH = 68;
  const itemStartY = startY + 62;

  state.ownedCurios = state.ownedCurios || [];

  CURIO_MARKET_DATABASE.forEach((ci, idx) => {
    const iy = itemStartY + idx * (itemH + 10);
    const isOwned = state.ownedCurios.includes(ci.id);

    ctx.fillStyle = isOwned ? '#231d34' : '#1a1628';
    roundRect(ctx, startX + 14, iy, cardW - 28, itemH, 6, true, true, isOwned ? '#f59e0b' : '#475569', 1);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = '22px sans-serif';
    ctx.fillText(ci.icon, startX + 22, iy + 14);

    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fef08a';
    ctx.fillText(ci.name, startX + 54, iy + 10);

    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = '#cbd5e1';
    ctx.fillText(fitText(ci.desc, cardW - 140, '13.5px ' + FONT_UI), startX + 54, iy + 28);

    ctx.font = 'bold 14px ' + FONT_MONO;
    ctx.fillStyle = '#34d399';
    ctx.fillText(`买入价: ¥${ci.cost.toLocaleString()} · 年化增益 +${Math.round(ci.baseAppreciation * 100)}%`, startX + 54, iy + 46);

    // 购买/已鉴藏按钮
    const btnW = 62;
    const btnH = 26;
    const btnX = startX + cardW - 28 - btnW - 10;
    const btnY = iy + 21;

    if (isOwned) {
      ctx.fillStyle = '#166534';
      roundRect(ctx, btnX, btnY, btnW, btnH, 4, true, true, '#22c55e', 1);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = 'bold 14px ' + FONT_UI;
      ctx.fillStyle = '#f8fafc';
      ctx.fillText("已鉴藏", btnX + btnW / 2, btnY + btnH / 2);
    } else {
      const canAfford = state.capital >= ci.cost;
      drawTactileButton(ctx, {
        id: 'buy_curio_' + ci.id,
        x: btnX,
        y: btnY,
        w: btnW,
        h: btnH,
        radius: 4,
        bg: canAfford ? '#78350f' : '#262626',
        border: '#f59e0b',
        borderWidth: 1,
        text: "淘入 ➔",
        font: 'bold 14px ' + FONT_UI,
        textColor: '#f8fafc',
        priority: 50,
        onClick: () => {
          if (state.capital >= ci.cost) {
            state.capital -= ci.cost;
            state.ownedCurios.push(ci.id);
            addStat("rep", 5, 10);
            playSoundEffect('coin');
            spawnInspirationSparks(screenWidth / 2, screenHeight / 2, 25);
            addChronicleItem(state.age, state.year, `【古玩雅集】在潘家园信托行慧眼识珠淘入【${ci.name}】，大局声望+5！`, "盛世典藏", "history");
            showToast(`淘得【${ci.name}】！声望+5，随时代推移持续增值！`, "gold");
          } else {
            showToast(`资本不足，需结余 ¥${ci.cost.toLocaleString()} 元！`, "alert");
          }
          requestRender();
        }
      });
    }
  });

  // 底部退出
  const closeBtnW = cardW - 40;
  const closeBtnH = 36;
  const closeBtnX = startX + 20;
  const closeBtnY = startY + cardH - closeBtnH - 14;

  drawTactileButton(ctx, {
    id: 'curio_market_close',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#221e33',
    border: '#475569',
    borderWidth: 1,
    text: "离开雅集 ➔",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

// 🌾 V25 二十四节气与四时物候系统 (Twenty-Four Solar Terms Engine)

function getSolarTermInfo(year, age) {
  const y = year || 1980;
  const a = age || 0;
  const idx = Math.abs((y * 2 + a) % 24);
  return SOLAR_TERMS[idx];
}

// ==========================================
// 🌿 V38 二十四节气顺时修身与天人合一调养系统 (Seasonal Wellness & Phenology Engine)
// ==========================================
function practiceSeasonalWellness() {
  const term = getSolarTermInfo(state.year, state.age);
  if (!term) return;

  if (state.seasonalWellnessYear === state.year) {
    showToast(`🎋 本岁时【${term.name}】已完成顺时修身，请待新岁节气再续！`, 'info');
    return;
  }
  if (state.ap < 1) {
    showToast('⚠️ 精力暂竭，稍事休整或品茗后再依循时令吐纳修身！', 'gold');
    return;
  }
  state.ap -= 1;
  state.seasonalWellnessYear = state.year;
  progressThreeYearPact(12, '节气顺时修身');

  let seasonMsg = '';
  if (term.season === '春') {
    state.sanbaoBonusQi = Math.min(25, (state.sanbaoBonusQi || 0) + 3);
    addStat("resilience", (3), 50);
    seasonMsg = `🌱【${term.name} · 春生木旺】吐故纳新，舒活筋骨！浩然之气+3，心性抗逆+3！`;
  } else if (term.season === '夏') {
    state.sanbaoBonusShen = Math.min(25, (state.sanbaoBonusShen || 0) + 3);
    addStat("courage", (3), 50);
    seasonMsg = `☀️【${term.name} · 夏长极阳】定心安神，消暑除烦！元神清明+3，胆识魄力+3！`;
  } else if (term.season === '秋') {
    state.sanbaoBonusJing = Math.min(25, (state.sanbaoBonusJing || 0) + 3);
    addStat("iq", (3), 50);
    seasonMsg = `🍁【${term.name} · 秋收金气】金水相涵，凝神静思！身体元精+3，智谋内省+3！`;
  } else {
    state.sanbaoBonusShen = Math.min(25, (state.sanbaoBonusShen || 0) + 2);
    addStat("health", (4), 80);
    seasonMsg = `❄️【${term.name} · 冬藏潜阳】闭门涵养，固本培元！健康体魄+4，元神笃定+2！`;
  }

  playSoundEffect('chime_stone_bianqing');
  triggerHaptic('medium');
  spawnFloatingRuneFX(`🎋 ${term.name}时宪 · 顺时修身`, screenWidth / 2, getDashboardY() + 30, '#10b981');
  showToast(seasonMsg, 'cyan');
  requestRender();
}

