function drawSolarTermModal() {
  const cardW = Math.min(screenWidth - 28, 350);
  const cardH = 470;
  const startX = (screenWidth - cardW) / 2;
  const startY = (screenHeight - cardH) / 2;

  ctx.save();
  // 卷轴外装裱
  drawSilkScrollFrame(ctx, startX, startY, cardW, cardH, '#dc2626', '#b91c1c');

  const term = getSolarTermInfo(state.year, state.age);

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';

  // 1. 顶部朱砂红大印章
  ctx.fillStyle = 'rgba(185, 28, 28, 0.4)';
  roundRect(ctx, startX + cardW / 2 - 55, startY + 16, 110, 32, 6, true, true, '#ef4444', 1.5);
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(term.icon + ' ' + term.name + ' · 时宪', startX + cardW / 2, startY + 23);

  // 2. 物候考究
  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#fca5a5';
  ctx.fillText('【七十二候物候】' + term.pheno, startX + cardW / 2, startY + 58);

  // 3. 古典诗赋
  const poetBoxY = startY + 82;
  const poetBoxH = 68;
  ctx.fillStyle = '#1c1917';
  roundRect(ctx, startX + 16, poetBoxY, cardW - 32, poetBoxH, 6, true, true, '#d97706', 0.8);
  ctx.font = 'italic 13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fde68a';
  ctx.fillText('“' + term.poet.slice(0, 20) + '”', startX + cardW / 2, poetBoxY + 16);
  if (term.poet.length > 20) {
    ctx.fillText('“' + term.poet.slice(20) + '”', startX + cardW / 2, poetBoxY + 38);
  }

  // 4. 农桑民生与当代履职指引
  const guideBoxY = poetBoxY + poetBoxH + 12;
  const guideBoxH = 100;
  ctx.fillStyle = 'rgba(26, 20, 24, 0.92)';
  roundRect(ctx, startX + 16, guideBoxY, cardW - 32, guideBoxH, 4, true, true, '#856447', 1);

  ctx.textAlign = 'left';
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText('🌾 当代民生与工农时宪：', startX + 26, guideBoxY + 14);

  ctx.font = '13px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#c8bbae';
  drawWrappedText(ctx, term.advice, startX + 26, guideBoxY + 36, cardW - 52, 16);

  // 5. 顺天应时心法共振
  const synergyY = guideBoxY + guideBoxH + 12;
  const synergyH = 64;
  ctx.fillStyle = 'rgba(38, 28, 22, 0.95)';
  roundRect(ctx, startX + 16, synergyY, cardW - 32, synergyH, 4, true, true, '#d97706', 1);

  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText('🎋 顺天应时 · 四时调养之益：', startX + 26, synergyY + 14);
  ctx.font = '13px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fde68a';
  drawWrappedText(ctx, '当前节气为【' + term.name + '】，顺时修身可滋养【' + term.season + '季元气】，三宝元气与心性抗逆稳步提升 (+3)！', startX + 26, synergyY + 34, cardW - 52, 14);

  // 6. 底部双按钮：顺时修身 ＆ 明悟退出
  const btnGap = 10;
  const btnW = (cardW - 40 - btnGap) / 2;
  const btnH = 34;
  const btnY = startY + cardH - btnH - 14;
  const btn1X = startX + 20;
  const btn2X = btn1X + btnW + btnGap;

  // 按钮1: 顺时修身
  drawTactileButton(ctx, {
    id: 'btn_practice_wellness',
    x: btn1X,
    y: btnY,
    w: btnW,
    h: btnH,
    radius: 3,
    bg: '#78350f',
    border: '#d97706',
    borderWidth: 1,
    text: '顺时修身 · 补三宝 ➔',
    font: 'bold 13px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 60,
    onClick: () => {
      practiceSeasonalWellness();
    }
  });

  // 按钮2: 明悟时宪
  drawTactileButton(ctx, {
    id: 'close_solar_term',
    x: btn2X,
    y: btnY,
    w: btnW,
    h: btnH,
    radius: 3,
    bg: '#7f1d1d',
    border: '#ef4444',
    borderWidth: 1,
    text: '明悟时宪 · 顺天应时 ➔',
    font: 'bold 13px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 60,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

