function openMonumentGalleryModal() {
  state.activeModal = 'monument_gallery';
  playSoundEffect('gong_deep_reverence');
  triggerHaptic('medium');
  requestRender();
}

function inscribeMonument(monumentId) {
  state.inscribedMonuments = state.inscribedMonuments || {};
  if (state.inscribedMonuments[monumentId]) {
    showToast('🏛️ 该座大国丰碑已铭刻您的专属丹朱金石印章！', 'info');
    return;
  }
  const mon = MONUMENT_CATALOG_DATABASE.find(m => m.id === monumentId);
  if (mon && state.age < (mon.reqAge || 35)) {
    showToast(`⚠️ 须年满 ${mon.reqAge || 35} 岁且主持过重大工程后，方可在国之重器基座铭刻工匠私印！`, 'gold');
    return;
  }
  if (state.ap < 1) {
    showToast('⚠️ 精力暂竭，稍作调养后再郑重在国之重器上铭刻铭文！', 'gold');
    return;
  }
  state.ap -= 1;
  state.inscribedMonuments[monumentId] = true;
  progressThreeYearPact(15, `铭刻丰碑·${mon ? mon.name : '大国重器'}`);

  addStat("rep", (5), 50);
  if (state.masterStudio) {
    state.masterStudio.legacyScore = (state.masterStudio.legacyScore || 60) + 35;
  }

  playSoundEffect('war_drum_resonance');
  triggerHaptic('heavy');
  spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 75, 'rgba(217, 119, 6, 0.45)');
  spawnFloatingRuneFX('🏛️ 铭刻永驻 · 传承+35', screenWidth / 2, screenHeight / 2 - 30, '#f59e0b');
  showToast('🏛️【国之重器】已在重器基座加盖专属丹朱金石印章与匠心铭文！浩气长存！', 'gold');
  requestRender();
}

function drawMonumentGalleryModal() {
  const cardW = Math.min(screenWidth - 24, 356);
  const cardH = 490;
  const startX = (screenWidth - cardW) / 2;
  const startY = (screenHeight - cardH) / 2;

  ctx.save();
  drawSilkScrollFrame(ctx, startX, startY, cardW, cardH, '#b45309', '#d97706');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';

  // 1. 标题栏
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText('🏛️ 神州丰碑 · 毕生传世图录殿堂', startX + cardW / 2, startY + 16);

  const inscribedCount = Object.keys(state.inscribedMonuments || {}).length;
  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#fed7aa';
  ctx.fillText(fitText(`大国工匠 · 经手铸就功勋重器（已铭刻 ${inscribedCount}/${MONUMENT_CATALOG_DATABASE.length} 项）`, cardW - 24, '13.5px ' + FONT_UI), startX + cardW / 2, startY + 36);

  // 2. 展陈卡片列表 (展示前 3 项当期最具代表性重器)
  const listY = startY + 56;
  const itmH = 100;
  const monCount = Math.min(3, MONUMENT_CATALOG_DATABASE.length);

  for (let idx = 0; idx < monCount; idx++) {
    const mon = MONUMENT_CATALOG_DATABASE[idx];
    const iy = listY + idx * (itmH + 8);
    const isInscribed = !!(state.inscribedMonuments && state.inscribedMonuments[mon.id]);

    ctx.fillStyle = isInscribed ? 'rgba(38, 28, 22, 0.95)' : 'rgba(26, 20, 24, 0.92)';
    roundRect(ctx, startX + 14, iy, cardW - 28, itmH, 4, true, true, isInscribed ? '#d97706' : '#856447', 1);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fef08a';
    ctx.fillText(fitText(`${mon.icon} ${mon.name}`, cardW - 135, 'bold 14px ' + FONT_CHRONICLE), startX + 22, iy + 8);

    ctx.textAlign = 'right';
    ctx.font = 'bold 13px ' + FONT_MONO;
    ctx.fillStyle = '#d97706';
    ctx.fillText('自主率: ' + mon.localization, startX + cardW - 22, iy + 9);

    ctx.textAlign = 'left';
    ctx.font = '12px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#8c7662';
    ctx.fillText(fitText(`${mon.category} ✦ ${mon.specs}`, cardW - 44, '12px ' + FONT_CHRONICLE), startX + 22, iy + 26);

    ctx.font = '12.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#c8bbae';
    drawWrappedText(ctx, mon.desc, startX + 22, iy + 42, cardW - 44, 13);

    // 铭刻按钮 / 已铭刻印章
    const bW = 104;
    const bH = 22;
    const bx = startX + cardW - bW - 20;
    const by = iy + itmH - bH - 6;

    if (isInscribed) {
      ctx.fillStyle = '#221510';
      roundRect(ctx, bx, by, bW, bH, 3, true, true, '#d97706', 1);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = 'bold 12.5px ' + FONT_CHRONICLE;
      ctx.fillStyle = '#fde68a';
      ctx.fillText('✓ 已铭刻工匠私印', bx + bW / 2, by + bH / 2);
    } else {
      drawTactileButton(ctx, {
        id: 'inscribe_mon_' + mon.id,
        x: bx,
        y: by,
        w: bW,
        h: bH,
        radius: 3,
        bg: '#7f1d1d',
        border: '#ef4444',
        borderWidth: 1,
        font: 'bold 12.5px ' + FONT_CHRONICLE,
        textColor: '#fef08a',
        text: '铭刻铭文 (-1⚡) ➔',
        onClick: () => {
          inscribeMonument(mon.id);
        },
        priority: 45
      });
    }
  }

  // 3. 底部关闭按钮
  const closeBtnW = cardW - 40;
  const closeBtnH = 34;
  const closeBtnX = startX + 20;
  const closeBtnY = startY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'close_monument_gallery',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 3,
    bg: '#78350f',
    border: '#d97706',
    borderWidth: 1,
    font: 'bold 13.5px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    text: '瞻仰大国重器 · 薪火代代相传 ➔',
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    },
    priority: 60
  });

  ctx.restore();
}

