// 统一金石文脉粒子对象池
const HERITAGE_FX_PARTICLE_POOL = [];
function obtainHeritageParticle(initFn) {
  let p = HERITAGE_FX_PARTICLE_POOL.pop();
  if (!p) p = {};
  initFn(p);
  return p;
}
function releaseHeritageParticle(p) {
  if (HERITAGE_FX_PARTICLE_POOL.length < 50) HERITAGE_FX_PARTICLE_POOL.push(p);
}
function spawnHeritageFX(cx, cy, color, count = 24) {
  if (typeof goldConfettiList === 'undefined' || !Array.isArray(goldConfettiList)) return;
  for (let i = 0; i < count; i++) {
    const angle = Math.random() * Math.PI * 2;
    const spd = 1.0 + Math.random() * 3.5;
    goldConfettiList.push(obtainHeritageParticle(p => {
      p.x = cx; p.y = cy;
      p.vx = Math.cos(angle) * spd; p.vy = Math.sin(angle) * spd;
      p.life = 0; p.maxLife = 28 + Math.floor(Math.random() * 22);
      p.color = color || '#fbbf24'; p.size = 2 + Math.random() * 2.5;
      p.shape = 'spark';
    }));
  }
}

// 兼容各版本粒子派生调用
function spawnHeritageFiligreeFX(cx, cy, count) { spawnHeritageFX(cx, cy, '#a855f7', count); }
function spawnCinnabarRubbingFX(cx, cy, count) { spawnHeritageFX(cx, cy, '#eab308', count); }
function spawnCeladonGlazeFX(cx, cy, count) { spawnHeritageFX(cx, cy, '#14b8a6', count); }
function spawnTeaAromaMistFX(cx, cy, count) { spawnHeritageFX(cx, cy, '#22c55e', count); }
function spawnBrocadeSilkFX(cx, cy, count) { spawnHeritageFX(cx, cy, '#f472b6', count); }
function spawnGuqinSoundwaveFX(cx, cy, count) { spawnHeritageFX(cx, cy, '#818cf8', count); }
function spawnInkstoneAuraFX(cx, cy, count) { spawnHeritageFX(cx, cy, '#a78bfa', count); }

