// 统一文化品鉴与技能研习执行器
function appreciateHeritageItem(catKey, itemId) {
  const cat = HERITAGE_CATEGORIES[catKey];
  if (!cat || !cat.database) return;
  const item = cat.database.find(i => i.id === itemId);
  if (!item) return;

  state[cat.stateKey] = state[cat.stateKey] || { totalCount: 0 };
  const store = state[cat.stateKey];
  const mapKey = cat.studiedField;
  store[mapKey] = store[mapKey] || {};

  if (store[mapKey][itemId]) {
    showToast('✨ 已研习【' + item.name + '】，心法早已融会贯通！', 'info');
    return;
  }
  if (state.ap < (item.costAp || 1)) {
    showToast('⚠️ 精力暂竭，稍作调养再潜心研习！', 'gold');
    return;
  }
  if ((state.capital || 0) < (item.costMoney || 0)) {
    showToast('⚠️ 研习该项文化雅集所需资费不足！', 'gold');
    return;
  }

  // 扣除消耗
  state.ap -= (item.costAp || 1);
  state.capital = Math.max(0, (state.capital || 0) - (item.costMoney || 0));
  if (true) {
    progressThreeYearPact(12, '文脉研习·' + item.name);
  }

  // 记录
  store[mapKey][itemId] = 1;
  store.totalCount = (store.totalCount || 0) + 1;

  // 生效收益
  const eff = item.effects || {};
  if (eff.resilience) addStat('resilience', eff.resilience, 50);
  if (eff.courage) addStat('courage', eff.courage, 50);
  if (eff.rep) addStat('rep', eff.rep, 50);
  if (eff.iq) addStat('iq', eff.iq, 50);
  if (eff.eq) addStat('eq', eff.eq, 50);
  if (eff.san) state.san = Math.min(100, (state.san || 80) + eff.san);
  if (eff.sanbaoShen) state.sanbaoBonusShen = Math.min(25, (state.sanbaoBonusShen || 0) + eff.sanbaoShen);
  if (eff.sanbaoJing) state.sanbaoBonusJing = Math.min(25, (state.sanbaoBonusJing || 0) + eff.sanbaoJing);
  if (eff.apMaxBonus) {
    state.bonusMaxAp = Math.min(1, (state.bonusMaxAp || 0) + 1);
    state.maxAp = ((true && hasTalent('decisive') && state.age % 2 === 0) ? 4 : 3) + state.bonusMaxAp;
  }
  if (eff.legacyScore && state.masterStudio) {
    state.masterStudio.legacyScore = (state.masterStudio.legacyScore || 60) + eff.legacyScore;
  }
  if (eff.clanCulture) {
    state.clanCultureScore = (state.clanCultureScore || 0) + eff.clanCulture;
  }
  if (eff.clanBizBonus) {
    state.clanBizBonus = (state.clanBizBonus || 0) + eff.clanBizBonus;
  }

  playSoundEffect(cat.actionSound || 'click');
  triggerHaptic('medium');
  spawnHeritageFX(screenWidth / 2, screenHeight / 2, cat.fxColor, 28);
  if (typeof spawnEraPulseWaveFX === 'function') spawnEraPulseWaveFX(screenWidth / 2, screenHeight / 2, cat.themeBorder);
  if (typeof spawnFloatingRuneFX === 'function') spawnFloatingRuneFX('✨ ' + item.name + ' · 文脉通达', screenWidth / 2, screenHeight / 2 - 35, '#fef08a');
  showToast('✨【' + item.name + '】精研入化！' + (item.motto || ''), 'purple');
  requestRender();
}

// 统一文化雅鉴弹窗绘制引擎
function drawGenericHeritageModal(catKey) {
  const cat = HERITAGE_CATEGORIES[catKey];
  if (!cat || !cat.database) return;

  const cardW = Math.min(screenWidth - 24, 460);
  const cardH = Math.min(screenHeight - 120, 580);
  const startX = Math.round((screenWidth - cardW) / 2);
  const startY = Math.max(30, Math.round((screenHeight - cardH) / 2));

  ctx.save();
  ctx.fillStyle = 'rgba(0, 0, 0, 0.75)';
  ctx.fillRect(0, 0, screenWidth, screenHeight);

  // 1. 卡片底板
  ctx.fillStyle = cat.themeBg;
  roundRect(ctx, startX, startY, cardW, cardH, 4, true, true, cat.themeBorder || '#856447', 1.5);
  drawCornerOrnaments(ctx, startX, startY, cardW, cardH, 8, cat.themeBorder || '#d97706');

  // 2. 标题区
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 15.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  drawTraditionalSealBadge(ctx, 'scroll', startX + cardW / 2 - 128, startY + 23, 9, '#fef08a');
  ctx.fillText(cat.title, startX + cardW / 2, startY + 14);
  drawTraditionalSealBadge(ctx, 'scroll', startX + cardW / 2 + 128, startY + 23, 9, '#fef08a');

  const store = state[cat.stateKey] || {};
  const map = store[cat.studiedField] || {};
  const currentCount = store.totalCount || 0;

  ctx.font = '12px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#d4c7b8';
  ctx.fillText('已承袭藏品: ' + currentCount + ' / ' + cat.database.length + ' ✦ 宗族文脉流芳', startX + cardW / 2, startY + 36);

  // 3. 藏品项目列表
  const itemH = 82;
  const listStartY = startY + 58;
  const displayItems = cat.database.slice(0, 5);

  displayItems.forEach((item, idx) => {
    const itemY = listStartY + idx * (itemH + 8);
    if (itemY + itemH > startY + cardH - 50) return;

    const isOwned = !!map[item.id];
    ctx.fillStyle = isOwned ? 'rgba(38, 28, 22, 0.95)' : 'rgba(26, 20, 24, 0.92)';
    roundRect(ctx, startX + 12, itemY, cardW - 24, itemH, 4, true, true, isOwned ? (cat.themeBorder || '#d97706') : '#5c3a21', 1);

    // 图标与名称
    ctx.textAlign = 'left';
    ctx.font = 'bold 13.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = isOwned ? '#fef08a' : '#f1f5f9';
    ctx.fillText((item.icon || '🏺') + ' ' + item.name, startX + 22, itemY + 8);

    // 规格与箴言
    ctx.font = '11.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#8c7662';
    ctx.fillText(fitText(item.spec || item.motto || '', cardW - 120, '11.5px ' + FONT_CHRONICLE), startX + 22, itemY + 28);

    // 研习成本或状态
    ctx.font = '11.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = isOwned ? '#6ee7b7' : '#f59e0b';
    ctx.fillText(isOwned ? '✦ 技艺大成 · 已铭刻' : ('耗精力:' + (item.costAp || 1) + '  资费:¥' + (item.costMoney || 0)), startX + 22, itemY + 48);

    // 按钮
    const btnW = 76;
    const btnH = 28;
    const btnX = startX + cardW - 20 - btnW;
    const btnY = itemY + 26;

    drawTactileButton(ctx, {
      id: 'btn_heritage_' + catKey + '_' + item.id,
      x: btnX,
      y: btnY,
      w: btnW,
      h: btnH,
      radius: 3,
      bg: isOwned ? '#221714' : (cat.themeBorder || '#78350f'),
      border: isOwned ? '#6b4f3b' : '#d97706',
      borderWidth: 1,
      font: 'bold 12px ' + FONT_CHRONICLE,
      textColor: isOwned ? '#8c7662' : '#fef08a',
      text: isOwned ? '已研习' : cat.actionVerb,
      onClick: () => {
        if (!isOwned) appreciateHeritageItem(catKey, item.id);
      },
      priority: 45
    });
  });

  // 4. 底部关闭按钮
  const closeBtnW = cardW - 32;
  const closeBtnH = 36;
  const closeBtnX = startX + 16;
  const closeBtnY = startY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'close_heritage_' + catKey,
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 4,
    bg: '#1c1519',
    border: cat.themeBorder || '#856447',
    borderWidth: 1.2,
    font: 'bold 13.5px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    text: cat.closeText,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    },
    priority: 60
  });

  ctx.restore();
}

