// 🏛️ V37-V38 国家大师技能创新工作室传承体系 (Master Studio System)
// ==========================================
function openMasterStudioModal() {
  if (state.age < 30 && (state.rep || 0) < 65) {
    showToast('🏛️ 国家大师创新工作室须年满30岁（或声誉≥65）具备深厚行业资历后挂牌成立！', 'info');
    return;
  }
  if (!state.masterStudio) {
    const trackName = state.track === 'industry' ? '技能' : (state.track === 'military' ? '军工科技' : (state.track === 'agri' ? '神农育种' : (state.track === 'biz' ? '实业创新' : '科技攻坚')));
    state.masterStudio = {
      name: `${state.name}国家${trackName}大师创新工作室`,
      level: (state.rep >= 85 ? '国家级特等示范' : '省部级重点创新'),
      apprentices: 4,
      legacyScore: 60,
      completedProjects: 1
    };
  }
  if (!state.masterStudio.disciples || state.masterStudio.disciples.length === 0) {
    state.masterStudio.disciples = [
      { name: '林承志', specialty: '高精五轴磨削', stage: 1, stageName: '业务骨干' },
      { name: '周立人', specialty: '航空特种合金', stage: 2, stageName: '独当一面总工' },
      { name: '苏清若', specialty: '数字孪生装配', stage: 1, stageName: '业务骨干' }
    ];
  }
  state.activeModal = 'master_studio';
  playSoundEffect('guzheng_cascade');
  triggerHaptic('medium');
  requestRender();
}

function commendDisciple(idx) {
  if (!state.masterStudio) return;
  const list = state.masterStudio.disciples;
  if (!list || !list[idx]) return;

  const d = list[idx];
  if ((d.stage || 1) >= 3) {
    showToast(`🏆 门生【${d.name}】已荣登【领衔大国英才】，独当一面！`, 'info');
    return;
  }
  if (state.lastStudioDiscipleYear === state.year) {
    showToast('🏛️ 本年度已点拨提携过门生，传道授业贵在循序渐进！', 'info');
    return;
  }
  if (state.ap < 1) {
    showToast('⚠️ 精力暂竭，稍作调养后再倾心点拨提携门生！', 'gold');
    return;
  }
  state.ap -= 1;
  state.lastStudioDiscipleYear = state.year;
  progressThreeYearPact(15, `点拨提携·${d.name}`);
  d.stage = (d.stage || 1) + 1;
  if (d.stage === 2) {
    d.stageName = '独当一面总工';
    state.masterStudio.legacyScore = (state.masterStudio.legacyScore || 60) + 20;
    addStat("rep", (3), 50);
    playSoundEffect('guzheng_cascade');
    triggerHaptic('medium');
    spawnFloatingRuneFX(`💡 提携晋升 · ${d.name}出徒`, screenWidth / 2, screenHeight / 2 - 30, '#38bdf8');
    showToast(`💡【点拨提携】门生【${d.name}】突破关键技术瓶颈，荣升【独当一面总工】！传承积分+20！`, 'cyan');
  } else {
    d.stage = 3;
    d.stageName = '领衔大国英才';
    state.masterStudio.legacyScore = (state.masterStudio.legacyScore || 60) + 30;
    addStat("rep", (5), 50);
    playSoundEffect('war_drum_resonance');
    triggerHaptic('heavy');
    spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 70, 'rgba(217, 119, 6, 0.45)');
    spawnFloatingRuneFX(`🏆 栋梁大成 · ${d.name}国家英才`, screenWidth / 2, screenHeight / 2 - 30, '#f59e0b');
    showToast(`🏆【薪火相传】门生【${d.name}】荣获国家青年科技英才称号！声誉+5，传承积分+30！`, 'gold');
  }
  requestRender();
}

function executeStudioDirective(actionKey) {
  if (!state.masterStudio) return;
  if (state.lastStudioDirectiveYear === state.year) {
    showToast('🏛️ 本年度工作室重点攻关或传习任务已圆满推进，请静待来年新课题！', 'info');
    return;
  }
  if (state.ap < 1) {
    showToast('⚠️ 精力已竭，稍作调养或品茗后再指导工作室工作！', 'gold');
    return;
  }
  state.ap -= 1;
  state.lastStudioDirectiveYear = state.year;
  progressThreeYearPact(15, '大师工作室课题传习');
  if (actionKey === 'apprentice') {
    state.masterStudio.apprentices = (state.masterStudio.apprentices || 4) + 1;
    state.masterStudio.legacyScore = (state.masterStudio.legacyScore || 60) + 15;
    addStat("resilience", (3), 50);
    playSoundEffect('guzheng_cascade');
    triggerHaptic('medium');
    spawnFloatingRuneFX('💡 传艺+1 · 传承+15', screenWidth / 2, screenHeight / 2 - 40, '#fde68a');
    showToast('💡【带徒传习】倾囊相授独门绝学，新入选骨干学徒顺利出徒！传承积分+15！', 'gold');
  } else if (actionKey === 'topic') {
    state.masterStudio.completedProjects = (state.masterStudio.completedProjects || 1) + 1;
    state.masterStudio.legacyScore = (state.masterStudio.legacyScore || 60) + 20;
    addStat("rep", (4), 50);
    state.capital = (state.capital || 0) + 8000;
    playSoundEffect('pipa_tremolo');
    triggerHaptic('heavy');
    spawnFloatingRuneFX('🔬 课题结题 · 津贴+8千', screenWidth / 2, screenHeight / 2 - 40, '#38bdf8');
    showToast('🔬【课题攻坚】工作室挂牌攻关课题通过专家组阶段验收！声誉+4，津贴+¥8,000！', 'cyan');
  } else if (actionKey === 'codify') {
    state.masterStudio.legacyScore = (state.masterStudio.legacyScore || 60) + 25;
    addStat("iq", (4), 50);
    state.sanbaoBonusShen = Math.min(25, (state.sanbaoBonusShen || 0) + 3);
    playSoundEffect('seal_stamp_heavy');
    triggerHaptic('heavy');
    spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 60, 'rgba(220, 38, 38, 0.45)');
    spawnFloatingRuneFX('📜 工法立言 · 传承+25', screenWidth / 2, screenHeight / 2 - 40, '#ef4444');
    showToast('📜【工法编纂】国家级实训教材与核心专利指南付梓发行！薪火相传，垂范后世！', 'gold');
  }
  requestRender();
}

