const DEFAULT_STUDIO_DISCIPLES = [
  { name: '林承志', specialty: '高精五轴磨削', stage: 1, stageName: '业务骨干' },
  { name: '周立人', specialty: '航空特种合金', stage: 2, stageName: '独当一面总工' },
  { name: '苏清若', specialty: '数字孪生装配', stage: 1, stageName: '业务骨干' }
];

function drawMasterStudioModal() {
  const cardW = Math.min(screenWidth - 24, 356);
  const cardH = 490;
  const startX = (screenWidth - cardW) / 2;
  const startY = (screenHeight - cardH) / 2;

  ctx.save();
  drawSilkScrollFrame(ctx, startX, startY, cardW, cardH, '#d97706', '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';

  // 1. 标题栏
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText('🏛️ 国家大师技能创新工作室 · 薪火相传', startX + cardW / 2, startY + 16);

  const studio = state.masterStudio || {
    name: `${state.name}大师技能创新工作室`,
    level: '国家级特等示范',
    apprentices: 5,
    legacyScore: 80,
    completedProjects: 2
  };

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#fed7aa';
  ctx.fillText(`【${studio.name}】 · ${studio.level}`, startX + cardW / 2, startY + 36);

  // 2. 状态徽章条
  const badgeH = 24;
  ctx.fillStyle = '#1e1b2e';
  roundRect(ctx, startX + 16, startY + 52, cardW - 32, badgeH, 4, true, true, '#f59e0b', 0.8);
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = 'bold 14px ' + FONT_UI;
  ctx.fillStyle = '#fde68a';
  ctx.fillText(`传承英才: ${studio.apprentices}位 ✦ 攻坚结题: ${studio.completedProjects || 1}项 ✦ 传承功勋: ${studio.legacyScore}分`, startX + cardW / 2, startY + 52 + badgeH / 2);

  // 3. 三大导师工作职责卡
  const cardListY = startY + 82;
  const itmH = 68;
  for (let idx = 0; idx < MASTER_STUDIO_DIRECTIVES.length; idx++) {
    const d = MASTER_STUDIO_DIRECTIVES[idx];
    const iy = cardListY + idx * (itmH + 8);
    ctx.fillStyle = 'rgba(26, 20, 24, 0.92)';
    roundRect(ctx, startX + 14, iy, cardW - 28, itmH, 4, true, true, '#856447', 1);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fef08a';
    ctx.fillText(d.icon + ' ' + d.title, startX + 22, iy + 7);

    ctx.textAlign = 'right';
    ctx.font = 'bold 13px ' + FONT_MONO;
    ctx.fillStyle = (state.ap >= 1) ? '#d97706' : '#ef4444';
    ctx.fillText(d.cost, startX + cardW - 22, iy + 8);

    ctx.textAlign = 'left';
    ctx.font = '12.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#c8bbae';
    drawWrappedText(ctx, d.desc, startX + 22, iy + 24, cardW - 44, 13);

    // 交互按钮
    const btnW = 84;
    const btnH = 20;
    const btnX = startX + cardW - btnW - 18;
    const btnY = iy + itmH - btnH - 6;

    drawTactileButton(ctx, {
      id: 'studio_action_' + d.key,
      x: btnX,
      y: btnY,
      w: btnW,
      h: btnH,
      radius: 3,
      bg: '#78350f',
      border: '#d97706',
      borderWidth: 1,
      font: 'bold 12px ' + FONT_CHRONICLE,
      textColor: '#fef08a',
      text: '指导研习 ➔',
      onClick: () => {
        executeStudioDirective(d.key);
      },
      priority: 40
    });
  }

  // 4. 入室门生薪火谱台 (Disciple Pedigree Lineage)
  const discListY = startY + 316;
  const discBoxH = 86;
  ctx.fillStyle = 'rgba(34, 25, 29, 0.95)';
  roundRect(ctx, startX + 14, discListY, cardW - 28, discBoxH, 4, true, true, '#856447', 1);

  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText('👥 入室门生传承谱系（亲炙点拨出徒）：', startX + 22, discListY + 7);

  const disciples = (studio.disciples && studio.disciples.length > 0) ? studio.disciples : DEFAULT_STUDIO_DISCIPLES;

  const colW = (cardW - 44) / 3;
  for (let dIdx = 0; dIdx < disciples.length; dIdx++) {
    const dc = disciples[dIdx];
    const dx = startX + 20 + dIdx * (colW + 2);
    const dy = discListY + 24;
    const dh = discBoxH - 30;

    ctx.fillStyle = 'rgba(26, 20, 24, 0.92)';
    roundRect(ctx, dx, dy, colW - 4, dh, 3, true, true, dc.stage >= 2 ? '#d97706' : '#5c4538', 1);

    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 13px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fde68a';
    ctx.fillText(dc.name, dx + (colW - 4) / 2, dy + 4);

    ctx.font = '12px ' + FONT_CHRONICLE;
    ctx.fillStyle = dc.stage >= 3 ? '#d97706' : (dc.stage === 2 ? '#f59e0b' : '#8c7662');
    ctx.fillText(dc.stageName, dx + (colW - 4) / 2, dy + 18);

    // 点拨按钮
    const cbW = colW - 12;
    const cbH = 16;
    const cbX = dx + 4;
    const cbY = dy + dh - cbH - 4;

    if (dc.stage >= 3) {
      ctx.fillStyle = '#221510';
      roundRect(ctx, cbX, cbY, cbW, cbH, 3, true, true, '#d97706', 1);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = 'bold 11px ' + FONT_CHRONICLE;
      ctx.fillStyle = '#fde68a';
      ctx.fillText('已成大器', cbX + cbW / 2, cbY + cbH / 2);
    } else {
      drawTactileButton(ctx, {
        id: 'commend_disciple_' + dIdx,
        x: cbX,
        y: cbY,
        w: cbW,
        h: cbH,
        radius: 3,
        bg: '#78350f',
        border: '#d97706',
        borderWidth: 1,
        font: 'bold 11px ' + FONT_CHRONICLE,
        textColor: '#fef08a',
        text: dc.stage === 2 ? '提携+30' : '提携+20',
        onClick: () => {
          commendDisciple(dIdx);
        },
        priority: 45
      });
    }
  }

  // 5. 底部关闭按钮
  const closeBtnW = cardW - 40;
  const closeBtnH = 34;
  const closeBtnX = startX + 20;
  const closeBtnY = startY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'close_master_studio_modal',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 3,
    bg: '#78350f',
    border: '#d97706',
    borderWidth: 1,
    font: 'bold 13.5px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    text: '领略大师风范 · 传薪火于后人 ➔',
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    },
    priority: 60
  });

  ctx.restore();
}

