function interactSeal() {
  state.deskItemUsedYear = state.deskItemUsedYear || {};
  if (state.deskItemUsedYear.seal === state.year) {
    showToast('🔴 今年已郑重落款钤印过案头要务，印信千钧，请明年再用！', 'info');
    return;
  }
  if (state.ap < 1) {
    showToast('⚠️ 精力暂竭，稍事歇息或品茗后再郑重落款钤印！', 'gold');
    return;
  }
  state.ap -= 1;
  state.deskItemUsedYear.seal = state.year;
  if (true) {
    progressThreeYearPact(15, '钤印立信');
  }
  addStat("rep", (3), 50);
  state.sanbaoBonusQi = Math.min(25, (state.sanbaoBonusQi || 0) + 2);
  playSoundEffect('seal_stamp_heavy');
  triggerHaptic('heavy');
  spawnInkWashBloom(screenWidth / 2, getDashboardY() + 40, 50, 'rgba(220, 38, 38, 0.45)');
  spawnFloatingRuneFX('🔴 +3 威望赫然 · 丹朱定音', screenWidth / 2, getDashboardY() + 20, '#ef4444');
  showToast('🔴【丹朱钤印】郑重加盖个人专属印信！字斟句酌，一诺千金。声誉威望+3！', 'gold');
  requestRender();
}

function drawInteractiveScholarDesk(curY) {
  const padX = 12;
  const w = screenWidth - padX * 2;
  const deskH = 104;

  const vTop = getContentTop() - 60;
  const vBottom = getContentTop() + getContentH() + 60;
  if (curY + deskH < vTop || curY > vBottom) {
    return curY + deskH + 8;
  }

  ctx.save();
  ctx.fillStyle = '#111827';
  roundRect(ctx, padX, curY, w, deskH, 6, true, true, '#d97706', 1.2);
  drawCornerOrnaments(ctx, padX, curY, w, deskH, 4, '#fbbf24');

  // 顶部细文字
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fde68a';
  ctx.fillText('🖌️ 案头文房雅物与舆图卷宗：', padX + 10, curY + 6);

  // 十枚交互雅趣微按钮 (文房器用与经纬实干，分两行排布)
  const row1 = [
    { icon: '🍵', title: '品茗', id: 'desk_teapot', action: () => interactTeapot(), color: '#34d399' },
    { icon: '📐', title: '算盘', id: 'desk_abacus', action: () => interactAbacus(), color: '#38bdf8' },
    { icon: '⏱️', title: '怀表', id: 'desk_chronometer', action: () => interactChronometer(), color: '#f59e0b' },
    { icon: '🖋️', title: '铅笔', id: 'desk_pencil', action: () => interactPencil(), color: '#f87171' },
    { icon: '🪔', title: '香炉', id: 'desk_incense', action: () => interactIncense(), color: '#fbbf24' }
  ];
  const row2 = [
    { icon: '🪨', title: '镇纸', id: 'desk_paperweight', action: () => interactPaperweight(), color: '#c084fc' },
    { icon: '🔴', title: '钤印', id: 'desk_seal', action: () => interactSeal(), color: '#ef4444' },
    { icon: '📜', title: '因果', id: 'desk_karma', action: () => openKarmaCompassModal(), color: '#e879f9' },
    { icon: '🗺️', title: '舆图', id: 'desk_carto', action: () => openNineProvincesCartographyModal(), color: '#38bdf8' },
    { icon: '🏛️', title: '重器', id: 'desk_blueprints', action: () => openBlueprintGalleryModal(), color: '#f59e0b' }
  ];

  const colW = (w - 16) / 5;
  [row1, row2].forEach((rowList, rIdx) => {
    const iy = curY + 22 + rIdx * 38;
    rowList.forEach((it, idx) => {
      const ix = padX + 8 + idx * colW;
      const btnW = colW - 4;
      const btnH = 34;

      drawTactileButton(ctx, {
        id: it.id,
        x: ix,
        y: iy,
        w: btnW,
        h: btnH,
        radius: 3,
        bg: '#221510',
        pressedBg: '#140e0b',
        border: '#856447',
        pressedBorder: '#d97706',
        borderWidth: 1,
        isScroll: true,
        priority: 30,
        onClick: it.action,
        renderContent: (c) => {
          c.textAlign = 'center';
          c.textBaseline = 'middle';
          c.font = '12px ' + FONT_UI;
          c.fillText(it.icon, ix + btnW / 2, iy + 10);
          c.font = 'bold 11px ' + FONT_CHRONICLE;
          c.fillStyle = '#fde68a';
          c.fillText(it.title, ix + btnW / 2, iy + 23);
        }
      });
    });
  });

  ctx.restore();
  return curY + deskH + 8;
}

