// 🌊 V26 大国脊梁 · 世纪答卷历史检验 (Century Benchmark Historical Test)
// ==========================================
function triggerCenturyBenchmarkEvent() {
  if (state.activeModal) return false;
  const age = state.age;
  if (age >= 69 && age <= 70 && (!state.handledEvents || !state.handledEvents['century_benchmark_done'])) {
    state.handledEvents = state.handledEvents || {};
    state.handledEvents['century_benchmark_done'] = true;
    state.activeModal = 'century_benchmark';

    playSoundEffect('bianzhong_sacred_hymn');
    triggerScreenShake(8, 400);
    spawnGoldSpiral(screenWidth / 2, screenHeight / 2, 40);
    requestRender();
    return true;
  }
  return false;
}

