function openStrategicMatrixModal() {
  state.activeModal = 'strategic_matrix';
  playSoundEffect('sheng_harmonious_reed');
  triggerHaptic('medium');
  requestRender();
}

function synergizeInitiative(item) {
  state.activatedSynergies = state.activatedSynergies || {};
  if (state.activatedSynergies[item.id]) {
    showToast('重器铸成！大国专项举国联合会战圆满功成！', 'gold');
    return;
  }
  state.unlockedMasteries = state.unlockedMasteries || {};
  if (item.requires && item.requires.some(reqId => !state.unlockedMasteries[reqId])) {
    showToast(`⚠️ 须先在【重器工法谱】攻克前置基石（${item.reqNames}）方可启动协同攻坚！`, 'gold');
    return;
  }
  if ((state.ap || 0) < 1) {
    showToast('⚠️ 精力不足(需1⚡)，请调养生息后再启动跨界协同攻关！', 'gold');
    return;
  }
  state.ap -= 1;
  state.activatedSynergies[item.id] = true;
  if (true) {
    progressThreeYearPact(18, '战略协同');
  }
  if (item.id === 'syn_green_watershed') {
    addStat("iq", 5, 50);
    addStat("rep", 6, 50);
  } else if (item.id === 'syn_polar_robot') {
    addStat("resilience", 6, 50);
    addStat("iq", 5, 50);
  } else {
    addStat("resilience", 6, 50);
    addStat("rep", 6, 50);
  }
  playSoundEffect('bianzhong_sacred_hymn');
  triggerHaptic('heavy');
  showToast('🌟【跨界协同】突破【' + item.title + '】！声望与抗逆稳步跃升！', 'gold');
  addChronicleItem(state.age, state.year, '【战略协同】跨领域联合攻克【' + item.title + '】，成果丰硕，立功当世！', '大国协同', 'promo');
  requestRender();
}

function drawStrategicMatrixModal() {
  const cardW = Math.min(screenWidth - 24, 356);
  const cardH = 470;
  const startX = (screenWidth - cardW) / 2;
  const startY = (screenHeight - cardH) / 2;

  ctx.save();
  drawSilkScrollFrame(ctx, startX, startY, cardW, cardH, '#7c3aed', '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';

  // 1. 标题
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText('⚡ 国家重大战略联合攻关专项', startX + cardW / 2, startY + 16);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#ddd6fe';
  ctx.fillText('跨赛道多维工法交织融合 · 打造具有复合竞争力的超级重器', startX + cardW / 2, startY + 36);

  // 2. 专项列表
  const listY = startY + 58;
  const itemH = 92;
  state.activatedSynergies = state.activatedSynergies || {};

  STRATEGIC_INITIATIVE_MATRIX.forEach((it, idx) => {
    const iy = listY + idx * (itemH + 10);
    const isDone = !!state.activatedSynergies[it.id];

    drawTactileButton(ctx, {
      id: 'synergy_item_' + it.id,
      x: startX + 14,
      y: iy,
      w: cardW - 28,
      h: itemH,
      radius: 3,
      bg: isDone ? '#2a1a14' : 'rgba(26, 20, 24, 0.92)',
      border: isDone ? '#d97706' : '#856447',
      borderWidth: 1,
      priority: 60,
      onClick: () => {
        synergizeInitiative(it);
      },
      renderContent: (c, isPressed) => {
        c.textAlign = 'left';
        c.font = 'bold 14px ' + FONT_CHRONICLE;
        c.fillStyle = isDone ? '#fde68a' : '#fef08a';
        c.fillText(fitText('🌟 【' + it.title + '】' + (isDone ? ' · ✦ 已联合攻克' : ''), cardW - 140, 'bold 14px ' + FONT_CHRONICLE), startX + 22, iy + 8);

        c.textAlign = 'right';
        c.font = 'bold 12.5px ' + FONT_CHRONICLE;
        c.fillStyle = isDone ? '#d97706' : '#f59e0b';
        c.fillText(isDone ? '✔ 协同大成' : '合力攻关 ➔', startX + cardW - 22, iy + 9);

        c.textAlign = 'left';
        c.font = '12px ' + FONT_CHRONICLE;
        c.fillStyle = '#d97706';
        c.fillText('攻坚基石：' + it.reqNames, startX + 22, iy + 26);

        c.font = '12.5px ' + FONT_CHRONICLE;
        c.fillStyle = '#c8bbae';
        drawWrappedText(c, it.desc, startX + 22, iy + 42, cardW - 44, 14);

        c.font = 'bold 12px ' + FONT_CHRONICLE;
        c.fillStyle = isDone ? '#fef08a' : '#fde047';
        c.fillText('成果：' + it.bonus, startX + 22, iy + 73);
      }
    });
  });

  // 3. 底部关闭按钮
  const closeBtnW = cardW - 40;
  const closeBtnH = 34;
  const closeBtnX = startX + 20;
  const closeBtnY = startY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'close_strategic_matrix',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 3,
    bg: '#78350f',
    border: '#d97706',
    borderWidth: 1,
    text: '聚智攻坚 · 协同致远 ➔',
    font: 'bold 13.5px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 60,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

