function triggerKarmaNexusStage() {
  if (state.activeModal) return false;
  const age = state.age;

  for (let k of DEEP_CAUSAL_KARMA_NEXUS) {
    // 阶段一：青年埋因
    if (age === k.stage1Age && (!state.handledEvents || !state.handledEvents['karma_st1_' + k.id])) {
      state.handledEvents = state.handledEvents || {};
      state.handledEvents['karma_st1_' + k.id] = true;
      state.activeKarmaEvent = { type: 'stage1', data: k };
      state.activeModal = 'karma_nexus';
      playSoundEffect('xun_ancient_clay');
      triggerHaptic('medium');
      requestRender();
      return true;
    }
    // 阶段二：中年回响
    if (age === k.stage2Age && (!state.handledEvents || !state.handledEvents['karma_st2_' + k.id])) {
      state.handledEvents = state.handledEvents || {};
      state.handledEvents['karma_st2_' + k.id] = true;
      state.activeKarmaEvent = { type: 'stage2', data: k };
      state.activeModal = 'karma_nexus';
      playSoundEffect('storm_wind_thunder');
      triggerHaptic('heavy');
      requestRender();
      return true;
    }
    // 阶段三：晚年大成
    if (age === k.stage3Age && (!state.handledEvents || !state.handledEvents['karma_st3_' + k.id])) {
      state.handledEvents = state.handledEvents || {};
      state.handledEvents['karma_st3_' + k.id] = true;
      state.activeKarmaEvent = { type: 'stage3', data: k };
      state.activeModal = 'karma_nexus';
      playSoundEffect('bianzhong_sacred_hymn');
      triggerHaptic('heavy');
      requestRender();
      return true;
    }
  }
  return false;
}

function drawKarmaNexusModal() {
  const cardW = Math.min(screenWidth - 24, 356);
  const cardH = 470;
  const startX = (screenWidth - cardW) / 2;
  const startY = (screenHeight - cardH) / 2;

  const ke = state.activeKarmaEvent;
  if (!ke) {
    state.activeModal = null;
    return;
  }

  ctx.save();
  drawSilkScrollFrame(ctx, startX, startY, cardW, cardH, '#c2410c', '#d97706');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';

  const kData = ke.data;

  // 1. 标题
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  const stageTitle = ke.type === 'stage1' ? '🌱 宿命结因 · ' + kData.title : (ke.type === 'stage2' ? '⚡ 因果显发 · 四十载风云激荡' : '👑 岁月定论 · 半世纪沧桑回响');
  ctx.fillText(stageTitle, startX + cardW / 2, startY + 16);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#fed7aa';
  ctx.fillText('“地势坤，君子以厚德载物” · 青年所植之因，历经岁月汇为沧海', startX + cardW / 2, startY + 36);

  // 2. 正文
  const textBoxY = startY + 58;
  const textBoxH = 180;
  ctx.fillStyle = '#1c1917';
  roundRect(ctx, startX + 16, textBoxY, cardW - 32, textBoxH, 6, true, true, '#ea580c', 0.8);

  ctx.textAlign = 'left';
  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fde68a';

  let bodyText = '';
  if (ke.type === 'stage1') {
    bodyText = kData.stage1Desc;
  } else if (ke.type === 'stage2') {
    const isStrict = state[kData.choiceA.flag];
    bodyText = isStrict ? kData.stage2EchoA : kData.stage2EchoB;
  } else {
    const isStrict = state[kData.choiceA.flag];
    bodyText = isStrict ? kData.stage3EchoA : kData.stage3EchoB;
  }

  drawWrappedText(ctx, bodyText, startX + 26, textBoxY + 16, cardW - 52, 18);

  // 3. 抉择或领悟按钮
  if (ke.type === 'stage1') {
    const btnW = cardW - 32;
    const btnH = 42;
    let curBtnY = textBoxY + textBoxH + 12;

    [kData.choiceA, kData.choiceB].forEach((ch, idx) => {
      drawTactileButton(ctx, {
        id: 'karma_choice_' + idx,
        x: startX + 16,
        y: curBtnY,
        w: btnW,
        h: btnH,
        radius: 6,
        bg: idx === 0 ? '#7c2d12' : '#1e1b4b',
        border: idx === 0 ? '#ea580c' : '#6366f1',
        priority: 60,
        onClick: () => {
          state[ch.flag] = true;
          addStat("resilience", 5, 50);
          playSoundEffect('bell_grand_chime');
          triggerHaptic('medium');
          showToast('🌱【宿命种因】' + ch.tag + '！此抉择将在此后数十年中产生深远回响！', 'gold');
          addChronicleItem(state.age, state.year, '【重大抉择】' + kData.title + '：' + ch.outcomeText, ch.tag, 'promo');
          state.activeModal = null;
          requestRender();
        },
        renderContent: (c, isPressed) => {
          c.textAlign = 'left';
          c.font = 'bold 14px ' + FONT_CHRONICLE;
          c.fillStyle = idx === 0 ? '#ffedd5' : '#c7d2fe';
          c.fillText('⚖️ ' + ch.text, startX + 24, curBtnY + 13);

          c.font = '13.5px ' + FONT_UI;
          c.fillStyle = '#cbd5e1';
          c.fillText('【' + ch.tag + '】一念抉择，决定数十年后时代命运轨迹', startX + 24, curBtnY + 28);
        }
      });

      curBtnY += btnH + 8;
    });
  } else {
    // 阶段二与阶段三的领悟按钮
    const closeBtnW = cardW - 40;
    const closeBtnH = 36;
    const closeBtnX = startX + 20;
    const closeBtnY = startY + cardH - closeBtnH - 14;

    drawTactileButton(ctx, {
      id: 'close_karma_echo',
      x: closeBtnX,
      y: closeBtnY,
      w: closeBtnW,
      h: closeBtnH,
      radius: 6,
      bg: '#9a3412',
      border: '#ea580c',
      borderWidth: 1.2,
      text: '感悟岁月因果 · 笃定工匠道心 ➔',
      font: 'bold 14px ' + FONT_UI,
      textColor: '#fef08a',
      priority: 65,
      onClick: () => {
        addStat("resilience", 6, 50);
        addChronicleItem(state.age, state.year, '【因果回响】' + bodyText.slice(0, 45) + '...', '岁月因果', 'promo');
        state.activeModal = null;
        playSoundEffect('bell_grand_chime');
        triggerHaptic('heavy');
        requestRender();
      }
    });
  }

  ctx.restore();
}

