function getAllClansForLeaderboard() {
  const activeSeason = (typeof syncRealSeason === 'function') ? syncRealSeason() : ((typeof resolveCurrentRealSeason === 'function') ? resolveCurrentRealSeason() : null);
  const targetRealSeasonId = activeSeason ? activeSeason.realSeasonId : 'RS_2026_Q4_HANWEI';
  let list = null;
  if (_clanCloudMod && typeof _clanCloudMod.fetchClanLeaderboard === 'function') {
    try {
      const res = _clanCloudMod.fetchClanLeaderboard({
        realSeasonId: targetRealSeasonId,
        myFamily: state.familyProfile
      });
      if (Array.isArray(res) && res.length > 0) {
        list = res;
      }
    } catch (_) {}
  }
  if (!list || !list.length) {
    const fallbackSeeds = (_clanCloudMod && _clanCloudMod.SEED_SAMPLE_CLANS) || SAMPLE_CLANS;
    list = [...fallbackSeeds];
    if (state.familyProfile) {
      const existingIdx = list.findIndex(c => c.familyId === state.familyProfile.familyId);
      if (existingIdx >= 0) {
        list[existingIdx] = state.familyProfile;
      } else {
        list.unshift(state.familyProfile);
      }
    }
  }
  return list;
}

function openClanEstablishmentModal() {
  if (state.isClanProfileLoadingFromCloud) {
    showToast('正在迎回云端世家档案，请稍候...', 'normal');
  }
  if (state.familyProfile && state.familyProfile.isImmutable) {
    showToast(`我族【${state.familyProfile.fullName}】已确立，不可更改！`, 'info');
    state.activeTab = 'family';
    requestRender();
    return;
  }
  state.clanForm = state.clanForm || {
    surnameIndex: 0,
    provinceIndex: 0,
    vocationId: 'study_scholar',
    hallIndex: 0
  };
  state.activeModal = 'clan_establishment';

  // 关键埋点：立族大典弹窗展示上报
  reportGameMilestone('clan_establishment_viewed', {
    hasFormDraft: Boolean(state.clanForm),
    vocationId: state.clanForm ? state.clanForm.vocationId : 'study_scholar'
  });

  playSoundEffect('bell');
  requestRender();
}

function openClanLeaderboardModal(subTab = 'surname', forceRefresh = false) {
  state.clanLeaderboardSubTab = subTab;
  state.activeModal = 'clan_leaderboard';
  state.clanLeaderboardLoading = true;
  state.clanLeaderboardError = null;
  playSoundEffect('click');
  requestRender();

  const activeSeason = (typeof syncRealSeason === 'function') ? syncRealSeason() : ((typeof resolveCurrentRealSeason === 'function') ? resolveCurrentRealSeason() : null);
  const targetRealSeasonId = activeSeason ? activeSeason.realSeasonId : 'RS_2026_Q4_HANWEI';

  if (_clanCloudMod && typeof _clanCloudMod.fetchClanLeaderboard === 'function') {
    _clanCloudMod.fetchClanLeaderboard({
      realSeasonId: targetRealSeasonId,
      myFamily: state.familyProfile,
      forceRefresh: forceRefresh
    }, (err, clans) => {
      state.clanLeaderboardLoading = false;
      if (err) {
        state.clanLeaderboardError = '网络波动，未能拉取云端实时榜单';
        state.clanLeaderboardData = clans || getAllClansForLeaderboard();
      } else {
        state.clanLeaderboardError = null;
        state.clanLeaderboardData = clans;
      }
      requestRender();
    });
  } else {
    state.clanLeaderboardLoading = false;
    state.clanLeaderboardData = getAllClansForLeaderboard();
    requestRender();
  }
}

function openMarriageInvitationModal() {
  state.activeModal = 'marriage_invitation';
  playSoundEffect('fanfare');
  requestRender();
}

function openFrontierWaitingModal() {
  state.activeModal = 'frontier_waiting';
  state._frontierInterceptCount = (state._frontierInterceptCount || 0) + 1;
  const fam = state.familyProfile;
  const curYear = (fam && fam.timeline) ? fam.timeline.currentYear : (state.year || 2026);
  const frontierYear = (state && state.currentFrontierYear) || (typeof WORLD_CHRONO_CONFIG !== 'undefined' ? WORLD_CHRONO_CONFIG.frontierYear : 2035);

  // 关键埋点：前沿线拦截上报（想看新内容的关键需求信号）
  const frontierPayload = {
    familyId: (fam && fam.familyId) || '',
    currentYear: curYear,
    frontierYear: frontierYear,
    interceptCount: state._frontierInterceptCount
  };
  reportGameMilestone('frontier_intercepted', frontierPayload);
  reportGameMilestone('frontier_blocked_intercepted', frontierPayload);

  playSoundEffect('bell');
  requestRender();
}

function drawClanEstablishmentModal() {
  const { x: cardX, y: cardY, w: cardW, h: cardH } = getModalSafeRect(355, 595);

  ctx.save();
  // 华贵汉魏朱漆金玉底板
  drawElevatedCard(ctx, cardX, cardY, cardW, cardH, {
    elevation: 4,
    radius: 8,
    fill: '#1a1017',
    borderColor: '#f59e0b',
    borderWidth: 2,
    hasCornerOrnaments: true,
    cornerLength: 10,
    cornerColor: '#fbbf24',
    headerBandColor: 'rgba(180, 83, 9, 0.45)',
    leftAccentColor: '#f59e0b'
  });

  // 金色飞尘粒子点缀
  if (_charVisualsMod && typeof _charVisualsMod.drawFloatingSparks === 'function') {
    _charVisualsMod.drawFloatingSparks(ctx, cardX + 10, cardY + 10, cardW - 20, cardH - 20, Date.now() / 1000);
  }

  // 1. 顶部威严标题
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🏛️ 华夏世家 · 立族大典 🏛️", cardX + cardW / 2, cardY + 11);

  ctx.font = '10.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fca5a5';
  ctx.fillText("天地开阖 · 择立名门望族 · 肇启三千年世家华章", cardX + cardW / 2, cardY + 31);

  if (state.isClanProfileLoadingFromCloud) {
    ctx.fillStyle = 'rgba(59, 130, 246, 0.25)';
    roundRect(ctx, cardX + 14, cardY + 46, cardW - 28, 18, 4, true, true, '#60a5fa', 1);
    ctx.textAlign = 'center';
    ctx.font = '10px ' + FONT_UI;
    ctx.fillStyle = '#93c5fd';
    ctx.fillText('⏳ 正在探寻云端世家卷轴，请稍候...', cardX + cardW / 2, cardY + 49);
  }

  state.clanForm = state.clanForm || { surnameIndex: 0, provinceIndex: 0, vocationId: 'study_scholar', hallIndex: 0 };
  const form = state.clanForm;

  const surnames = (_familySystemMod && _familySystemMod.COMMON_SURNAMES) || ['王', '李', '张', '刘', '陈', '杨', '黄', '赵', '周', '吴', '徐', '孙', '胡', '朱', '高', '林'];
  const provinces = (_familySystemMod && _familySystemMod.PROVINCE_LIST) || ['河南', '山东', '广东', '浙江', '江苏', '四川', '湖北', '湖南', '河北', '安徽', '福建', '陕西'];
  const vocations = (_familySystemMod && _familySystemMod.VOCATION_ORIGIN_PROFILES) || {};

  const curSurname = surnames[Math.abs(form.surnameIndex) % surnames.length];
  const curProvince = provinces[Math.abs(form.provinceIndex) % provinces.length];
  const famousHalls = (_familySystemMod && _familySystemMod.FAMOUS_HALL_MAPPING && _familySystemMod.FAMOUS_HALL_MAPPING[curSurname]) || [`${curSurname}氏堂`, '清廉堂', '敦睦堂'];
  const curHall = famousHalls[Math.abs(form.hallIndex) % famousHalls.length] || `${curSurname}氏堂`;

  const lineage = (_familySystemMod && typeof _familySystemMod.getClanLineageDocket === 'function')
    ? _familySystemMod.getClanLineageDocket(curSurname, null, curProvince, curHall)
    : null;
  const titleChoronym = (lineage && lineage.choronym) ? lineage.choronym : curProvince;

  // 2. 华夏名门快捷席位 (Famous Historical Great Clan Presets)
  let curY = cardY + (state.isClanProfileLoadingFromCloud ? 68 : 48);
  const famousClansList = [
    { label: '👑 琅琊王', sIdx: 0, pIdx: 1, hIdx: 0, vKey: 'study_scholar' },
    { label: '📜 颍川陈', sIdx: 4, pIdx: 0, hIdx: 0, vKey: 'study_scholar' },
    { label: '⚖️ 弘农杨', sIdx: 5, pIdx: 11, hIdx: 0, vKey: 'study_scholar' },
    { label: '⚔️ 汝南袁', sIdx: 7, pIdx: 0, hIdx: 0, vKey: 'trade_craft' },
    { label: '🏛️ 清河崔', sIdx: 15, pIdx: 8, hIdx: 0, vKey: 'study_scholar' },
    { label: '🌟 百家姓', sIdx: 1, pIdx: 0, hIdx: 0, vKey: 'study_scholar' }
  ];

  const pillRowW = cardW - 24;
  const pillGap = 5;
  const pillW = Math.floor((pillRowW - pillGap * 5) / 6);
  const pillH = 22;

  for (let fi = 0; fi < famousClansList.length; fi++) {
    const fc = famousClansList[fi];
    const isFcSel = (fi < 5 && curSurname === surnames[fc.sIdx]) || (fi === 5 && !famousClansList.slice(0, 5).some(c => curSurname === surnames[c.sIdx]));
    const fx = cardX + 12 + fi * (pillW + pillGap);

    drawTactileButton(ctx, {
      id: `clan_famous_preset_${fi}`,
      x: fx,
      y: curY,
      w: pillW,
      h: pillH,
      radius: 3,
      bg: isFcSel ? '#78350f' : 'rgba(28, 20, 26, 0.9)',
      border: isFcSel ? '#fde047' : '#5c4538',
      borderWidth: isFcSel ? 1.5 : 1,
      text: fc.label,
      font: 'bold 9.5px ' + FONT_CHRONICLE,
      textColor: isFcSel ? '#fef08a' : '#cbd5e1',
      priority: 106,
      onClick: () => {
        form.surnameIndex = fc.sIdx;
        form.provinceIndex = fc.pIdx;
        form.hallIndex = fc.hIdx;
        form.vocationId = fc.vKey;
        playSoundEffect('paper');
        requestRender();
      }
    });
  }

  curY += pillH + 7;

  // 3. 核心宗门受命诏令圣卷总览 (The Master Ancestral Scroll Showcase)
  const masterScrollH = 76;
  drawElevatedCard(ctx, cardX + 12, curY, cardW - 24, masterScrollH, {
    elevation: 2,
    radius: 5,
    fill: 'rgba(28, 18, 24, 0.96)',
    borderColor: '#b45309',
    borderWidth: 1.5,
    hasCornerOrnaments: true,
    cornerLength: 6,
    cornerColor: '#d97706'
  });

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fde047';
  ctx.fillText(`【 ${titleChoronym} · ${curSurname}氏 · ${curHall} 】`, cardX + cardW / 2, curY + 6);

  ctx.font = '10px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#e2e8f0';
  const ancText = lineage ? `祖上名仕：${fitText(lineage.historicalAncestors.replace(/➔/g, '→'), cardW - 48, '10px ' + FONT_CHRONICLE)}` : '两汉名贤之后 · 华夏巨室';
  ctx.fillText(ancText, cardX + cardW / 2, curY + 25);

  if (lineage && lineage.clanPerk) {
    ctx.font = 'bold 10px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#6ee7b7';
    ctx.fillText(`独门底蕴：【${lineage.clanPerk.name}】${fitText(lineage.clanPerk.desc, cardW - 90, '10px ' + FONT_CHRONICLE)}`, cardX + cardW / 2, curY + 41);
  } else {
    ctx.font = 'italic 10px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fbbf24';
    const mottoText = lineage ? `祖训：“${fitText(lineage.motto, cardW - 48, 'italic 10px ' + FONT_CHRONICLE)}”` : '诗书传家，百代不迁。';
    ctx.fillText(mottoText, cardX + cardW / 2, curY + 41);
  }

  ctx.font = '9px ' + FONT_UI;
  ctx.fillStyle = '#a89988';
  const srcText = lineage ? `典籍史考：${lineage.historicalSource.split('《')[1] ? '《' + lineage.historicalSource.split('《')[1].split('》')[0] + '》' : lineage.historicalSource}` : '《元和姓纂》世系考';
  ctx.fillText(fitText(srcText, cardW - 36, '9px ' + FONT_UI), cardX + cardW / 2, curY + 58);

  curY += masterScrollH + 8;

  // 4. 家族姓氏选择区
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 11.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(`一、家族姓氏：【${curSurname}氏】`, cardX + 14, curY);

  drawTactileButton(ctx, {
    id: 'clan_form_s_prev',
    x: cardX + cardW - 74,
    y: curY - 2,
    w: 26,
    h: 20,
    radius: 3,
    bg: '#2d1b22',
    border: '#d97706',
    borderWidth: 1,
    text: '◀',
    font: '10px ' + FONT_UI,
    textColor: '#fef08a',
    priority: 105,
    onClick: () => {
      form.surnameIndex = (form.surnameIndex - 1 + surnames.length) % surnames.length;
      form.hallIndex = 0;
      playSoundEffect('click');
      requestRender();
    }
  });

  drawTactileButton(ctx, {
    id: 'clan_form_s_next',
    x: cardX + cardW - 42,
    y: curY - 2,
    w: 26,
    h: 20,
    radius: 3,
    bg: '#2d1b22',
    border: '#d97706',
    borderWidth: 1,
    text: '▶',
    font: '10px ' + FONT_UI,
    textColor: '#fef08a',
    priority: 105,
    onClick: () => {
      form.surnameIndex = (form.surnameIndex + 1) % surnames.length;
      form.hallIndex = 0;
      playSoundEffect('click');
      requestRender();
    }
  });

  curY += 20;
  const sChips = 5;
  const chipGap = 5;
  const sBtnW = Math.floor((cardW - 28 - (sChips - 1) * chipGap) / sChips);
  const sStartIdx = Math.floor(form.surnameIndex / sChips) * sChips;

  for (let i = 0; i < sChips; i++) {
    const sIdx = (sStartIdx + i) % surnames.length;
    const sText = surnames[sIdx];
    const isSelected = (sIdx === (form.surnameIndex % surnames.length));
    const cx = cardX + 14 + i * (sBtnW + chipGap);

    drawTactileButton(ctx, {
      id: `clan_form_s_${i}`,
      x: cx,
      y: curY,
      w: sBtnW,
      h: 22,
      radius: 3,
      bg: isSelected ? '#78350f' : '#221929',
      border: isSelected ? '#f59e0b' : '#5c4538',
      borderWidth: isSelected ? 1.5 : 1,
      text: sText,
      font: 'bold 11px ' + FONT_CHRONICLE,
      textColor: isSelected ? '#fef08a' : '#cbd5e1',
      priority: 105,
      onClick: () => {
        form.surnameIndex = sIdx;
        form.hallIndex = 0;
        playSoundEffect('click');
        requestRender();
      }
    });
  }

  // 5. 祖籍省份选择区
  curY += 28;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 11.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(`二、祖籍省份：【${curProvince}】`, cardX + 14, curY);

  drawTactileButton(ctx, {
    id: 'clan_form_p_prev',
    x: cardX + cardW - 74,
    y: curY - 2,
    w: 26,
    h: 20,
    radius: 3,
    bg: '#2d1b22',
    border: '#d97706',
    borderWidth: 1,
    text: '◀',
    font: '10px ' + FONT_UI,
    textColor: '#fef08a',
    priority: 105,
    onClick: () => {
      form.provinceIndex = (form.provinceIndex - 1 + provinces.length) % provinces.length;
      playSoundEffect('click');
      requestRender();
    }
  });

  drawTactileButton(ctx, {
    id: 'clan_form_p_next',
    x: cardX + cardW - 42,
    y: curY - 2,
    w: 26,
    h: 20,
    radius: 3,
    bg: '#2d1b22',
    border: '#d97706',
    borderWidth: 1,
    text: '▶',
    font: '10px ' + FONT_UI,
    textColor: '#fef08a',
    priority: 105,
    onClick: () => {
      form.provinceIndex = (form.provinceIndex + 1) % provinces.length;
      playSoundEffect('click');
      requestRender();
    }
  });

  curY += 20;
  const pChips = 4;
  const pBtnW = Math.floor((cardW - 28 - (pChips - 1) * chipGap) / pChips);
  const pStartIdx = Math.floor(form.provinceIndex / pChips) * pChips;

  for (let i = 0; i < pChips; i++) {
    const pIdx = (pStartIdx + i) % provinces.length;
    const pText = provinces[pIdx];
    const isSelected = (pIdx === (form.provinceIndex % provinces.length));
    const px = cardX + 14 + i * (pBtnW + chipGap);

    drawTactileButton(ctx, {
      id: `clan_form_p_${i}`,
      x: px,
      y: curY,
      w: pBtnW,
      h: 22,
      radius: 3,
      bg: isSelected ? '#78350f' : '#221929',
      border: isSelected ? '#f59e0b' : '#5c4538',
      borderWidth: isSelected ? 1.5 : 1,
      text: pText,
      font: 'bold 10.5px ' + FONT_CHRONICLE,
      textColor: isSelected ? '#fef08a' : '#cbd5e1',
      priority: 105,
      onClick: () => {
        form.provinceIndex = pIdx;
        playSoundEffect('click');
        requestRender();
      }
    });
  }

  // 6. 传世堂号推荐区
  curY += 28;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 11.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(`三、传世堂号：【${curHall}】`, cardX + 14, curY);

  curY += 19;
  const hChips = famousHalls.length;
  const hBtnW = Math.floor((cardW - 28 - (hChips - 1) * chipGap) / hChips);

  for (let i = 0; i < hChips; i++) {
    const hText = famousHalls[i];
    const isSelected = (i === (form.hallIndex % famousHalls.length));
    const hx = cardX + 14 + i * (hBtnW + chipGap);

    drawTactileButton(ctx, {
      id: `clan_form_h_${i}`,
      x: hx,
      y: curY,
      w: hBtnW,
      h: 22,
      radius: 3,
      bg: isSelected ? '#78350f' : '#221929',
      border: isSelected ? '#f59e0b' : '#5c4538',
      borderWidth: isSelected ? 1.5 : 1,
      text: hText,
      font: 'bold 10.5px ' + FONT_CHRONICLE,
      textColor: isSelected ? '#fef08a' : '#cbd5e1',
      priority: 105,
      onClick: () => {
        form.hallIndex = i;
        playSoundEffect('click');
        requestRender();
      }
    });
  }

  // 7. 家业底色选择区
  curY += 28;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 11.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("四、家业底色：万世立身之基", cardX + 14, curY);

  curY += 18;
  const vocKeys = ['study_scholar', 'trade_craft', 'medical_herb', 'iron_craft'];
  const vColW = Math.floor((cardW - 28 - chipGap) / 2);
  const vRowH = 26;

  for (let i = 0; i < 4; i++) {
    const vKey = vocKeys[i];
    const vObj = vocations[vKey] || { name: vKey, icon: '📜', desc: '' };
    const isSelected = form.vocationId === vKey;
    const col = i % 2;
    const row = Math.floor(i / 2);
    const vx = cardX + 14 + col * (vColW + chipGap);
    const vy = curY + row * (vRowH + 5);

    drawTactileButton(ctx, {
      id: `clan_form_v_${vKey}`,
      x: vx,
      y: vy,
      w: vColW,
      h: vRowH,
      radius: 3,
      bg: isSelected ? '#78350f' : 'rgba(32, 24, 38, 0.9)',
      border: isSelected ? '#f59e0b' : '#5c4538',
      borderWidth: isSelected ? 1.5 : 1,
      priority: 105,
      renderCustom: () => {
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.font = 'bold 10.5px ' + FONT_CHRONICLE;
        ctx.fillStyle = isSelected ? '#fef08a' : '#cbd5e1';
        ctx.fillText(vObj.name.split('·')[0].trim(), vx + vColW / 2, vy + vRowH / 2);
      },
      onClick: () => {
        form.vocationId = vKey;
        playSoundEffect('click');
        requestRender();
      }
    });
  }

  // 8. 提交与确认按钮 (满足 height >= 44px 且同时支持 clan_form_submit 与 clan_form_confirm)
  curY += 2 * (vRowH + 5) + 10;
  const submitH = 46;

  const handleSubmitClan = () => {
    if (state.isClanProfileLoadingFromCloud) {
      showToast('云端世家档案同步中，请稍候...', 'normal');
      return;
    }
    try {
      const openid = (_clanCloudMod && typeof _clanCloudMod.getUserOpenId === 'function')
        ? _clanCloudMod.getUserOpenId()
        : null;
      const profile = _familySystemMod.createFamilyProfile({
        surname: curSurname,
        province: curProvince,
        hallName: curHall,
        vocationId: form.vocationId,
        openid: openid
      });
      const activeChrono = (_seasonChronoMod && typeof _seasonChronoMod.getSeasonTimelineProgress === 'function')
        ? _seasonChronoMod.getSeasonTimelineProgress(Date.now())
        : null;
      const startYr = activeChrono ? activeChrono.recommendedStartYear : 100;
      profile.timeline.currentEpochIndex = 1;
      profile.timeline.currentYear = startYr;
      profile.timeline.completedEpochs = {};

      state.familyProfile = profile;
      saveClanProfile(profile);

      reportGameMilestone('clan_established', {
        familyId: profile.familyId,
        surname: curSurname,
        province: curProvince,
        hallName: curHall,
        vocationId: form.vocationId,
        openid: openid || '',
        isCustomMotto: false
      });

      playSoundEffect('fanfare');
      triggerHaptic('heavy');
      showToast(`立族大典圆满！【${profile.fullName}】开辟三千年世家长卷！`, 'gold');

      state._pendingCreationAfterClanEstablishment = false;
      state.selectedBirthYear = startYr;
      state.gameScene = 'game';
      state.activeModal = 'clan_origins_celebration';
      requestRender();
    } catch (err) {
      showToast(err.message, 'error');
    }
  };

  drawTactileButton(ctx, {
    id: 'clan_form_submit',
    x: cardX + 16,
    y: curY,
    w: cardW - 32,
    h: submitH,
    radius: 5,
    bg: 'rgba(180, 83, 9, 0.95)',
    border: '#fde047',
    borderWidth: 1.5,
    text: "✦ 焚香告庙 · 永定传世世家 ➔",
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 110,
    onClick: handleSubmitClan
  });

  // 别名注册，确保部分测试寻找 clan_form_confirm 时命中
  drawTactileButton(ctx, {
    id: 'clan_form_confirm',
    x: cardX + 16,
    y: curY,
    w: cardW - 32,
    h: submitH,
    bg: 'transparent',
    border: null,
    priority: 111,
    onClick: handleSubmitClan
  });

  // 9. 暂缓返回按钮 (满足 height >= 38px)
  curY += submitH + 8;
  drawTactileButton(ctx, {
    id: 'clan_form_cancel',
    x: cardX + Math.round((cardW - 140) / 2),
    y: curY,
    w: 140,
    h: 38,
    radius: 4,
    bg: 'rgba(28, 22, 25, 0.85)',
    border: '#6b4f3b',
    borderWidth: 1,
    text: "✕ 暂缓立族",
    font: 'bold 12px ' + FONT_CHRONICLE,
    textColor: '#a89988',
    priority: 105,
    onClick: () => {
      reportGameMilestone('clan_establishment_abandoned', {
        surname: curSurname,
        province: curProvince,
        vocationId: form.vocationId
      });
      state.activeModal = null;
      state._pendingCreationAfterClanEstablishment = false;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

function drawClanLeaderboardModal() {
  const { x: cardX, y: cardY, w: cardW, h: cardH } = getModalSafeRect(350, 520);

  ctx.save();
  ctx.fillStyle = '#111827';
  roundRect(ctx, cardX, cardY, cardW, cardH, 10, true, true, '#f59e0b', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#f59e0b');

  // 标题
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🏆 华夏世家 · 百家风华总榜", cardX + cardW / 2, cardY + 12);

  const subTab = state.clanLeaderboardSubTab || 'surname';

  // 右上角刷新按钮
  drawTactileButton({
    id: 'clan_lb_refresh_btn',
    x: cardX + cardW - 68,
    y: cardY + 8,
    w: 56,
    h: 26,
    radius: 3,
    bg: '#1f2937',
    border: '#f59e0b',
    borderWidth: 1,
    text: "🔄 刷新",
    font: 'bold 11px ' + FONT_UI,
    textColor: '#fef08a',
    priority: 110,
    onClick: () => {
      openClanLeaderboardModal(subTab, true);
    }
  });

  // 子标签页切换
  const tabW = Math.floor((cardW - 36) / 3);
  const tabH = 32;
  const tabY = cardY + 38;

  const tabs = [
    { key: 'surname', label: '📜 姓氏总榜' },
    { key: 'province', label: '🗺️ 八方籍贯榜' },
    { key: 'vocation', label: '⚖️ 四大家业榜' }
  ];

  tabs.forEach((t, idx) => {
    const tx = cardX + 14 + idx * (tabW + 4);
    const isAct = (subTab === t.key);
    drawTactileButton({
      id: `clan_lb_sub_${t.key}`,
      x: tx,
      y: tabY,
      w: tabW,
      h: tabH,
      radius: 4,
      bg: isAct ? '#78350f' : '#1f2937',
      border: isAct ? '#f59e0b' : '#4b5563',
      borderWidth: 1,
      text: t.label,
      font: 'bold 11.5px ' + FONT_CHRONICLE,
      textColor: isAct ? '#fef08a' : '#9ca3af',
      priority: 105,
      onClick: () => {
        state.clanLeaderboardSubTab = t.key;
        playSoundEffect('click');
        requestRender();
      }
    });
  });

  // 异步数据状态与内容展示
  const curContentY = tabY + tabH + 8;
  const botY = cardY + cardH - 92;

  if (state.clanLeaderboardLoading) {
    // 1. 加载中状态
    ctx.fillStyle = 'rgba(31, 41, 55, 0.65)';
    roundRect(ctx, cardX + 14, curContentY, cardW - 28, 200, 6, true, true, '#374151', 1);
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fef08a';
    ctx.fillText("⏳ 正在接引云端百家总谱...", cardX + cardW / 2, curContentY + 80);
    ctx.font = '12px ' + FONT_UI;
    ctx.fillStyle = '#9ca3af';
    ctx.fillText("校勘天下名门威望与宗亲气运中", cardX + cardW / 2, curContentY + 110);
  } else {
    // 数据源与榜单构建
    const allClans = (state.clanLeaderboardData && state.clanLeaderboardData.length)
      ? state.clanLeaderboardData
      : getAllClansForLeaderboard();

    let list = [];
    if (subTab === 'surname') {
      list = (_clanSocialMod && typeof _clanSocialMod.buildSurnameLeaderboard === 'function')
        ? _clanSocialMod.buildSurnameLeaderboard(allClans)
        : [];
    } else if (subTab === 'province') {
      list = (_clanSocialMod && typeof _clanSocialMod.buildProvinceLeaderboard === 'function')
        ? _clanSocialMod.buildProvinceLeaderboard(allClans)
        : [];
    } else {
      list = (_clanSocialMod && typeof _clanSocialMod.buildVocationLeaderboard === 'function')
        ? _clanSocialMod.buildVocationLeaderboard(allClans)
        : [];
    }

    let itemStartY = curContentY;

    // 2. 失败提示与重试卡片
    if (state.clanLeaderboardError) {
      ctx.fillStyle = 'rgba(127, 29, 29, 0.45)';
      roundRect(ctx, cardX + 14, curContentY, cardW - 28, 28, 4, true, true, '#ef4444', 1);
      ctx.textAlign = 'left';
      ctx.textBaseline = 'middle';
      ctx.font = '11px ' + FONT_UI;
      ctx.fillStyle = '#fca5a5';
      ctx.fillText(`⚠️ ${state.clanLeaderboardError} (展示本地缓存)`, cardX + 22, curContentY + 14);

      drawTactileButton({
        id: 'clan_lb_retry_btn',
        x: cardX + cardW - 74,
        y: curContentY + 3,
        w: 52,
        h: 22,
        radius: 3,
        bg: '#7f1d1d',
        border: '#f87171',
        borderWidth: 1,
        text: "重试",
        font: 'bold 10px ' + FONT_UI,
        textColor: '#fee2e2',
        priority: 106,
        onClick: () => {
          openClanLeaderboardModal(subTab, true);
        }
      });
      itemStartY += 34;
    }

    // 3. 空状态
    if (!list.length) {
      ctx.fillStyle = 'rgba(31, 41, 55, 0.65)';
      roundRect(ctx, cardX + 14, itemStartY, cardW - 28, 180, 6, true, true, '#374151', 1);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = 'bold 14px ' + FONT_CHRONICLE;
      ctx.fillStyle = '#fde68a';
      ctx.fillText("📭 暂无宗族入榜数据", cardX + cardW / 2, itemStartY + 70);
      ctx.font = '12px ' + FONT_UI;
      ctx.fillStyle = '#9ca3af';
      ctx.fillText("焚香立族，成为天下第一开基名门！", cardX + cardW / 2, itemStartY + 100);
    } else {
      // 4. 榜单列表展示 (最多展示 TOP 5 或 6)
      let curY = itemStartY;
      const rowH = 46;
      const medals = ['🥇', '🥈', '🥉', '④', '⑤', '⑥'];
      const maxRows = state.clanLeaderboardError ? 5 : 6;

      for (let i = 0; i < Math.min(maxRows, list.length); i++) {
        const item = list[i];
        const isMyItem = state.familyProfile && (
          (subTab === 'surname' && item.surname === state.familyProfile.surname) ||
          (subTab === 'province' && item.province === state.familyProfile.province) ||
          (subTab === 'vocation' && item.vocationId === state.familyProfile.vocationId)
        );

        ctx.fillStyle = isMyItem ? 'rgba(120, 53, 15, 0.45)' : 'rgba(31, 41, 55, 0.5)';
        roundRect(ctx, cardX + 14, curY, cardW - 28, rowH - 4, 4, true, true, isMyItem ? '#f59e0b' : '#374151', isMyItem ? 1.5 : 1);

        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.font = 'bold 14px ' + FONT_CHRONICLE;
        ctx.fillStyle = i < 3 ? '#fbbf24' : '#cbd5e1';
        ctx.fillText(`${medals[i]}`, cardX + 22, curY + (rowH - 4) / 2);

        let mainText = '';
        let subText = '';
        if (subTab === 'surname') {
          mainText = `【${item.surname}氏宗族】 代表堂号：${item.representativeHall || '传世堂'}`;
          subText = `总威望：${item.totalPrestige} 点 · 入驻宗门：${item.clanCount} 家`;
        } else if (subTab === 'province') {
          mainText = `【${item.province}世家】 首望姓氏：${item.topSurname || '大族'}`;
          subText = `总威望：${item.totalPrestige} 点 · 门阀总数：${item.clanCount} 门`;
        } else {
          mainText = `【${item.vocationName}】`;
          subText = `总威望：${item.totalPrestige} 点 · 承袭家族：${item.clanCount} 族`;
        }

        ctx.font = 'bold 12.5px ' + FONT_CHRONICLE;
        ctx.fillStyle = isMyItem ? '#fef08a' : '#f3f4f6';
        ctx.fillText(fitText(mainText, cardW - 120, 'bold 12.5px ' + FONT_CHRONICLE), cardX + 50, curY + 14);

        ctx.font = '11px ' + FONT_UI;
        ctx.fillStyle = '#9ca3af';
        ctx.fillText(fitText(subText, cardW - 120, '11px ' + FONT_UI), cardX + 50, curY + 29);

        if (isMyItem) {
          ctx.textAlign = 'right';
          ctx.font = 'bold 10.5px ' + FONT_CHRONICLE;
          ctx.fillStyle = '#fbbf24';
          ctx.fillText("我族所属", cardX + cardW - 24, curY + (rowH - 4) / 2);
        } else {
          ctx.textAlign = 'right';
          ctx.font = '10px ' + FONT_UI;
          ctx.fillStyle = '#6b7280';
          ctx.fillText(item.isCloud ? "【云端互联】" : "【演练示例】", cardX + cardW - 24, curY + (rowH - 4) / 2);
        }

        curY += rowH;
      }
    }
  }

  // 底部提示与操作按钮 (主按钮 h >= 44, 次级按钮 h >= 38)
  drawTactileButton({
    id: 'clan_lb_share_btn',
    x: cardX + 16,
    y: botY,
    w: cardW - 32,
    h: 44,
    radius: 4,
    bg: '#b45309',
    borderColor: '#fde047',
    borderWidth: 1.2,
    text: "📣 昭告天下 · 广传宗亲榜 (分享微信群)",
    font: 'bold 13px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 105,
    onClick: () => {
      const surname = state.familyProfile ? state.familyProfile.surname : '华夏';
      if (typeof wx !== 'undefined' && wx.shareAppMessage) {
        wx.shareAppMessage({
          title: `【${surname}氏百家总榜】我族声望赫奕，列祖列宗名震八荒，诚邀宗亲合谱！`,
          query: `action=clan_ranking&surname=${encodeURIComponent(surname)}`
        });
      }
      playSoundEffect('fanfare');
      showToast('已开启名榜昭告，邀天下同族宗亲聚首！', 'gold');
    }
  });

  drawTactileButton({
    id: 'clan_lb_close',
    x: cardX + Math.round((cardW - 140) / 2),
    y: botY + 48,
    w: 140,
    h: 38,
    radius: 4,
    bg: '#374151',
    border: '#6b7280',
    borderWidth: 1,
    text: "✕ 返回宗祠",
    font: 'bold 12px ' + FONT_CHRONICLE,
    textColor: '#f3f4f6',
    priority: 105,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

function drawMarriageInvitationModal() {
  const { x: cardX, y: cardY, w: cardW, h: cardH } = getModalSafeRect(350, 480);

  ctx.save();
  ctx.fillStyle = '#1c131a';
  roundRect(ctx, cardX, cardY, cardW, cardH, 8, true, true, '#f43f5e', 2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#fb7185');

  // 标题
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fecdd3';
  ctx.fillText("💌 世家联姻 · 喜结秦晋之好", cardX + cardW / 2, cardY + 14);

  ctx.font = '11.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fda4af';
  ctx.fillText("结两姓之好 · 守望相助 · 共享商路与名望红利", cardX + cardW / 2, cardY + 36);

  const myFam = state.familyProfile;
  let curY = cardY + 58;

  // 庚帖卷轴卡片
  const scrollH = 175;
  ctx.fillStyle = '#2a1520';
  roundRect(ctx, cardX + 14, curY, cardW - 28, scrollH, 6, true, true, '#e11d48', 1.2);

  ctx.font = 'bold 13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("📜 传世名门联姻庚帖", cardX + cardW / 2, curY + 10);

  ctx.textAlign = 'left';
  ctx.font = '12px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#ffe4e6';
  const famName = myFam ? myFam.fullName : '华夏名门';
  const genNum = (myFam && myFam.genealogyList && myFam.genealogyList.length) ? myFam.genealogyList.length : 1;
  const prest = (myFam && myFam.clanTrust && typeof myFam.clanTrust.prestigeScore === 'number') ? myFam.clanTrust.prestigeScore : 50;

  ctx.fillText(`缔约门第：${famName}`, cardX + 26, curY + 34);
  ctx.fillText(`世系渊源：已传世 ${genNum} 代 · 宗族声望：${prest} 分`, cardX + 26, curY + 54);
  ctx.fillText("缔盟誓词：“两姓联姻，一堂缔约，良缘永结，匹配同称。”", cardX + 26, curY + 74);

  ctx.font = 'bold 12px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fbbf24';
  ctx.fillText("【世交盟好永久增益】", cardX + 26, curY + 98);

  ctx.font = '11.5px ' + FONT_UI;
  ctx.fillStyle = '#fecdd3';
  ctx.fillText("• 每日结交享丰厚聘礼（首门 +25 声望，+¥2,500 礼金，随次递减）", cardX + 26, curY + 116);
  ctx.fillText("• 宗族信托公积稳步注入，兼顾门阀品第防刷平衡", cardX + 26, curY + 134);
  ctx.fillText("• 往后世代经商与化解黑天鹅危机成功率 +15%", cardX + 26, curY + 152);

  // 微信转发分享按钮 (主按钮 h: 44)
  curY += scrollH + 14;
  drawTactileButton({
    id: 'clan_marry_share',
    x: cardX + 16,
    y: curY,
    w: cardW - 32,
    h: 44,
    radius: 4,
    bg: '#be123c',
    border: '#f43f5e',
    borderWidth: 1.5,
    text: "🤝 微信转发庚帖 (邀请好友名门联姻) ➔",
    font: 'bold 13px ' + FONT_CHRONICLE,
    textColor: '#fff1f2',
    priority: 105,
    onClick: () => {
      const card = _clanSocialMod && _clanSocialMod.generateMarriageInvitationCard
        ? _clanSocialMod.generateMarriageInvitationCard(myFam)
        : null;
      if (typeof wx !== 'undefined' && typeof wx.shareAppMessage === 'function' && card) {
        wx.shareAppMessage({
          title: card.shareTitle,
          imageUrl: '',
          query: card.queryParam
        });
      }
      // 关键埋点：联姻庚帖生成与发送
      reportGameMilestone('marriage_proposal_sent', {
        familyId: myFam ? myFam.familyId : '',
        youthName: myFam ? (myFam.surname + '长子') : '长子',
        alliancesCount: (myFam && myFam.alliances) ? myFam.alliances.length : 0
      });
      showToast("庚帖已备齐！好友点击即可缔结世交！", "gold");
      playSoundEffect('fanfare');
      requestRender();
    }
  });

  // 匹配名门缔结世交 (主按钮 h: 44)
  curY += 50;
  drawTactileButton({
    id: 'clan_marry_match',
    x: cardX + 16,
    y: curY,
    w: cardW - 32,
    h: 44,
    radius: 4,
    bg: '#4c1d30',
    border: '#f59e0b',
    borderWidth: 1.2,
    text: "🕊️ 匹配天下名门 (缔结世交通好)",
    font: 'bold 12.5px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 105,
    onClick: () => {
      if (!myFam) {
        showToast("请先完成立族大典！", "error");
        return;
      }
      const allClans = getAllClansForLeaderboard();
      const candidates = allClans.filter(c => c.familyId !== myFam.familyId && c.province !== myFam.province);
      if (!candidates.length) {
        showToast("暂无可匹配的世交名门！", "info");
        return;
      }
      const peer = candidates[Math.floor(Math.random() * candidates.length)] || candidates[0];
      peer.fullName = peer.fullName || `${peer.province}·${peer.surname}氏·${peer.hallName}`;
      try {
        const res = _clanSocialMod.acceptMarriageAlliance(myFam, peer);
        if (res.success) {
          saveClanProfile(myFam);
          playSoundEffect('fanfare');
          // 关键埋点：联姻成功缔结
          reportGameMilestone('marriage_proposal_accepted', {
            familyId: myFam.familyId,
            peerFamilyId: peer.familyId,
            peerSurname: peer.surname,
            alliancesCount: res.familyA_allianceCount,
            rewardPrestige: res.rewardPrestige,
            rewardMoney: res.rewardMoney
          });
          showToast(`喜结秦晋之好！与【${peer.province}·${peer.surname}氏】结为世交！(声望+${res.rewardPrestige}, 礼金+¥${res.rewardMoney})`, 'gold');
        } else {
          showToast(res.message || "此前已结为世交！", "info");
        }
      } catch (e) {
        showToast(e.message || "缔结世交异常", "error");
      }
      requestRender();
    }
  });

  // 返回按钮 (次级按钮 h: 38)
  curY += 50;
  drawTactileButton({
    id: 'clan_marry_close',
    x: cardX + Math.round((cardW - 140) / 2),
    y: curY,
    w: 140,
    h: 38,
    radius: 4,
    bg: 'rgba(32, 20, 26, 0.85)',
    border: '#6b4f3b',
    borderWidth: 1,
    text: "✕ 返回",
    font: 'bold 12px ' + FONT_CHRONICLE,
    textColor: '#a89988',
    priority: 105,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

