    ctx.fillText(`• 宗族威望底蕴增长：+${anc.prestigeGain || 50} 分`, cardX + 30, innerY + 64);

    innerY += 92;
    ctx.textAlign = 'center';
    ctx.font = 'italic 10.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#d4c7b8';
