function drawCentennialBanquetModal() {
  const cardW = screenWidth - 28;
  const cardH = 440;
  const cardX = 14;
  const cardY = Math.max(16, Math.round((screenHeight - cardH) / 2));

  const isHanWeiB = state.year <= 500;
  const p = state.track || state.youthPath || (isHanWeiB ? 'scholar' : 'gaokao');
  const cfg = CENTENNIAL_BANQUET_CONFIGS[p] || (isHanWeiB ? CENTENNIAL_BANQUET_CONFIGS.scholar : CENTENNIAL_BANQUET_CONFIGS.default);
  const hasSpouse = !!(state.family && state.family.spouseName);

  ctx.save();
  ctx.fillStyle = '#171122';
  roundRect(ctx, cardX, cardY, cardW, cardH, 12, true, true, '#d97706', 2.2);
  drawCornerOrnaments(ctx, cardX, cardY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 15.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText(cfg.title, cardX + cardW / 2, cardY + 16);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#34d399';
  ctx.fillText(cfg.subtitle, cardX + cardW / 2, cardY + 38);

  const bBoxH = 260;
  const bBoxY = cardY + 58;
  ctx.fillStyle = '#22182c';
  roundRect(ctx, cardX + 16, bBoxY, cardW - 32, bBoxH, 8, true, true, '#d97706', 1);

  ctx.textAlign = 'left';
  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#f59e0b';
  ctx.fillText("📜 【花甲感怀 · 满座同钦】", cardX + 28, bBoxY + 14);

  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef3c7';
  for (let i = 0; i < cfg.lines.length; i++) {
    let lineText = cfg.lines[i];
    if (!hasSpouse && (lineText.indexOf('老伴') !== -1 || lineText.indexOf('伴侣') !== -1)) {
      lineText = '至交挚友举杯相视一笑：“这一辈子脚踏实地，无愧良心，无愧家国。”';
    }
    ctx.fillText(fitText(lineText, cardW - 56, '13.5px ' + FONT_CHRONICLE), cardX + 28, bBoxY + 38 + i * 22);
  }

  // 终身大满贯荣誉徽章
  const medalH = 75;
  const medalY = bBoxY + 130;
  ctx.fillStyle = '#1a1426';
  roundRect(ctx, cardX + 24, medalY, cardW - 48, medalH, 6, true, true, '#f59e0b', 1);

  ctx.font = 'bold 14px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🏅 终身德望印记：", cardX + 34, medalY + 14);

  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#cbd5e1';
  ctx.fillText("• 功勋卓著 · 门庭繁茂，亲眷宗族同享清荣", cardX + 34, medalY + 34);
  ctx.fillText("• 桃李天下 · 传帮带三代青年骨干，薪火长明不灭", cardX + 34, medalY + 52);

  // 退出寿宴按钮
  const closeBtnW = cardW - 48;
  const closeBtnH = 36;
  const closeBtnX = cardX + 24;
  const closeBtnY = cardY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'close_centennial_banquet',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#78350f',
    border: '#f59e0b',
    text: "举杯同庆 · 载誉功成 ➔",
    font: 'bold 14px ' + FONT_CHRONICLE,
    textColor: '#fff',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('bell');
      requestRender();
    }
  });

  ctx.restore();
}

function openMegaprojectConsortiaModal() {
  state.activeModal = 'megaproject_consortia';
  playSoundEffect('blueprint_unroll_foley');
  requestRender();
}

function drawMegaprojectConsortiaModal() {
  const padX = 12;
  const cardW = screenWidth - padX * 2;
  const cardH = 450;
  const startX = padX;
  const startY = Math.max(16, (screenHeight - cardH) / 2);

  ctx.save();
  // 经典工程深青色晒蓝图背景
  ctx.fillStyle = '#081726';
  roundRect(ctx, startX, startY, cardW, cardH, 12, true, true, '#0ea5e9', 2);
  drawCornerOrnaments(ctx, startX, startY, cardW, cardH, 8, '#38bdf8');

  // 工程网格暗纹 (单次合批绘制，省去数十次 stroke 调用)
  ctx.strokeStyle = 'rgba(14, 165, 233, 0.12)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  for (let x = startX + 10; x < startX + cardW; x += 20) {
    ctx.moveTo(x, startY + 10);
    ctx.lineTo(x, startY + cardH - 10);
  }
  for (let y = startY + 10; y < startY + cardH; y += 20) {
    ctx.moveTo(startX + 10, y);
    ctx.lineTo(startX + cardW - 10, y);
  }
  ctx.stroke();

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 15.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#38bdf8';
  ctx.fillText("🚀 国家战略重大专项 · 工程总览图", startX + cardW / 2, startY + 14);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#7dd3fc';
  ctx.fillText(fitText(`“铸大国重器，挺民族脊梁” · 专项统筹精力: ${state.ap || 0}⚡ | 结余资金: ¥${(state.capital || 0).toLocaleString()}`, cardW - 24, '13.5px ' + FONT_UI), startX + cardW / 2, startY + 36);

  const startListY = startY + 56;
  const bH = 80;

  for (let idx = 0; idx < NATIONAL_MEGAPROJECT_CONSORTIA.length; idx++) {
    const proj = NATIONAL_MEGAPROJECT_CONSORTIA[idx];
    const py = startListY + idx * (bH + 8);
    const curStg = getMegaprojectStage(proj.id);
    const stgInfo = MEGAPROJECT_STAGES[curStg - 1];

    ctx.fillStyle = curStg >= 4 ? '#064e3b' : '#0c2338';
    roundRect(ctx, startX + 12, py, cardW - 24, bH, 6, true, true, curStg >= 4 ? '#10b981' : proj.color, 1.2);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = '22px sans-serif';
    ctx.fillText(proj.badge, startX + 20, py + 12);

    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#f8fafc';
    ctx.fillText(fitText(`${proj.name} 【${proj.field}】`, cardW - 130, 'bold 14px ' + FONT_CHRONICLE), startX + 52, py + 10);

    ctx.font = '12.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#94a3b8';
    ctx.fillText(fitText(proj.desc, cardW - 130, '12.5px ' + FONT_CHRONICLE), startX + 52, py + 28);

    // 四阶进度指示条
    const pBarW = cardW - 145;
    const pBarH = 6;
    const pBarX = startX + 52;
    const pBarY = py + 48;
    ctx.fillStyle = '#0a1d2e';
    roundRect(ctx, pBarX, pBarY, pBarW, pBarH, 3, true, false);
    ctx.fillStyle = curStg >= 4 ? '#10b981' : '#38bdf8';
    roundRect(ctx, pBarX, pBarY, Math.max(6, (curStg / 4) * pBarW), pBarH, 3, true, false);

    ctx.font = '12px ' + FONT_CHRONICLE;
    ctx.fillStyle = curStg >= 4 ? '#34d399' : '#38bdf8';
    ctx.fillText(`阶段 ${curStg}/4：【${stgInfo.name}】`, pBarX, py + 58);

    // 攻坚推进按钮
    const btnW = 58;
    const btnH = 32;
    const btnX = startX + cardW - btnW - 20;
    const btnY = py + 24;

    if (curStg >= 4) {
      ctx.fillStyle = '#047857';
      roundRect(ctx, btnX, btnY, btnW, btnH, 3, true, true, '#10b981', 1);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = 'bold 13px ' + FONT_CHRONICLE;
      ctx.fillStyle = '#fff';
      ctx.fillText("已投产", btnX + btnW / 2, btnY + btnH / 2);
    } else {
      drawTactileButton(ctx, {
        id: `advance_proj_${proj.id}`,
        x: btnX,
        y: btnY,
        w: btnW,
        h: btnH,
        radius: 3,
        bg: '#0369a1',
        border: '#38bdf8',
        borderWidth: 1,
        text: "攻坚推进",
        font: 'bold 13px ' + FONT_CHRONICLE,
        textColor: '#fff',
        priority: 110,
        onClick: () => {
          advanceMegaprojectStage(proj.id);
        }
      });
    }
  }

  // 底部关闭
  const closeBtnW = cardW - 48;
  const closeBtnH = 32;
  const closeBtnX = startX + 24;
  const closeBtnY = startY + cardH - closeBtnH - 8;

  drawTactileButton(ctx, {
    id: 'close_megaproject_modal',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 4,
    bg: '#0f2742',
    border: '#38bdf8',
    text: "收起工程图纸 ➔",
    font: 'bold 13.5px ' + FONT_CHRONICLE,
    textColor: '#7dd3fc',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

