function openClanAcademyModal() {
  state.activeModal = 'clan_academy';
  playSoundEffect('guqin_water_flow');
  requestRender();
}

function deliverAcademyLecture(lectureId) {
  const lec = ACADEMY_LECTURES_DATABASE.find(l => l.id === lectureId);
  if (!lec) return;

  state.handledLectures = state.handledLectures || {};
  if (Array.isArray(state.handledLectures) ? state.handledLectures.includes(lectureId) : state.handledLectures[lectureId]) {
    showToast("该讲学纲领已传道授业，门生已铭记于心！", "info");
    return;
  }
  if (state.ap < 1) {
    showToast("今年精力已耗尽，请先迈入下一年！", "alert");
    return;
  }
  state.ap--;
  if (true) {
    progressThreeYearPact(15, '杏坛讲学');
  }
  if (Array.isArray(state.handledLectures)) {
    state.handledLectures.push(lectureId);
  } else {
    state.handledLectures[lectureId] = true;
  }
  lec.buff(state);

  state.activeLectureTitle = lec.title;
  playSoundEffect('bianqing_chime');
  triggerScreenShake(6, 220);
  spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 85, lec.color);
  spawnGoldSpiral(screenWidth / 2, screenHeight / 2, 28);

  addChronicleItem(state.age, state.year, `【杏坛传道】于宗族书院登坛主讲${lec.title}！门生后生肃立恭听，士林景仰！`, '杏坛讲学', 'promo');
  showToast(`讲学圆满！${lec.effectsText}`, 'gold');
  state.activeModal = null;
  requestRender();
}

function drawClanAcademyModal() {
  const padX = 14;
  const cardW = screenWidth - padX * 2;
  const cardH = 440;
  const startX = padX;
  const startY = Math.max(16, (screenHeight - cardH) / 2);

  ctx.save();
  ctx.fillStyle = '#171224';
  roundRect(ctx, startX, startY, cardW, cardH, 12, true, true, '#d97706', 2);
  drawCornerOrnaments(ctx, startX, startY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🏛️ 宗族书院 · 杏坛讲学传道阁", startX + cardW / 2, startY + 14);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#34d399';
  void CLAN_ACADEMIES;
  ctx.fillText(`“传道授业，继往开来” · 可用精力: ${state.ap || 0}⚡`, startX + cardW / 2, startY + 36);

  // 3 门治世讲学纲领
  const startListY = startY + 58;
  const lH = 92;

  ACADEMY_LECTURES_DATABASE.forEach((lec, idx) => {
    const ly = startListY + idx * (lH + 10);
    const isDone = state.handledLectures && (Array.isArray(state.handledLectures) ? state.handledLectures.includes(lec.id) : !!state.handledLectures[lec.id]);
    ctx.fillStyle = isDone ? '#1c1628' : '#22182c';
    roundRect(ctx, startX + 16, ly, cardW - 32, lH, 6, true, true, isDone ? '#475569' : lec.color, isDone ? 0.8 : 1.2);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = '18px sans-serif';
    ctx.fillText(lec.badge, startX + 26, ly + 10);

    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = isDone ? '#94a3b8' : '#fef08a';
    ctx.fillText(fitText(lec.title, cardW - 135, 'bold 14px ' + FONT_CHRONICLE), startX + 52, ly + 10);

    ctx.font = '13.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = isDone ? '#64748b' : '#cbd5e1';
    ctx.fillText(fitText(lec.motto, cardW - 135, '13.5px ' + FONT_CHRONICLE), startX + 52, ly + 28);

    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = '#94a3b8';
    ctx.fillText(fitText(lec.desc, cardW - 130, '13.5px ' + FONT_UI), startX + 52, ly + 46);

    ctx.fillStyle = lec.color;
    ctx.fillText(fitText(`⚡ 讲学回响：${lec.effectsText}`, cardW - 135, '13.5px ' + FONT_UI), startX + 52, ly + 64);

    const btnW = 54;
    const btnH = 28;
    const btnX = startX + cardW - btnW - 26;
    const btnY = ly + 32;

    if (isDone) {
      ctx.fillStyle = '#065f46';
      roundRect(ctx, btnX, btnY, btnW, btnH, 4, true, true, '#10b981', 1);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = 'bold 14px ' + FONT_UI;
      ctx.fillStyle = '#fff';
      ctx.fillText("已传道", btnX + btnW / 2, btnY + btnH / 2);
    } else {
      drawTactileButton(ctx, {
        id: `deliver_lec_${lec.id}`,
        x: btnX,
        y: btnY,
        w: btnW,
        h: btnH,
        radius: 4,
        bg: '#78350f',
        border: '#f59e0b',
        borderWidth: 1,
        text: "登坛设席",
        font: 'bold 14px ' + FONT_UI,
        textColor: '#fff',
        priority: 110,
        onClick: () => {
          deliverAcademyLecture(lec.id);
        }
      });
    }
  });

  // 底部关闭
  const closeBtnW = cardW - 48;
  const closeBtnH = 32;
  const closeBtnX = startX + 24;
  const closeBtnY = startY + cardH - closeBtnH - 8;

  drawTactileButton(ctx, {
    id: 'close_academy_modal',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#221e33',
    border: '#475569',
    text: "讲学毕 · 掩卷退席 ➔",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

