function drawNationalGrandStrategyModal() {
  const padX = 12;
  const cardW = screenWidth - padX * 2;
  const cardH = 450;
  const startX = padX;
  const startY = Math.max(16, (screenHeight - cardH) / 2);
  const matrix = calcNationalPowerMatrix();

  ctx.save();
  ctx.fillStyle = 'rgba(26, 20, 24, 0.96)';
  roundRect(ctx, startX, startY, cardW, cardH, 4, true, true, '#856447', 1.5);
  drawCornerOrnaments(ctx, startX, startY, cardW, cardH, 8, '#d97706');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🌐 盛世宏图 · 四维国力气象总览", startX + cardW / 2, startY + 14);

  ctx.font = '13px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fde68a';
  ctx.fillText(fitText(`“风云一甲子，大国定乾坤” · 综合国力定评：【${matrix.eraTier}】`, cardW - 24, '13px ' + FONT_CHRONICLE), startX + cardW / 2, startY + 36);

  // 四维国力菱形星阵图雷达展示区
  const radarH = 175;
  const radarY = startY + 56;
  ctx.fillStyle = 'rgba(38, 28, 22, 0.95)';
  roundRect(ctx, startX + 16, radarY, cardW - 32, radarH, 4, true, true, '#856447', 1);

  const cx = startX + cardW / 2;
  const cy = radarY + radarH / 2;
  const rSize = 58;

  // 绘制十字坐标轴
  ctx.strokeStyle = 'rgba(133, 100, 71, 0.4)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(cx - rSize - 15, cy);
  ctx.lineTo(cx + rSize + 15, cy);
  ctx.moveTo(cx, cy - rSize - 15);
  ctx.lineTo(cx, cy + rSize + 15);
  ctx.stroke();

  // 四维基准多边形轮廓
  ctx.strokeStyle = 'rgba(217, 119, 6, 0.3)';
  ctx.beginPath();
  ctx.moveTo(cx, cy - rSize);
  ctx.lineTo(cx + rSize, cy);
  ctx.lineTo(cx, cy + rSize);
  ctx.lineTo(cx - rSize, cy);
  ctx.closePath();
  ctx.stroke();

  // 绘制当前四维国力多边形
  const pTop = (matrix.defenseTechIndex / 100) * rSize;
  const pRight = (matrix.globalTradeIndex / 100) * rSize;
  const pBottom = (matrix.ecologyGreenIndex / 100) * rSize;
  const pLeft = (matrix.livelihoodIndex / 100) * rSize;

  ctx.fillStyle = 'rgba(217, 119, 6, 0.35)';
  ctx.strokeStyle = '#d97706';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(cx, cy - pTop);
  ctx.lineTo(cx + pRight, cy);
  ctx.lineTo(cx, cy + pBottom);
  ctx.lineTo(cx - pLeft, cy);
  ctx.closePath();
  ctx.fill();
  ctx.stroke();

  // 四维端点指示与数值
  ctx.font = 'bold 12.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#0284c7';
  ctx.fillText(`🛡️ 科技国防: ${matrix.defenseTechIndex}`, cx, cy - rSize - 12);
  ctx.fillStyle = '#d97706';
  ctx.fillText(`🌐 全球经贸: ${matrix.globalTradeIndex}`, cx + rSize + 22, cy - 2);
  ctx.fillStyle = '#15803d';
  ctx.fillText(`🌿 绿色低碳: ${matrix.ecologyGreenIndex}`, cx, cy + rSize + 4);
  ctx.fillStyle = '#b45309';
  ctx.fillText(`🌾 民生富庶: ${matrix.livelihoodIndex}`, cx - rSize - 22, cy - 2);

  // 四维国力柱状分析条
  const listY = radarY + radarH + 10;
  const bW = cardW - 32;
  const bH = 34;

  const dims = [
    { name: '🛡️ 科技自立与国防安全', val: matrix.defenseTechIndex, color: '#0284c7' },
    { name: '🌾 民生福祉与乡村全面振兴', val: matrix.livelihoodIndex, color: '#b45309' },
    { name: '🌐 全球多边经贸与话语权', val: matrix.globalTradeIndex, color: '#d97706' },
    { name: '🌿 生态文明与绿色低碳发展', val: matrix.ecologyGreenIndex, color: '#15803d' }
  ];

  dims.forEach((d, i) => {
    const dy = listY + i * (bH + 6);
    ctx.fillStyle = 'rgba(34, 25, 29, 0.95)';
    roundRect(ctx, startX + 16, dy, bW, bH, 3, true, true, '#856447', 1);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 13px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fef08a';
    ctx.fillText(`${d.name} (${d.val}分)`, startX + 26, dy + 6);

    const barW = bW - 120;
    ctx.fillStyle = '#140f13';
    roundRect(ctx, startX + 26, dy + 20, barW, 5, 2, true, false);
    ctx.fillStyle = d.color;
    roundRect(ctx, startX + 26, dy + 20, Math.max(4, (d.val / 100) * barW), 5, 2, true, false);

    ctx.textAlign = 'right';
    ctx.font = 'bold 12.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = d.color;
    ctx.fillText(d.val >= 85 ? '卓越领跑' : '稳步攻坚', startX + bW + 4, dy + 11);
  });

  const curMega = NATIONAL_MEGA_PROJECTS.find(mp => !(state.megaProjectList || []).includes(mp.id) && state.year >= mp.year) || NATIONAL_MEGA_PROJECTS[NATIONAL_MEGA_PROJECTS.length - 1];
  if (curMega) {
    const doneMega = (state.megaProjectList || []).includes(curMega.id);
    ctx.textAlign = 'center';
    ctx.font = '12.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = doneMega ? '#d97706' : '#fde68a';
    ctx.fillText(fitText(`${curMega.icon} 世纪工程【${curMega.title}】(${doneMega ? '已勋铭' : curMega.reqText})`, cardW - 24, '12.5px ' + FONT_CHRONICLE), startX + cardW / 2, startY + cardH - 52);
  }

  // 底部关闭
  const closeBtnW = cardW - 48;
  const closeBtnH = 32;
  const closeBtnX = startX + 24;
  const closeBtnY = startY + cardH - closeBtnH - 8;

  drawTactileButton(ctx, {
    id: 'close_national_strategy_matrix',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 3,
    bg: '#78350f',
    border: '#d97706',
    borderWidth: 1,
    text: "收起国力总览 ➔",
    font: 'bold 13.5px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

// ------------------------------------------
// 🏛️ 大国国策闭门沙龙·国士建言弹窗 (Statecraft Colloquium Modal)
// ------------------------------------------
function openStatecraftColloquiumModal() {
  state.activeModal = 'statecraft_colloquium';
  playSoundEffect('silk_scroll_unfurl');
  playSoundEffect('state_orchestra_fanfare');
  requestRender();
}

function adoptStatecraftMotion(motionId) {
  const mot = NATIONAL_STRATEGY_MOTIONS.find(m => m.id === motionId);
  if (!mot) return false;

  if ((state.age || 18) < 35) {
    showToast("需年满35岁、具备充足资历后方可呈递国家宏观战略建言提案！", "info");
    return false;
  }
  if (state.ap < 1) {
    showToast("今年精力已耗尽，请先迈入下一年！", "alert");
    return false;
  }
  if ((state.handledMotions || []).includes(motionId)) {
    showToast("该提案已呈递并获批复，无需重复呈递！", "alert");
    return false;
  }
  state.ap--;
  if (true) {
    progressThreeYearPact(15, '国士建言');
  }
  mot.buff(state);

  playSoundEffect('seal_stamp_heavy');
  playSoundEffect('bianzhong_chime');
  triggerScreenShake(8, 250);
  spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 90, mot.color);
  spawnGoldSpiral(screenWidth / 2, screenHeight / 2, 30);

  state.handledMotions = state.handledMotions || [];
  state.handledMotions.push(motionId);

  addChronicleItem(state.age, state.year, `【国士论道】受邀出席国家宏观战略闭门研讨会，呈递${mot.title}，获国家重大规划采纳并在全国推行！`, '国士建言', 'promo');
  showToast(`提案获国家重点规划采纳！${mot.effectsText}`, 'gold');
  state.activeModal = null;
  requestRender();
  return true;
}

function drawStatecraftColloquiumModal() {
  const padX = 14;
  const cardW = screenWidth - padX * 2;
  const cardH = 440;
  const startX = padX;
  const startY = Math.max(16, (screenHeight - cardH) / 2);

  ctx.save();
  ctx.fillStyle = '#16111f';
  roundRect(ctx, startX, startY, cardW, cardH, 12, true, true, '#d97706', 2);
  drawCornerOrnaments(ctx, startX, startY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🏛️ 国策闭门研讨沙龙 · 国士论道", startX + cardW / 2, startY + 14);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#34d399';
  ctx.fillText(`“治大国若烹小鲜，谋全局当立长远” · 可用精力: ${state.ap || 0}⚡`, startX + cardW / 2, startY + 36);

  const startListY = startY + 58;
  const mH = 76;

  NATIONAL_STRATEGY_MOTIONS.forEach((mot, idx) => {
    const my = startListY + idx * (mH + 8);
    const isDone = (state.handledMotions || []).includes(mot.id);

    ctx.fillStyle = isDone ? '#1c1728' : '#23182e';
    roundRect(ctx, startX + 16, my, cardW - 32, mH, 6, true, true, isDone ? '#475569' : mot.color, 1.2);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = isDone ? '#94a3b8' : '#fef08a';
    ctx.fillText(fitText(`${mot.pillar} ${mot.title}`, cardW - 120, 'bold 14px ' + FONT_CHRONICLE), startX + 28, my + 8);

    ctx.font = '13.5px ' + FONT_UI;
    ctx.fillStyle = isDone ? '#64748b' : '#cbd5e1';
    ctx.fillText(fitText(mot.desc, cardW - 120, '13.5px ' + FONT_UI), startX + 28, my + 26);

    ctx.fillStyle = mot.color;
    ctx.fillText(fitText(`⚡ 采纳成效：${mot.effectsText}`, cardW - 120, '13.5px ' + FONT_UI), startX + 28, my + 44);

    const btnW = 54;
    const btnH = 26;
    const btnX = startX + cardW - btnW - 26;
    const btnY = my + 22;

    if (isDone) {
      ctx.fillStyle = '#334155';
      roundRect(ctx, btnX, btnY, btnW, btnH, 4, true, true, '#475569', 1);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = 'bold 14px ' + FONT_UI;
      ctx.fillStyle = '#94a3b8';
      ctx.fillText("已呈批", btnX + btnW / 2, btnY + btnH / 2);
    } else {
      drawTactileButton(ctx, {
        id: `adopt_motion_${mot.id}`,
        x: btnX,
        y: btnY,
        w: btnW,
        h: btnH,
        radius: 4,
        bg: '#78350f',
        border: '#f59e0b',
        borderWidth: 1,
        text: "呈递提案",
        font: 'bold 14px ' + FONT_UI,
        textColor: '#fff',
        priority: 110,
        onClick: () => {
          adoptStatecraftMotion(mot.id);
        }
      });
    }
  });

  // 底部关闭
  const closeBtnW = cardW - 48;
  const closeBtnH = 32;
  const closeBtnX = startX + 24;
  const closeBtnY = startY + cardH - closeBtnH - 8;

  drawTactileButton(ctx, {
    id: 'close_statecraft_colloquium',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#221e33',
    border: '#475569',
    text: "研讨毕 · 拱手退席 ➔",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

// ------------------------------------------
// 🗺️ 九州治略万象舆图弹窗 (Nine Provinces Atlas Modal)
// ------------------------------------------
function openNineProvincesAtlasModal() {
  state.activeModal = 'nine_provinces_atlas';
  playSoundEffect('horn_call_majestic');
  spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 105, 'rgba(14, 165, 233, 0.45)');
  spawnGoldSpiral(screenWidth / 2, screenHeight / 2, 35);
  requestRender();
}

function drawNineProvincesAtlasModal() {
  const padX = 12;
  const cardW = screenWidth - padX * 2;
  const cardH = 460;
  const startX = padX;
  const startY = Math.max(14, (screenHeight - cardH) / 2);

  ctx.save();
  ctx.fillStyle = 'rgba(26, 20, 24, 0.96)';
  roundRect(ctx, startX, startY, cardW, cardH, 4, true, true, '#856447', 1.5);
  drawCornerOrnaments(ctx, startX, startY, cardW, cardH, 8, '#d97706');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🗺️ 九州治略万象舆图 · 九大增长极展布", startX + cardW / 2, startY + 12);

  ctx.font = '13px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fde68a';
  ctx.fillText("“胸有丘壑掌枢机，经略九州定乾坤” · 国家战略腹地全息展布", startX + cardW / 2, startY + 34);

  // 九大战略增长极网格展示区 (3列 x 3行)
  const gridX = startX + 10;
  const gridY = startY + 54;
  const colW = Math.floor((cardW - 20 - 10) / 3);
  const rowH = 76;
  const gap = 5;

  NINE_PROVINCES_ATLAS.forEach((reg, idx) => {
    const cIdx = idx % 3;
    const rIdx = Math.floor(idx / 3);
    const rx = gridX + cIdx * (colW + gap);
    const ry = gridY + rIdx * (rowH + gap);

    ctx.fillStyle = 'rgba(38, 28, 22, 0.95)';
    roundRect(ctx, rx, ry, colW, rowH, 3, true, true, '#856447', 1);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 13px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fef08a';
    ctx.fillText(`${reg.badge} ${reg.name.substring(0, 4)}`, rx + 5, ry + 6);

    ctx.font = '12px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#d97706';
    ctx.fillText(fitText(reg.focus, colW - 10, '12px ' + FONT_CHRONICLE), rx + 5, ry + 22);

    // 协同度进度条
    const barW = colW - 10;
    const barH = 5;
    const barY = ry + 40;
    ctx.fillStyle = '#140f13';
    roundRect(ctx, rx + 5, barY, barW, barH, 2, true, false);
    ctx.fillStyle = '#d97706';
    roundRect(ctx, rx + 5, barY, Math.round(barW * (reg.coordination / 100)), barH, 2, true, false);

    ctx.font = 'bold 12px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#8c7662';
    ctx.fillText(`协同度: ${reg.coordination}%`, rx + 5, ry + 52);
  });

  // 跨区重大战略调度操作按钮区
  const opsY = startY + cardH - 104;
  ctx.fillStyle = 'rgba(34, 25, 29, 0.95)';
  roundRect(ctx, startX + 10, opsY, cardW - 20, 60, 4, true, true, '#856447', 1);

  ctx.textAlign = 'left';
  ctx.font = 'bold 13px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("⚡ 跨区重大战略联动调度（消耗 1 ⚡）:", startX + 16, opsY + 8);

  const btnW = Math.floor((cardW - 36) / 2);
  const btnH = 26;
  const btn1X = startX + 14;
  const btn1Y = opsY + 26;
  const btn2X = btn1X + btnW + 8;
  const btn2Y = btn1Y;

  // 调度1：东数西算
  drawTactileButton(ctx, {
    id: 'synergy_data_calc',
    x: btn1X,
    y: btn1Y,
    w: btnW,
    h: btnH,
    radius: 3,
    bg: '#78350f',
    border: '#d97706',
    borderWidth: 1,
    text: "🚀 调度【东数西算】",
    font: 'bold 12.5px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      dispatchRegionalSynergy('east_data_west_calc');
    }
  });

  // 调度2：西电东送
  drawTactileButton(ctx, {
    id: 'synergy_power_trans',
    x: btn2X,
    y: btn2Y,
    w: btnW,
    h: btnH,
    radius: 3,
    bg: '#2a1a14',
    border: '#856447',
    borderWidth: 1,
    text: "⚡ 调度【西电东送】",
    font: 'bold 12.5px ' + FONT_CHRONICLE,
    textColor: '#fde68a',
    priority: 100,
    onClick: () => {
      dispatchRegionalSynergy('west_power_east_trans');
    }
  });

  // 底部关闭按钮
  const closeBtnW = cardW - 40;
  const closeBtnH = 30;
  const closeBtnX = startX + 20;
  const closeBtnY = startY + cardH - closeBtnH - 6;

  drawTactileButton(ctx, {
    id: 'close_nine_provinces_atlas',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 3,
    bg: '#221815',
    border: '#856447',
    borderWidth: 1,
    text: "收起万象舆图 ➔",
    font: 'bold 13px ' + FONT_CHRONICLE,
    textColor: '#c8bbae',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

