// 👑 家族万世谱系评级大典弹窗 (Clan Legacy Celebration Modal)
// ------------------------------------------
function openClanLegacyCelebrationModal() {
  state.activeModal = 'clan_legacy_celebration';
  playSoundEffect('state_orchestra_fanfare');
  playSoundEffect('temple_bell_reverb');
  spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 120, '#d97706');
  spawnGoldSpiral(screenWidth / 2, screenHeight / 2, 45);
  requestRender();
}

function drawClanLegacyCelebrationModal() {
  const padX = 14;
  const cardW = screenWidth - padX * 2;
  const cardH = 450;
  const startX = padX;
  const startY = Math.max(14, (screenHeight - cardH) / 2);
  const matrix = calcClanLegacyIndex();

  ctx.save();
  ctx.fillStyle = '#1a1026';
  roundRect(ctx, startX, startY, cardW, cardH, 12, true, true, '#d97706', 2);
  drawCornerOrnaments(ctx, startX, startY, cardW, cardH, 8, '#f59e0b');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 16px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("👑 家族万世谱系定评 · 千秋勋名盛典", startX + cardW / 2, startY + 16);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#f59e0b';
  ctx.fillText("“源远流长，德配天地；积善成德，万世永昌”", startX + cardW / 2, startY + 38);

  // 核心定评勋位大卡片
  const tierY = startY + 58;
  const tierH = 80;
  ctx.fillStyle = '#2d1844';
  roundRect(ctx, startX + 16, tierY, cardW - 32, tierH, 8, true, true, '#f59e0b', 1.5);

  ctx.font = 'bold 20px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fde047';
  ctx.fillText(matrix.tier, startX + cardW / 2, tierY + 14);

  ctx.font = 'bold 14px ' + FONT_MONO;
  ctx.fillStyle = '#cbd5e1';
  ctx.fillText(`家族宗族万世定评总分: ${matrix.score} 分`, startX + cardW / 2, tierY + 44);

  // 史官定评
  const descY = tierY + tierH + 12;
  const descH = 120;
  ctx.fillStyle = '#221433';
  roundRect(ctx, startX + 16, descY, cardW - 32, descH, 8, true, true, '#b45309', 1);

  ctx.textAlign = 'left';
  ctx.font = '13.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  wrapText(ctx, `太史公赞曰：${matrix.desc}`, startX + 26, descY + 14, cardW - 52, 20);

  // 族谱四维统计
  const statY = descY + descH + 10;
  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#94a3b8'; ctx.textAlign = 'center';
  ctx.fillText(fitText(`📜 家训采纳: ${matrix.preceptsCount} 条 | 🎖️ 国家勋章: ${matrix.medalsCount} 枚 | 🏛️ 史诗纪略: ${matrix.chroniclesCount} 回`, cardW - 32, '13.5px ' + FONT_UI), startX + cardW / 2, statY);

  // 终局封册大典按钮
  const closeBtnW = cardW - 48;
  const closeBtnH = 36;
  const closeBtnX = startX + 24;
  const closeBtnY = startY + cardH - closeBtnH - 14;

  drawTactileButton(ctx, {
    id: 'close_clan_legacy_celebration',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 6,
    bg: '#b45309',
    border: '#f59e0b',
    text: "封册圆满 · 阅览大国人生终卷 ➔",
    font: 'bold 14px ' + FONT_UI,
    textColor: '#fff',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      triggerEndgameModal();
    }
  });

  ctx.restore();
}


// ------------------------------------------
