// ==========================================
// 🌊 V22 生平命途波澜水墨折线长卷 (Life Trajectory Wave Chart)
// ==========================================
function recordLifeWaveHistoryPoint() {
  const curWaveScore = Math.round(
    ((state.capital || 0) / 10000) * 0.15 +
    getStat("rep", 0) * 0.35 +
    getStat("resilience", 50) * 0.30 +
    getStat("clean", 50) * 0.10 +
    getStat("iq", 50) * 0.10
  );
  state.lifeWaveHistory = state.lifeWaveHistory || [];
  const latestChron = (state.chronicleHistory && state.chronicleHistory.length > 0) ? state.chronicleHistory[0].text : '履职笃行，深耕细作';
  state.lifeWaveHistory.push({
    age: state.age,
    year: state.year,
    score: curWaveScore,
    resilience: state.resilience || 50,
    title: state.jobTitle || '履职筑梦',
    note: latestChron
  });
  if (state.lifeWaveHistory.length > 120) {
    state.lifeWaveHistory.shift();
  }
}

function selectWaveHistoryPoint(pt) {
  state.selectedWavePoint = pt;
  playSoundEffect('guzheng_harmonic_pluck');
  triggerHaptic('light');
  requestRender();
}

function openLifeWaveModal() {
  state.activeModal = 'life_wave';
  playSoundEffect('guzheng_harmonic_pluck');
  spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 120, '#6366f1');
  spawnGoldSpiral(screenWidth / 2, screenHeight / 2, 35);
  requestRender();
}

const WAVE_COORDS_SCRATCH = [];
const DEFAULT_WAVE_PTS = [
  { age: 0, score: 50 },
  { age: 18, score: 50 }
];

function drawLifeTrajectoryWaveChart(ctx, chartX, chartY, chartW, chartH, history) {
  let pts = history;
  if (!pts || pts.length === 0) {
    DEFAULT_WAVE_PTS[1].age = state.age || 18;
    DEFAULT_WAVE_PTS[1].score = Math.round(((state.capital || 0) / 10000) * 0.15 + getStat("rep", 0) * 0.35 + getStat("resilience", 50) * 0.30 + 10);
    pts = DEFAULT_WAVE_PTS;
  }

  ctx.save();
  // 水墨背景底框
  ctx.fillStyle = '#060a12';
  roundRect(ctx, chartX, chartY, chartW, chartH, 8, true, true, '#4f46e5', 1);

  // 坐标边界计算
  const n = pts.length;
  let minScore = 9999, maxScore = -9999;
  for (let i = 0; i < n; i++) {
    const sc = pts[i].score;
    if (sc < minScore) minScore = sc;
    if (sc > maxScore) maxScore = sc;
  }
  if (minScore === maxScore) { minScore -= 10; maxScore += 20; }
  const padBottom = 26;
  const padTop = 20;
  const padSide = 32;
  const plotW = chartW - padSide * 2;
  const plotH = chartH - padTop - padBottom;

  const minAge = pts[0].age || 0;
  const maxAge = Math.max(pts[n - 1].age || 18, minAge + 1);

  // 绘制水墨网格线
  ctx.strokeStyle = 'rgba(99, 102, 241, 0.18)';
  ctx.lineWidth = 1;
  for (let i = 0; i <= 4; i++) {
    const gy = chartY + padTop + (plotH / 4) * i;
    ctx.beginPath();
    ctx.moveTo(chartX + padSide, gy);
    ctx.lineTo(chartX + chartW - padSide, gy);
    ctx.stroke();

    const scoreTick = Math.round(maxScore - (i / 4) * (maxScore - minScore));
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    ctx.font = '13.5px ' + FONT_MONO;
    ctx.fillStyle = '#64748b';
    ctx.fillText(scoreTick + '', chartX + padSide - 4, gy);
  }

  // 零分配映射点坐标
  while (WAVE_COORDS_SCRATCH.length < n) {
    WAVE_COORDS_SCRATCH.push({ x: 0, y: 0, p: null });
  }
  const xSpan = (maxAge - minAge) || 1;
  const ySpan = (maxScore - minScore) || 1;
  for (let i = 0; i < n; i++) {
    const p = pts[i];
    const s = WAVE_COORDS_SCRATCH[i];
    s.x = chartX + padSide + ((p.age - minAge) / xSpan) * plotW;
    s.y = chartY + padTop + plotH - ((p.score - minScore) / ySpan) * plotH;
    s.p = p;
  }

  // 渐变面积填充
  if (n > 1) {
    ctx.beginPath();
    const baseY = chartY + padTop + plotH;
    ctx.moveTo(WAVE_COORDS_SCRATCH[0].x, baseY);
    for (let i = 0; i < n; i++) {
      ctx.lineTo(WAVE_COORDS_SCRATCH[i].x, WAVE_COORDS_SCRATCH[i].y);
    }
    ctx.lineTo(WAVE_COORDS_SCRATCH[n - 1].x, baseY);
    ctx.closePath();

    const areaGrad = ctx.createLinearGradient(0, chartY + padTop, 0, chartY + padTop + plotH);
    areaGrad.addColorStop(0, 'rgba(251, 191, 36, 0.28)');
    areaGrad.addColorStop(0.6, 'rgba(99, 102, 241, 0.15)');
    areaGrad.addColorStop(1, 'rgba(99, 102, 241, 0.01)');
    ctx.fillStyle = areaGrad;
    ctx.fill();
  }

  // 水墨金线主轨迹
  ctx.beginPath();
  ctx.moveTo(WAVE_COORDS_SCRATCH[0].x, WAVE_COORDS_SCRATCH[0].y);
  for (let i = 1; i < n; i++) {
    ctx.lineTo(WAVE_COORDS_SCRATCH[i].x, WAVE_COORDS_SCRATCH[i].y);
  }
  ctx.strokeStyle = '#fbbf24';
  ctx.lineWidth = 2.2;
  ctx.stroke();

  // 绘制关键转折节点
  let highestIdx = 0, lowestIdx = 0;
  for (let i = 1; i < n; i++) {
    if (pts[i].score > pts[highestIdx].score) highestIdx = i;
    if (pts[i].score < pts[lowestIdx].score) lowestIdx = i;
  }

  for (let idx = 0; idx < n; idx++) {
    const c = WAVE_COORDS_SCRATCH[idx];
    const isPeak = idx === highestIdx && n > 3;
    const isValley = idx === lowestIdx && n > 3;
    const isLatest = idx === n - 1;

    if (isPeak || isValley || isLatest || n <= 15 || idx % 2 === 0) {
      const isSel = state.selectedWavePoint && state.selectedWavePoint.age === c.p.age;
      drawTactileButton(ctx, {
        id: 'wave_node_' + c.p.age,
        x: c.x - 12,
        y: c.y - 12,
        w: 24,
        h: 24,
        bg: 'transparent',
        border: null,
        priority: 62,
        onClick: () => {
          selectWaveHistoryPoint(c.p);
        },
        renderContent: (cctx, isPressed) => {
          cctx.fillStyle = isSel ? '#facc15' : (isPeak ? '#34d399' : (isValley ? '#ef4444' : '#60a5fa'));
          cctx.beginPath();
          cctx.arc(c.x, c.y, (isSel ? 5.5 : (isLatest ? 4.5 : 3.5)) * (isPressed ? 1.25 : 1.0), 0, Math.PI * 2);
          cctx.fill();
          cctx.strokeStyle = isSel ? '#fbbf24' : '#fff';
          cctx.lineWidth = isSel ? 2.0 : 1.2;
          cctx.stroke();

          // 文本标记
          cctx.font = 'bold 14px ' + FONT_UI;
          cctx.fillStyle = isPeak ? '#6ee7b7' : (isValley ? '#fca5a5' : '#93c5fd');
          cctx.textAlign = 'center';
          const label = isPeak ? '👑 顺遂峰值' : (isValley ? '⚡ 至暗淬炼' : `${c.p.age}岁今夕`);
          const tagY = c.y < chartY + padTop + 20 ? c.y + 12 : c.y - 8;
          cctx.fillText(label, c.x, tagY);
        }
      });
    }
  }

  // X 轴年龄刻度
  ctx.fillStyle = '#94a3b8';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillText(minAge + '岁', chartX + padSide, chartY + padTop + plotH + 6);
  ctx.fillText(Math.round((minAge + maxAge) / 2) + '岁', chartX + padSide + plotW / 2, chartY + padTop + plotH + 6);
  ctx.fillText(maxAge + '岁', chartX + padSide + plotW, chartY + padTop + plotH + 6);

  ctx.restore();
}



