function openMindfulnessModal() {
  state.activeModal = 'mindfulness_modal';
  playSoundEffect('guzheng_harmonic_pluck');
  spawnInkWashBloom(screenWidth / 2, screenHeight / 2, 100, '#818cf8');
  requestRender();
}

function drawMindfulnessModal() {
  const padX = 14;
  const cardW = screenWidth - padX * 2;
  const cardH = Math.min(520, screenHeight - 32);
  const startX = padX;
  const startY = Math.max(16, (screenHeight - cardH) / 2);

  ctx.save();
  ctx.fillStyle = 'rgba(26, 20, 24, 0.96)';
  roundRect(ctx, startX, startY, cardW, cardH, 4, true, true, '#856447', 1.5);
  drawCornerOrnaments(ctx, startX, startY, cardW, cardH, 8, '#d97706');
  drawCloudFiligreeBorders(ctx, startX, startY, cardW, cardH, '#5c3a21');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 15.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  drawTraditionalSealBadge(ctx, 'taichi', startX + cardW / 2 - 132, startY + 23, 9, '#fef08a');
  ctx.fillText("🧘 澄心静虑 · 每日三省修身堂", startX + cardW / 2, startY + 14);
  drawTraditionalSealBadge(ctx, 'taichi', startX + cardW / 2 + 132, startY + 23, 9, '#fef08a');

  ctx.font = '12.5px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#d4c7b8';
  ctx.fillText("“吾日三省吾身” · 每年可消耗1点精力澄心悟道，凝练沉毅风骨", startX + cardW / 2, startY + 35);

  // 4 大修身心法卡片
  const itemH = 70;
  const listStartY = startY + 54;
  const hasAp = (state.ap || 0) >= 1 && state.lastMindfulnessYear !== state.year;

  MINDFULNESS_DISCIPLINES.forEach((disc, idx) => {
    const iy = listStartY + idx * (itemH + 8);
    ctx.fillStyle = 'rgba(38, 28, 22, 0.95)';
    roundRect(ctx, startX + 12, iy, cardW - 24, itemH, 4, true, true, disc.color || '#856447', 1);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 14px ' + FONT_CHRONICLE;
    ctx.fillStyle = disc.color || '#fef08a';
    ctx.fillText(disc.name, startX + 22, iy + 8);

    ctx.font = '12.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#c8bbae';
    wrapText(ctx, disc.desc, startX + 22, iy + 26, cardW - 110, 14);

    // 参悟按钮
    const btnW = 68;
    const btnH = 28;
    const btnX = startX + cardW - btnW - 20;
    const btnY = iy + (itemH - btnH) / 2;

    if (hasAp) {
      drawTactileButton(ctx, {
        id: 'btn_disc_' + disc.key,
        x: btnX,
        y: btnY,
        w: btnW,
        h: btnH,
        radius: 3,
        bg: '#78350f',
        border: '#d97706',
        text: '参悟(1⚡)',
        font: 'bold 13px ' + FONT_CHRONICLE,
        textColor: '#fef08a',
        priority: 100,
        onClick: () => {
          if (state.lastMindfulnessYear === state.year) {
            showToast('今年已静坐内省过，请待来年再续！', 'info');
            return;
          }
          state.ap = Math.max(0, (state.ap || 1) - 1);
          state.lastMindfulnessYear = state.year;
          disc.action(state);
          progressThreeYearPact(12, '履职心法参悟');
          state.activeModal = null;
          requestRender();
        }
      });
    } else {
      ctx.fillStyle = '#1c1519';
      roundRect(ctx, btnX, btnY, btnW, btnH, 3, true, true, '#4a3b32', 1);
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = 'bold 12.5px ' + FONT_CHRONICLE;
      ctx.fillStyle = '#786960';
      ctx.fillText(state.lastMindfulnessYear === state.year ? '本年已悟' : '精力不足', btnX + btnW / 2, btnY + btnH / 2);
    }
  });

  // 底部关闭按钮
  const closeBtnW = cardW - 40;
  const closeBtnH = 32;
  const closeBtnX = startX + 20;
  const closeBtnY = startY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'close_mindfulness',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 4,
    bg: '#1c1519',
    border: '#6b4f3b',
    text: "暂歇参悟 · 返回案头 ➔",
    font: 'bold 13.5px ' + FONT_CHRONICLE,
    textColor: '#d4c7b8',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

