function drawKinshipTreeModal() {
  const padX = 14;
  const cardW = screenWidth - padX * 2;
  const cardH = Math.min(530, screenHeight - 32);
  const startX = padX;
  const startY = Math.max(16, (screenHeight - cardH) / 2);

  ctx.save();
  ctx.fillStyle = '#0b1120';
  roundRect(ctx, startX, startY, cardW, cardH, 12, true, true, '#f59e0b', 2);
  drawCornerOrnaments(ctx, startX, startY, cardW, cardH, 8, '#fef08a');
  drawCloudFiligreeBorders(ctx, startX, startY, cardW, cardH, '#fbbf24');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  ctx.fillText("🏡 家族亲友谱系长卷 · 温情人间", startX + cardW / 2, startY + 14);

  ctx.font = '13.5px ' + FONT_UI;
  ctx.fillStyle = '#cbd5e1';
  ctx.fillText(fitText("“枝叶繁茂，源深流长” · 记录血脉至亲、结发伴侣与师门挚友的一生守望", cardW - 24, '13.5px ' + FONT_UI), startX + cardW / 2, startY + 34);

  // 四大谱系卡片
  const isParentPassed = !!(state.handledEvents && state.handledEvents['fam_fam_parent_farewell']);
  const isGoldenWedding = !!(state.handledEvents && state.handledEvents['fam_fam_golden_wedding']);
  const hasGrandchild = !!(state.handledEvents && state.handledEvents['fam_fam_grandchild_arrival']);
  const hasSpouseKin = !!(state.family && state.family.spouseName);
  const hasChildKin = !!(state.family && ((state.family.children && state.family.children.length > 0) || state.family.childName));
  const childName = hasChildKin ? (state.family.childName || state.family.children[0].name) : '';

  const kinCategories = [
    {
      title: '【父母双亲 · 庭训家风】',
      status: isParentPassed ? '安详辞世 · 遗训永存' : (state.age >= 38 ? '安享晚年 · 怡养天年' : '身体硬朗 · 操持家务'),
      desc: isParentPassed ? '老双亲高寿西去，留下绝笔《致儿亲笔手书》：堂堂正正做人，清清白白立世。' : '双亲时刻挂念儿女冷暖，淳朴家风始终是你在时代风浪中最温暖的港湾。',
      color: '#f59e0b'
    },
    {
      title: '【结发伴侣 · 相濡以沫】',
      status: !hasSpouseKin ? '尚未成家 · 独身立业' : (isGoldenWedding ? '四十载金婚大成' : '相伴相携 · 风雨同舟'),
      desc: !hasSpouseKin ? '当前全身心扑在事业与时代浪潮之中，静待有缘知己相逢携手。' : (isGoldenWedding ? `与【${state.family.spouseName}】携手跨越半生坎坷风霜，金婚盛宴重温红花喜糖，执子之手与子偕老。` : `与伴侣【${state.family.spouseName}】相濡以沫，默默分担柴米油盐与风霜，是最坚实的后盾。`),
      color: '#ec4899'
    },
    {
      title: '【子嗣后辈 · 薪火相传】',
      status: !hasChildKin ? '膝下尚无子嗣' : (hasGrandchild ? '三代同堂 · 弄璋之喜' : '笃学成长 · 薪火相承'),
      desc: !hasChildKin ? '膝下尚无儿女绕膝，闲暇时常提携单位与同门青年后辈，亦有一番桃李芬芳。' : (hasGrandchild ? `子嗣【${childName}】扎根国家建设一线，孙辈清脆啼哭降生，三代同堂其乐融融！` : `子嗣【${childName}】在淳正家风熏陶下茁壮成长，传承勤俭笃学门风。`),
      color: '#10b981'
    },
    {
      title: '【师门同侪 · 蝴蝶因果】',
      status: (state.butterflyNexus && state.butterflyNexus.length > 0) ? `已结成 ${state.butterflyNexus.length} 条蝴蝶因果链` : '同窗发小 · 义结金兰',
      desc: (state.butterflyNexus && state.butterflyNexus.length > 0) ? `青年时期的仗义援手与原则把关，已跨越数十年演进为坚不可摧的大国产业与师门同盟！` : '昔日同窗与发小常通音问，互勉共进，君子之交淡如水。',
      color: '#d97706'
    }
  ];

  const itemH = 68;
  const listStartY = startY + 54;

  kinCategories.forEach((cat, idx) => {
    const cy = listStartY + idx * (itemH + 8);
    ctx.fillStyle = '#140f13';
    roundRect(ctx, startX + 12, cy, cardW - 24, itemH, 4, true, true, cat.color, 1);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 13.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = cat.color;
    ctx.fillText(cat.title, startX + 22, cy + 8);

    ctx.textAlign = 'right';
    ctx.font = 'bold 12.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#fef08a';
    ctx.fillText(cat.status, startX + cardW - 24, cy + 8);

    ctx.textAlign = 'left';
    ctx.font = '12px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#d4c7b8';
    wrapText(ctx, cat.desc, startX + 22, cy + 28, cardW - 44, 13);
  });

  // 底部关闭按钮
  const closeBtnW = cardW - 40;
  const closeBtnH = 32;
  const closeBtnX = startX + 20;
  const closeBtnY = startY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'close_kinship_tree',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 4,
    bg: '#251e22',
    border: '#6b4f3b',
    text: "感念深情 · 返回案头 ➔",
    font: 'bold 13px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

