function drawCausalNexusModal() {
  const padX = 14;
  const cardW = screenWidth - padX * 2;
  const cardH = Math.min(520, screenHeight - 32);
  const startX = padX;
  const startY = Math.max(16, (screenHeight - cardH) / 2);

  ctx.save();
  ctx.fillStyle = '#1c1519';
  roundRect(ctx, startX, startY, cardW, cardH, 6, true, true, '#856447', 1.5);
  drawCornerOrnaments(ctx, startX, startY, cardW, cardH, 8, '#d97706');

  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = 'bold 15px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#fef08a';
  drawTraditionalSealBadge(ctx, 'taichi', startX + cardW / 2 - 118, startY + 23, 9, '#fef08a');
  ctx.fillText("天道罗盘 · 沧海因果星图", startX + cardW / 2, startY + 14);
  drawTraditionalSealBadge(ctx, 'taichi', startX + cardW / 2 + 118, startY + 23, 9, '#fef08a');

  ctx.font = '12px ' + FONT_CHRONICLE;
  ctx.fillStyle = '#d4c7b8';
  ctx.fillText("“草蛇灰线，伏脉千里” · 往昔少年抉择，化作今日大国风云", startX + cardW / 2, startY + 34);

  // 因果链展示区域
  const chainsList = NARRATIVE_CAUSAL_NEXUS.chains || [];
  const itemH = 68;
  const listStartY = startY + 54;

  chainsList.forEach((chain, idx) => {
    const isSeedActive = isCausalSeedActive(chain.seed);
    const isEchoTriggered = !!(state.causalEchoes && state.causalEchoes.some(e => e.includes(chain.seed) || (chain.seed === 'seed_hardtech_olympics' && e === 'echo_chip_backup_activation') || (chain.seed === 'seed_people_flood' && e === 'echo_flood_infrastructure_mandate')));
    const cy = listStartY + idx * (itemH + 8);
    if (cy + itemH > startY + cardH - 52) return;

    ctx.fillStyle = isEchoTriggered ? 'rgba(6, 78, 59, 0.4)' : (isSeedActive ? 'rgba(120, 53, 15, 0.3)' : '#140f13');
    roundRect(ctx, startX + 12, cy, cardW - 24, itemH, 4, true, true, isEchoTriggered ? '#059669' : (isSeedActive ? '#d97706' : '#6b4f3b'), 1);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'top';
    ctx.font = 'bold 13.5px ' + FONT_CHRONICLE;
    ctx.fillStyle = isEchoTriggered ? '#6ee7b7' : (isSeedActive ? '#fef08a' : '#a89988');
    ctx.fillText((isEchoTriggered ? "✨ [已应验] " : (isSeedActive ? "🌱 [潜伏中] " : "🔒 [未觉醒] ")) + chain.badge + " " + chain.name, startX + 20, cy + 8);

    ctx.font = '12px ' + FONT_CHRONICLE;
    ctx.fillStyle = '#d4c7b8';
    ctx.fillText(fitText(chain.desc, cardW - 40, '12px ' + FONT_CHRONICLE), startX + 20, cy + 26);
    ctx.fillStyle = isEchoTriggered ? '#a7f3d0' : (isSeedActive ? '#fde68a' : '#8c7d86');
    ctx.font = '11.5px ' + FONT_CHRONICLE;
    ctx.fillText(fitText("➔ " + (isEchoTriggered ? "因果回响已爆发，大国宏图深远受益" : (isSeedActive ? "因果已植入，静待历史契机破茧成蝶" : "机缘尚未萌发，系于早年立身行事之念")), cardW - 40, '11.5px ' + FONT_CHRONICLE), startX + 20, cy + 44);
  });

  // 底部关闭按钮
  const closeBtnW = cardW - 40;
  const closeBtnH = 32;
  const closeBtnX = startX + 20;
  const closeBtnY = startY + cardH - closeBtnH - 12;

  drawTactileButton(ctx, {
    id: 'close_causal_nexus',
    x: closeBtnX,
    y: closeBtnY,
    w: closeBtnW,
    h: closeBtnH,
    radius: 4,
    bg: '#7f1d1d',
    border: '#991b1b',
    text: "参透因果 · 返回案头 ➔",
    font: 'bold 13.5px ' + FONT_CHRONICLE,
    textColor: '#fef08a',
    priority: 100,
    onClick: () => {
      state.activeModal = null;
      playSoundEffect('click');
      requestRender();
    }
  });

  ctx.restore();
}

